	public static void onFernPlaced(ServerPlayer player, BlockPos pos) {
		if (player == null || pos == null || !(player.level() instanceof ServerLevel level)) {
			return;
		}

		clearCartelFernGrowth(level.dimension(), pos);

		Optional<PlayerRaceConfig> raceOptional = getRace(player);
		if (raceOptional.isEmpty()) {
			return;
		}

		PlayerRaceConfig race = raceOptional.get();
		if (!MISTER_CARTEL_49_RACE_ID.equals(sanitizePath(race.id))
				|| race.shnyaga == null
				|| !race.shnyaga.enabled
				|| !hasUnlockedAbility(player, race, RaceAbilitySlot.SHNYAGA)) {
			return;
		}

		if (!level.getBlockState(pos).is(Blocks.FERN)) {
			return;
		}

		scheduleCartelFernGrowth(level, pos, race.shnyaga);
	}

	private static InteractionResult onUseBlock(ServerPlayer player, InteractionHand hand, BlockPos pos) {
		InteractionResult womanAttack = tryReleaseWomanAttack(player, hand);
		if (womanAttack != InteractionResult.PASS) {
			return womanAttack;
		}
		InteractionResult womanResult = tryUseWomanFlowerStock(player, hand, pos);
		if (womanResult != InteractionResult.PASS) {
			return womanResult;
		}

		ItemStack stack = player.getItemInHand(hand);
		if (!stack.is(Items.BONE_MEAL)) {
			return InteractionResult.PASS;
		}

		Optional<PlayerRaceConfig> raceOptional = getRace(player);
		if (raceOptional.isEmpty()) {
			return InteractionResult.PASS;
		}

		PlayerRaceConfig race = raceOptional.get();
		if (!MISTER_CARTEL_49_RACE_ID.equals(sanitizePath(race.id))
				|| race.shnyaga == null
				|| !race.shnyaga.enabled
				|| !hasUnlockedAbility(player, race, RaceAbilitySlot.SHNYAGA)) {
			return InteractionResult.PASS;
		}

		ServerLevel level = (ServerLevel) player.level();
		if (!level.getBlockState(pos).is(Blocks.FERN)) {
			return InteractionResult.PASS;
		}

		double chance = race.shnyaga.chance > 0.0D ? race.shnyaga.chance : CARTEL_DEFAULT_SHNYAGA_TRAVKA_DROP_CHANCE;
		CARTEL_TRAVKA_GROWTH_ATTEMPTS.add(new CartelTravkaGrowthAttempt(player.getUUID(), level.dimension(), pos, level.getGameTime() + 1L, chance));
		return InteractionResult.PASS;
	}

	private static InteractionResult tryUseLittleDictatorStock(ServerPlayer player, InteractionHand hand, BlockPos pos) {
		if (player == null
				|| pos == null
				|| !(player.level() instanceof ServerLevel level)
				|| getLittleDictatorStockAbility(player) == null) {
			return InteractionResult.PASS;
		}

		BlockState state = level.getBlockState(pos);
		if (!canLittleDictatorOpenStorage(state)) {
			return InteractionResult.PASS;
		}

		MenuProvider provider = state.getMenuProvider(level, pos);
		if (provider == null) {
			BlockEntity blockEntity = level.getBlockEntity(pos);
			if (blockEntity instanceof MenuProvider menuProvider) {
				provider = menuProvider;
			}
		}
		if (provider == null) {
			return InteractionResult.PASS;
		}
		return player.openMenu(provider).isPresent() ? InteractionResult.CONSUME : InteractionResult.PASS;
	}
	public static InteractionResult tryHandleLittleDictatorUseInteraction(ServerPlayer player, InteractionHand hand, BlockHitResult hitResult) {
		BlockPos pos = hitResult == null ? null : hitResult.getBlockPos();
		InteractionResult ironMechanismResult = tryHandleLittleDictatorIronMechanism(player, hand, hitResult);
		if (ironMechanismResult != InteractionResult.PASS) {
			return ironMechanismResult;
		}
		if (shouldLittleDictatorPreserveVanillaSecondaryUse(player, hand)) {
			return InteractionResult.PASS;
		}
		InteractionResult taxChestResult = tryMarkLittleDictatorTaxChest(player, hand, pos);
		if (taxChestResult != InteractionResult.PASS) {
			return taxChestResult;
		}
		return tryUseLittleDictatorStock(player, hand, pos);
	}

	public static boolean shouldLittleDictatorPreserveVanillaSecondaryUse(ServerPlayer player, InteractionHand hand) {
		if (player == null || hand == null || !player.isSecondaryUseActive()) {
			return false;
		}
		return !player.getMainHandItem().isEmpty() || !player.getOffhandItem().isEmpty();
	}
	private static boolean tryToggleLittleDictatorIronDoor(ServerLevel level, ServerPlayer player, BlockPos pos, BlockState state, BlockHitResult hitResult) {
		if (level == null
				|| player == null
				|| state == null
				|| !state.is(Blocks.IRON_DOOR)
				|| !(state.getBlock() instanceof DoorBlock)) {
			return false;
		}
		boolean open = !state.getValue(DoorBlock.OPEN);
		BlockPos lowerPos = state.getValue(DoorBlock.HALF) == DoubleBlockHalf.UPPER ? pos.below() : pos;
		BlockPos upperPos = lowerPos.above();
		BlockState lowerState = level.getBlockState(lowerPos);
		BlockState upperState = level.getBlockState(upperPos);
		if (lowerState.is(Blocks.IRON_DOOR)) {
			level.setBlock(lowerPos, lowerState.setValue(DoorBlock.OPEN, open), Block.UPDATE_CLIENTS | Block.UPDATE_KNOWN_SHAPE);
		}
		if (upperState.is(Blocks.IRON_DOOR)) {
			level.setBlock(upperPos, upperState.setValue(DoorBlock.OPEN, open), Block.UPDATE_CLIENTS | Block.UPDATE_KNOWN_SHAPE);
		}
		level.playSound(null, lowerPos, open ? SoundEvents.IRON_DOOR_OPEN : SoundEvents.IRON_DOOR_CLOSE, SoundSource.BLOCKS, 1.0F, level.getRandom().nextFloat() * 0.1F + 0.9F);
		level.gameEvent(player, open ? GameEvent.BLOCK_OPEN : GameEvent.BLOCK_CLOSE, lowerPos);
		resyncLittleDictatorIronMechanismUse(player, level, pos, hitResult);
		return true;
	}

	private static boolean tryToggleLittleDictatorIronTrapdoor(ServerLevel level, ServerPlayer player, BlockPos pos, BlockState state, BlockHitResult hitResult) {
		if (level == null || player == null || state == null || !state.is(Blocks.IRON_TRAPDOOR) || !(state.getBlock() instanceof TrapDoorBlock)) {
			return false;
		}

		boolean open = !state.getValue(TrapDoorBlock.OPEN);
		level.setBlock(
				pos,
				state.setValue(TrapDoorBlock.OPEN, open),
				Block.UPDATE_CLIENTS | Block.UPDATE_KNOWN_SHAPE
		);
		level.playSound(null, pos, open ? SoundEvents.IRON_TRAPDOOR_OPEN : SoundEvents.IRON_TRAPDOOR_CLOSE, SoundSource.BLOCKS, 1.0F, level.getRandom().nextFloat() * 0.1F + 0.9F);
		level.gameEvent(player, open ? GameEvent.BLOCK_OPEN : GameEvent.BLOCK_CLOSE, pos);
		resyncLittleDictatorIronMechanismUse(player, level, pos, hitResult);
		return true;
	}

	private static void resyncLittleDictatorIronMechanismUse(ServerPlayer player, ServerLevel level, BlockPos pos, BlockHitResult hitResult) {
		if (level == null || pos == null) {
			return;
		}
		BlockState current = level.getBlockState(pos);
		level.sendBlockUpdated(pos, current, current, Block.UPDATE_CLIENTS);
		if (hitResult != null && hitResult.getDirection() != null) {
			BlockPos placementPos = pos.relative(hitResult.getDirection());
			BlockState placementState = level.getBlockState(placementPos);
			level.sendBlockUpdated(placementPos, placementState, placementState, Block.UPDATE_CLIENTS);
		}
	}

	public static boolean shouldRewriteLittleDictatorIronMechanismPackets(ServerPlayer receiver) {
		return receiver != null && getLittleDictatorStockAbility(receiver) != null;
	}

	public static void sendLittleDictatorIronMechanismChunkOverlay(ServerPlayer receiver, ClientboundLevelChunkWithLightPacket packet) {
		if (receiver == null || packet == null || receiver.connection == null || !shouldRewriteLittleDictatorIronMechanismPackets(receiver) || !(receiver.level() instanceof ServerLevel level)) {
			return;
		}
		LevelChunk chunk = level.getChunkSource().getChunkNow(packet.getX(), packet.getZ());
		if (chunk == null) {
			return;
		}
		BlockPos.MutableBlockPos cursor = new BlockPos.MutableBlockPos();
		int minX = chunk.getPos().getMinBlockX();
		int minZ = chunk.getPos().getMinBlockZ();
		int minY = level.getMinY();
		int maxY = level.getMaxY();
		for (int x = minX; x < minX + 16; x++) {
			for (int z = minZ; z < minZ + 16; z++) {
				for (int y = minY; y < maxY; y++) {
					cursor.set(x, y, z);
					BlockState fakeState = getLittleDictatorClientIronMechanismState(chunk.getBlockState(cursor));
					if (fakeState != null) {
						receiver.connection.send(new ClientboundBlockUpdatePacket(cursor.immutable(), fakeState));
					}
				}
			}
		}
	}
	public static boolean handleLittleDictatorIronMechanismSectionUpdate(ServerPlayer receiver, ClientboundSectionBlocksUpdatePacket packet) {
		if (receiver == null || packet == null || receiver.connection == null || getLittleDictatorStockAbility(receiver) == null) {
			return false;
		}
		List<Map.Entry<BlockPos, BlockState>> updates = new ArrayList<>();
		boolean[] hasReplacement = {false};
		packet.runUpdates((pos, state) -> {
			BlockPos immutablePos = pos.immutable();
			updates.add(Map.entry(immutablePos, state));
			if (getLittleDictatorClientIronMechanismState(state) != null) {
				hasReplacement[0] = true;
			}
		});
		if (!hasReplacement[0]) {
			return false;
		}
		for (Map.Entry<BlockPos, BlockState> update : updates) {
			BlockState fakeState = getLittleDictatorClientIronMechanismState(update.getValue());
			receiver.connection.send(new ClientboundBlockUpdatePacket(update.getKey(), fakeState == null ? update.getValue() : fakeState));
		}
		return true;
	}

	public static ClientboundBlockUpdatePacket rewriteLittleDictatorIronMechanismBlockUpdate(ServerPlayer receiver, ClientboundBlockUpdatePacket packet) {
		if (receiver == null || packet == null || getLittleDictatorStockAbility(receiver) == null) {
			return packet;
		}
		BlockState fakeState = getLittleDictatorClientIronMechanismState(packet.getBlockState());
		return fakeState == null ? packet : new ClientboundBlockUpdatePacket(packet.getPos(), fakeState);
	}
	private static BlockState getLittleDictatorClientIronMechanismState(BlockState state) {
		if (state == null) {
			return null;
		}
		if (state.is(Blocks.IRON_DOOR)) {
			return ModBlocks.DICTATOR_IRON_DOOR.defaultBlockState()
					.setValue(DoorBlock.FACING, state.getValue(DoorBlock.FACING))
					.setValue(DoorBlock.OPEN, state.getValue(DoorBlock.OPEN))
					.setValue(DoorBlock.HINGE, state.getValue(DoorBlock.HINGE))
					.setValue(DoorBlock.POWERED, state.getValue(DoorBlock.POWERED))
					.setValue(DoorBlock.HALF, state.getValue(DoorBlock.HALF));
		}
		if (state.is(Blocks.IRON_TRAPDOOR)) {
			return ModBlocks.DICTATOR_IRON_TRAPDOOR.defaultBlockState()
					.setValue(TrapDoorBlock.FACING, state.getValue(TrapDoorBlock.FACING))
					.setValue(TrapDoorBlock.OPEN, state.getValue(TrapDoorBlock.OPEN))
					.setValue(TrapDoorBlock.HALF, state.getValue(TrapDoorBlock.HALF))
					.setValue(TrapDoorBlock.POWERED, state.getValue(TrapDoorBlock.POWERED))
					.setValue(TrapDoorBlock.WATERLOGGED, state.getValue(TrapDoorBlock.WATERLOGGED));
		}
		return null;
	}

	public static InteractionResult tryHandleLittleDictatorIronMechanism(
			ServerPlayer player,
			InteractionHand hand,
			BlockHitResult hitResult
	) {
		BlockPos pos = hitResult == null ? null : hitResult.getBlockPos();
		if (player == null
				|| hand == null
				|| pos == null
				|| !(player.level() instanceof ServerLevel level)
				|| getLittleDictatorStockAbility(player) == null) {
			return InteractionResult.PASS;
		}
		BlockState state = level.getBlockState(pos);
		return tryToggleLittleDictatorIronDoor(level, player, pos, state, hitResult)
				|| tryToggleLittleDictatorIronTrapdoor(level, player, pos, state, hitResult)
				? InteractionResult.CONSUME
				: InteractionResult.PASS;
	}

	public static boolean canLittleDictatorBypassInteraction(ServerPlayer player, BlockState state) {
		return player != null
				&& state != null
				&& getLittleDictatorStockAbility(player) != null
				&& (canLittleDictatorOpenStorage(state) || canLittleDictatorToggleIronMechanism(state));
	}

	private static boolean canLittleDictatorToggleIronMechanism(BlockState state) {
		return state != null && (state.is(Blocks.IRON_DOOR) || state.is(Blocks.IRON_TRAPDOOR));
	}

	private static boolean canLittleDictatorOpenStorage(BlockState state) {
		if (state == null) {
			return false;
		}
		return state.is(Blocks.CHEST)
				|| state.is(Blocks.TRAPPED_CHEST)
				|| state.is(Blocks.BARREL)
				|| state.is(Blocks.HOPPER)
				|| state.is(Blocks.DISPENSER)
				|| state.is(Blocks.DROPPER)
				|| state.is(Blocks.CRAFTER)
				|| state.is(Blocks.SHULKER_BOX)
				|| state.getBlock() instanceof net.minecraft.world.level.block.ShulkerBoxBlock;
	}

	private static InteractionResult onUseEntity(ServerPlayer player, InteractionHand hand, Entity entity, Vec3 location) {
		InteractionResult sanctionedTrade = tryBlockLittleDictatorSanctionedTrade(player, entity);
		if (sanctionedTrade != InteractionResult.PASS) {
			return sanctionedTrade;
		}
		InteractionResult decreeInteraction = tryUseLittleDictatorDecreeOnEntity(player, hand, entity);
		if (decreeInteraction != InteractionResult.PASS) {
			return decreeInteraction;
		}
		InteractionResult markAxeInteraction = tryPickupMarkThrownAxe(player, hand, entity);
		if (markAxeInteraction != InteractionResult.PASS) {
			return markAxeInteraction;
		}
		InteractionResult donkeyInteraction = handleGennadiyDonkeyEntityUse(player, hand, entity, location);
		if (donkeyInteraction != InteractionResult.PASS) {
			return donkeyInteraction;
		}
		InteractionResult womanAttack = tryReleaseWomanAttack(player, hand);
		if (womanAttack != InteractionResult.PASS) {
			return womanAttack;
		}
		return tryUseWomanAnimalBreedStock(player, hand, entity);
	}

	private static InteractionResult tryUseWomanFlowerStock(ServerPlayer player, InteractionHand hand, BlockPos pos) {
		if (player == null
				|| pos == null
				|| hand != InteractionHand.MAIN_HAND
				|| !player.getMainHandItem().isEmpty()
				|| !(player.level() instanceof ServerLevel level)) {
			return InteractionResult.PASS;
		}

		RaceAbilityConfig stock = getWomanStockAbility(player);
		if (stock == null) {
			return InteractionResult.PASS;
		}

		BlockState state = level.getBlockState(pos);
		if (!state.is(BlockTags.FLOWERS)) {
			return InteractionResult.PASS;
		}

		long remainingCooldownTicks = getRemainingOnlineCooldownTicks(WOMAN_FLOWER_COOLDOWNS, player.getUUID());
		if (displayRemainingCooldown(player, remainingCooldownTicks)) {
			return InteractionResult.SUCCESS;
		}

		consumeWomanFlower(level, pos, state, player);
		level.sendParticles(ParticleTypes.END_ROD, pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D, 6, 0.22D, 0.22D, 0.22D, 0.02D);
		level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.GENERIC_EAT, SoundSource.PLAYERS, 0.9F, 1.0F);
		player.heal(WOMAN_FLOWER_HEAL_AMOUNT);
		startOnlineCooldown(WOMAN_FLOWER_COOLDOWNS, player.getUUID(), asTicks(getWomanFlowerCooldownSeconds(stock)));
		return InteractionResult.SUCCESS;
	}

	private static InteractionResult tryUseWomanAnimalBreedStock(ServerPlayer player, InteractionHand hand, Entity entity) {
		if (player == null
				|| entity == null
				|| hand != InteractionHand.MAIN_HAND
				|| !player.getMainHandItem().isEmpty()
				|| !(entity instanceof Animal animal)) {
			return InteractionResult.PASS;
		}

		RaceAbilityConfig stock = getWomanStockAbility(player);
		if (stock == null) {
			return InteractionResult.PASS;
		}

		if (!canWomanTriggerBreeding(animal)) {
			return InteractionResult.PASS;
		}

		long remainingCooldownTicks = getRemainingOnlineCooldownTicks(WOMAN_ANIMAL_BREED_COOLDOWNS, player.getUUID());
		if (displayRemainingCooldown(player, remainingCooldownTicks)) {
			return InteractionResult.SUCCESS;
		}

		animal.setInLove(player);
		playWomanAnimalBreedStockSound(player);
		startOnlineCooldown(WOMAN_ANIMAL_BREED_COOLDOWNS, player.getUUID(), asTicks(getWomanAnimalBreedCooldownSeconds(stock)));
		return InteractionResult.SUCCESS;
	}

	private static boolean canWomanTriggerBreeding(Animal animal) {
		if (animal == null || !animal.isAlive()) {
			return false;
		}
		if (animal.isBaby() || animal.getAge() != 0 || animal.isInLove() || !animal.canFallInLove()) {
			return false;
		}
		if (animal instanceof net.minecraft.world.entity.TamableAnimal tameable) {
			if (!tameable.isTame() || tameable.getHealth() < tameable.getMaxHealth()) {
				return false;
			}
		}
		return true;
	}

	private static void consumeWomanFlower(ServerLevel level, BlockPos pos, BlockState state, ServerPlayer player) {
		if (!(state.getBlock() instanceof DoublePlantBlock) || !state.hasProperty(DoublePlantBlock.HALF)) {
			level.destroyBlock(pos, false, player);
			return;
		}

		DoubleBlockHalf half = state.getValue(DoublePlantBlock.HALF);
		BlockPos lowerPos = half == DoubleBlockHalf.UPPER ? pos.below() : pos;
		BlockPos upperPos = lowerPos.above();
		BlockState lowerState = level.getBlockState(lowerPos);
		BlockState upperState = level.getBlockState(upperPos);
		if (lowerState.getBlock() == state.getBlock()) {
			level.destroyBlock(lowerPos, false, player);
		}
		if (upperState.getBlock() == state.getBlock()) {
			level.destroyBlock(upperPos, false, player);
		}
	}

