	private static int useMilkOligarchAttack(ServerPlayer player, PlayerRaceConfig race, RaceAbilityConfig ability) {
		if (player == null || ability == null || player.isSpectator() || !player.isAlive()) {
			return 0;
		}
		if (!hasMilkAbsoluteHeartToSpend(player)) {
			player.displayClientMessage(
					Component.literal("Нельзя активировать Абсолют с последним сердцем.")
							.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
					true
			);
			return 0;
		}
		UUID playerId = player.getUUID();
		boolean enabled = !MILK_ABSOLUTE_ATTACK_READY.remove(playerId);
		if (enabled) {
			MILK_ABSOLUTE_ATTACK_READY.add(playerId);
		}
		syncMilkAbsoluteAttackHud(player, enabled, true);
		Lg2.LOGGER.info(
				"Player {} {} milk oligarch absolute attack '{}' from race '{}'",
				player.getGameProfile().name(),
				enabled ? "armed" : "disarmed",
				ability.abilityId,
				race.id
		);
		return 1;
	}

	private static int useLittleDictatorAttack(ServerPlayer player, PlayerRaceConfig race, RaceAbilityConfig ability) {
		if (player == null || race == null || ability == null || player.isSpectator() || !player.isAlive()) {
			return 0;
		}

		if (displayGenericAbilityCooldown(player, RaceAbilitySlot.ATTACK)) {
			return 0;
		}

		ServerLevel level = player.level();
		double targetRange = positiveOrDefault(ability.activationRangeBlocks, LITTLE_DICTATOR_ATTACK_DEFAULT_TARGET_RANGE_BLOCKS);
		LivingEntity target = findLookTarget(player, targetRange);
		if (target == null || target == player || !target.isAlive()) {
			displayTargetNotSelected(player);
			return 0;
		}

		double aggroRadius = getLittleDictatorAttackAggroRadiusBlocks(ability);
		int mobStrengthDurationTicks = (int) Math.min(Integer.MAX_VALUE, Math.max(1L, asTicks(getLittleDictatorAttackMobStrengthSeconds(ability))));
		int playerSlownessDurationTicks = (int) Math.min(Integer.MAX_VALUE, Math.max(1L, asTicks(getLittleDictatorAttackPlayerSlownessSeconds(ability))));
		AABB area = target.getBoundingBox().inflate(aggroRadius);
		int redirectedCount = 0;

		for (Mob mob : level.getEntitiesOfClass(Mob.class, area, mob -> mob != null && mob.isAlive() && mob != target)) {
			if (!canLittleDictatorAttackRedirectMob(mob, target)) {
				continue;
			}
			applyLittleDictatorAttackTarget(mob, target);
			if (mobStrengthDurationTicks > 0) {
				mob.addEffect(new MobEffectInstance(MobEffects.STRENGTH, mobStrengthDurationTicks, LITTLE_DICTATOR_ATTACK_MOB_STRENGTH_LEVEL - 1, false, false, true));
			}
			redirectedCount++;
		}

		if (target instanceof ServerPlayer targetPlayer && playerSlownessDurationTicks > 0) {
			targetPlayer.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, playerSlownessDurationTicks, LITTLE_DICTATOR_ATTACK_PLAYER_SLOWNESS_LEVEL - 1, false, true, true));
		}
		spawnLittleDictatorAttackTargetParticles(level, target);
		startGenericAbilityCooldownSeconds(player, RaceAbilitySlot.ATTACK, positiveOrDefault(ability.cooldownSeconds, LITTLE_DICTATOR_ATTACK_DEFAULT_COOLDOWN_SECONDS));
		Lg2.LOGGER.info(
				"Player {} used little dictator attack '{}' from race '{}' on target {} and redirected {} mobs",
				player.getGameProfile().name(),
				ability.abilityId,
				race.id,
				target.getUUID(),
				redirectedCount
		);
		return 1;
	}

	private static void spawnLittleDictatorAttackTargetParticles(ServerLevel level, LivingEntity target) {
		if (level == null || target == null) {
			return;
		}
		Vec3 center = target.position().add(0.0D, Math.max(0.45D, target.getBbHeight() * 0.55D), 0.0D);
		level.sendParticles(ParticleTypes.ENCHANT, center.x, center.y, center.z, 12, 0.22D, 0.28D, 0.22D, 0.02D);
		level.sendParticles(ParticleTypes.CRIT, center.x, center.y + 0.08D, center.z, 8, 0.18D, 0.22D, 0.18D, 0.01D);
	}

	private static int useLittleDictatorDefense(ServerPlayer player, PlayerRaceConfig race, RaceAbilityConfig ability) {
		if (player == null || race == null || ability == null || player.isSpectator() || !player.isAlive()) {
			return 0;
		}
		if (!(player.level() instanceof ServerLevel level)) {
			return 0;
		}
		if (displayGenericAbilityCooldown(player, RaceAbilitySlot.DEFENSE)) {
			return 0;
		}

		double radius = getLittleDictatorDefenseRadiusBlocks(ability);
		long durationTicks = Math.max(1L, asTicks(getLittleDictatorDefenseDurationSeconds(ability)));
		long endTick = level.getGameTime() + durationTicks;
		int minPingMs = getLittleDictatorDefenseMinFakePingMs(ability);
		int maxPingMs = getLittleDictatorDefenseMaxFakePingMs(ability);
		Vec3 origin = player.position().add(0.0D, player.getBbHeight() * 0.5D, 0.0D);

		clearLittleDictatorPingEffect(player);
		LITTLE_DICTATOR_PING_SESSIONS.remove(player.getUUID());
		LITTLE_DICTATOR_LAST_DELAYED_PACKET_RELEASE_TICKS.remove(player.getUUID());

		for (ServerPlayer target : level.getEntitiesOfClass(ServerPlayer.class, player.getBoundingBox().inflate(radius), candidate ->
				candidate != null && candidate != player && candidate.isAlive() && !candidate.isSpectator())) {
			playLittleDictatorDefenseActivationSound(target, origin);
			if (isLittleDictatorPlayer(target)) {
				continue;
			}
			LITTLE_DICTATOR_PING_SESSIONS.put(
					target.getUUID(),
					new LittleDictatorPingSession(endTick, minPingMs, maxPingMs, 0L, minPingMs)
			);
			syncLittleDictatorDefenseOverlay(target, true, true);
		}

		LITTLE_DICTATOR_DEFENSE_WAVES.add(new LittleDictatorDefenseWaveSession(level.dimension(), origin, level.getGameTime(), level.getGameTime() + LITTLE_DICTATOR_DEFENSE_WAVE_DURATION_TICKS, radius));
		startGenericAbilityCooldownSeconds(player, RaceAbilitySlot.DEFENSE, positiveOrDefault(ability.cooldownSeconds, LITTLE_DICTATOR_DEFENSE_DEFAULT_COOLDOWN_SECONDS));
		Lg2.LOGGER.info(
				"Player {} used little dictator defense '{}' from race '{}' with radius {}",
				player.getGameProfile().name(),
				ability.abilityId,
				race.id,
				radius
		);
		return 1;
	}

	private static int useLittleDictatorUnique(ServerPlayer player, PlayerRaceConfig race, RaceAbilityConfig ability) {
		if (player == null || race == null || ability == null || player.isSpectator() || !player.isAlive()) {
			return 0;
		}
		if (!(player.level() instanceof ServerLevel level)) {
			return 0;
		}
		if (displayGenericAbilityCooldown(player, RaceAbilitySlot.UNIQUE_ABILITY)) {
			return 0;
		}
		if (LITTLE_DICTATOR_UNIQUE_SESSIONS.containsKey(player.getUUID())) {
			return 0;
		}

		long nowTick = level.getGameTime();
		long durationTicks = Math.max(1L, asTicks(getLittleDictatorUniqueDurationSeconds(ability)));
		long activeEndTick = nowTick + durationTicks;
		long endTick = activeEndTick + LITTLE_DICTATOR_UNIQUE_SHRINK_TICKS;
		long growthEndTick = Math.min(activeEndTick, nowTick + LITTLE_DICTATOR_UNIQUE_GROWTH_TICKS);
		long shockIntervalTicks = Math.max(1L, asTicks(getLittleDictatorUniqueShockIntervalSeconds(ability)));
		double radius = getLittleDictatorUniqueRadiusBlocks(ability);
		double shockTargetCountMultiplierMin = getLittleDictatorUniqueShockTargetCountMultiplierMin(ability);
		double shockTargetCountMultiplierMax = getLittleDictatorUniqueShockTargetCountMultiplierMax(ability);
		double xpPerHealth = getLittleDictatorUniqueXpPerHealth(ability);
		double foodPerHealth = getLittleDictatorUniqueFoodPerHealth(ability);
		LittleDictatorUniqueSession session = new LittleDictatorUniqueSession(
				level.dimension(),
				nowTick,
				growthEndTick,
				activeEndTick,
				endTick,
				player.position(),
				player.isNoGravity(),
				radius,
				LITTLE_DICTATOR_UNIQUE_TARGET_SCALE,
				shockTargetCountMultiplierMin,
				shockTargetCountMultiplierMax,
				shockIntervalTicks,
				xpPerHealth,
				foodPerHealth
		);

		player.stopRiding();
		lockLittleDictatorUniqueCasterMovement(player, session);
		syncLittleDictatorUniqueScale(player, 1.0D);
		for (ServerPlayer target : getLittleDictatorUniquePlayersInRadius(level, player, radius)) {
			if (target == player || target.isSpectator() || !target.isAlive()) {
				continue;
			}
			if (!hasLittleDictatorUniqueLineOfSight(level, player, target)) {
				continue;
			}
			session.gazeLockedPlayers.add(target.getUUID());
			applyLittleDictatorUniqueSlowness(target, session);
			forceLittleDictatorUniqueLookAtCaster(target, player);
		}
		LITTLE_DICTATOR_UNIQUE_SESSIONS.put(player.getUUID(), session);
		spawnLittleDictatorUniqueActivationParticles(level, player);
		startGenericAbilityCooldownSeconds(player, RaceAbilitySlot.UNIQUE_ABILITY, positiveOrDefault(ability.cooldownSeconds, LITTLE_DICTATOR_UNIQUE_DEFAULT_COOLDOWN_SECONDS));
		Lg2.LOGGER.info(
				"Player {} used little dictator unique '{}' from race '{}' with radius {}",
				player.getGameProfile().name(),
				ability.abilityId,
				race.id,
				radius
		);
		return 1;
	}

	private static int useLittleDictatorShnyaga(ServerPlayer player, PlayerRaceConfig race, RaceAbilityConfig ability) {
		if (player == null || race == null || ability == null || player.isSpectator() || !player.isAlive()) {
			return 0;
		}
		UUID playerId = player.getUUID();
		if (!LITTLE_DICTATOR_TAX_CHEST_PENDING.add(playerId)) {
			LITTLE_DICTATOR_TAX_CHEST_PENDING.remove(playerId);
			return 1;
		}
		displayLittleDictatorTaxChestPrompt(player);
		return 1;
	}

	private static void displayLittleDictatorTaxChestPrompt(ServerPlayer player) {
	if (player == null) {
		return;
	}
	player.displayClientMessage(
			Component.literal("Откройте сундук, чтобы сделать его налоговым.")
					.withStyle(style -> style.withColor(ChatFormatting.LIGHT_PURPLE).withItalic(false)),
			true
	);
}

private static InteractionResult tryMarkLittleDictatorTaxChest(ServerPlayer player, InteractionHand hand, BlockPos pos) {
	if (player == null
			|| hand != InteractionHand.MAIN_HAND
			|| pos == null
			|| !LITTLE_DICTATOR_TAX_CHEST_PENDING.contains(player.getUUID())
			|| !(player.level() instanceof ServerLevel level)) {
		return InteractionResult.PASS;
	}
	if (getLittleDictatorShnyagaAbility(player) == null) {
		LITTLE_DICTATOR_TAX_CHEST_PENDING.remove(player.getUUID());
		player.displayClientMessage(
				Component.literal("Способность ещё не куплена.")
						.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
				true
		);
		return InteractionResult.SUCCESS;
	}

	BlockState state = level.getBlockState(pos);
	if (!isLittleDictatorTaxChestBlock(state)) {
		return InteractionResult.PASS;
	}

	LITTLE_DICTATOR_TAX_CHEST_PENDING.remove(player.getUUID());
	LittleDictatorTaxChestRef ref = new LittleDictatorTaxChestRef(level.dimension(), pos);
	LITTLE_DICTATOR_TAX_CHESTS.computeIfAbsent(player.getUUID(), ignored -> new HashSet<>()).add(ref);
	saveLittleDictatorTaxChests(level.getServer());
	spawnLittleDictatorDecreeParticles(level, Vec3.atCenterOf(pos));
	syncLittleDictatorTaxChestHighlights(level.getServer(), player);
	player.displayClientMessage(
			Component.literal("Налоговый сундук назначен.")
					.withStyle(style -> style.withColor(ChatFormatting.LIGHT_PURPLE).withItalic(false)),
			true
	);

	MenuProvider provider = state.getMenuProvider(level, pos);
	if (provider == null) {
		BlockEntity blockEntity = level.getBlockEntity(pos);
		if (blockEntity instanceof MenuProvider menuProvider) {
			provider = menuProvider;
		}
	}
	return provider != null && player.openMenu(provider).isPresent() ? InteractionResult.CONSUME : InteractionResult.SUCCESS;
}

private static boolean isLittleDictatorTaxChestBlock(BlockState state) {
	return state != null && (state.is(Blocks.CHEST) || state.is(Blocks.TRAPPED_CHEST));
}

private static InteractionResult tryBlockLittleDictatorSanctionedTrade(ServerPlayer player, Entity entity) {
	if (player == null || entity == null || !isLittleDictatorSanctioned(player) || !(entity instanceof Merchant)) {
		return InteractionResult.PASS;
	}
	player.displayClientMessage(
			Component.literal("Под санкциями торговля недоступна.")
					.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
			true
	);
	return InteractionResult.FAIL;
}

private static InteractionResult tryUseLittleDictatorDecreeOnSelf(ServerPlayer player, InteractionHand hand) {
	if (player == null || hand == null || hand != InteractionHand.MAIN_HAND) {
		return InteractionResult.PASS;
	}
	ItemStack stack = player.getItemInHand(hand);
	LittleDictatorDecreeType type = getLittleDictatorDecreeType(stack);
	if (type == null) {
		return InteractionResult.PASS;
	}
	if (!isLittleDictatorPlayer(player)) {
		displayLittleDictatorDecreeForbidden(player);
		return InteractionResult.SUCCESS;
	}
	if (getLittleDictatorShnyagaAbility(player) == null) {
		player.displayClientMessage(
				Component.literal("Способность ещё не куплена.")
						.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
				true
		);
		return InteractionResult.SUCCESS;
	}
	if (type != LittleDictatorDecreeType.PROPAGANDA) {
		double targetRange = Math.max(player.blockInteractionRange(), player.entityInteractionRange());
		LivingEntity target = findLookTarget(player, targetRange);
		if (target instanceof ServerPlayer && target != player && target.isAlive()) {
			return InteractionResult.PASS;
		}
		displayTargetNotSelected(player);
		return InteractionResult.SUCCESS;
	}
	if (isDuplicateLittleDictatorDecreeUse(player)) {
		return InteractionResult.SUCCESS;
	}
	applyLittleDictatorPropaganda(player, getLittleDictatorShnyagaAbility(player));
	playLittleDictatorDecreeActivationSound(player, player);
	consumeLittleDictatorDecree(player, stack);
	return InteractionResult.SUCCESS;
}

private static void displayLittleDictatorDecreeForbidden(ServerPlayer player) {
	if (player == null) {
		return;
	}
	player.displayClientMessage(
			Component.literal("\u0412\u044b \u043d\u0435 \u043c\u043e\u0436\u0435\u0442\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u044d\u0442\u043e\u0442 \u0443\u043a\u0430\u0437.")
					.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
			true
	);
}

private static InteractionResult tryUseLittleDictatorDecreeOnEntity(ServerPlayer player, InteractionHand hand, Entity entity) {
	if (player == null || hand == null || hand != InteractionHand.MAIN_HAND || entity == null) {
		return InteractionResult.PASS;
	}
	ItemStack stack = player.getItemInHand(hand);
	LittleDictatorDecreeType type = getLittleDictatorDecreeType(stack);
	if (type == null) {
		return InteractionResult.PASS;
	}
	if (!isLittleDictatorPlayer(player)) {
		displayLittleDictatorDecreeForbidden(player);
		return InteractionResult.SUCCESS;
	}
	RaceAbilityConfig ability = getLittleDictatorShnyagaAbility(player);
	if (ability == null) {
		player.displayClientMessage(
				Component.literal(localizeAbilityNotPurchased(player, "Указы"))
						.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
				true
		);
		return InteractionResult.SUCCESS;
	}
	ServerPlayer target = resolveLittleDictatorDecreeTarget(entity, player);
	if (target == null) {
		if (type == LittleDictatorDecreeType.PROPAGANDA) {
			player.displayClientMessage(
					Component.literal("Пропаганда применяется только на себя.")
							.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
					true
			);
		} else {
			displayTargetNotSelected(player);
		}
		return InteractionResult.SUCCESS;
	}
	if (type == LittleDictatorDecreeType.PROPAGANDA) {
		player.displayClientMessage(
				Component.literal("Пропаганда применяется только на себя.")
						.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
				true
		);
		return InteractionResult.SUCCESS;
	}

	if (isDuplicateLittleDictatorDecreeUse(player)) {
		return InteractionResult.SUCCESS;
	}
	if (type == LittleDictatorDecreeType.SANCTIONS) {
		applyLittleDictatorSanctions(player, target, ability);
	} else if (type == LittleDictatorDecreeType.TAXES) {
		applyLittleDictatorTaxes(player, target, ability);
	}
	playLittleDictatorDecreeActivationSound(player, target);
	consumeLittleDictatorDecree(player, stack);
	return InteractionResult.SUCCESS;
}

private static ServerPlayer resolveLittleDictatorDecreeTarget(Entity entity, ServerPlayer user) {
	if (entity == null) {
		return null;
	}
	if (entity instanceof ServerPlayer playerTarget) {
		return playerTarget != user && playerTarget.isAlive() ? playerTarget : null;
	}
	for (Entity passenger : entity.getPassengers()) {
		ServerPlayer resolvedPassenger = resolveLittleDictatorDecreeTarget(passenger, user);
		if (resolvedPassenger != null) {
			return resolvedPassenger;
		}
	}
	Entity vehicle = entity.getVehicle();
	if (vehicle != null && vehicle != entity) {
		ServerPlayer resolvedVehicle = resolveLittleDictatorDecreeTarget(vehicle, user);
		if (resolvedVehicle != null) {
			return resolvedVehicle;
		}
	}
	return null;
}

private static void playLittleDictatorDecreeActivationSound(ServerPlayer dictator, ServerPlayer target) {
	if (dictator == null) {
		return;
	}
	long seed = dictator.level().getGameTime() ^ dictator.getUUID().getLeastSignificantBits();
	sendPersonalSound(dictator, SoundEvents.BOOK_PAGE_TURN, SoundSource.PLAYERS, dictator.position(), 0.65F, 1.0F, seed);
	if (target != null && target != dictator) {
		sendPersonalSound(target, SoundEvents.BOOK_PAGE_TURN, SoundSource.PLAYERS, target.position(), 0.65F, 1.0F, seed ^ target.getUUID().getMostSignificantBits());
	}
}

private static void applyLittleDictatorSanctions(ServerPlayer dictator, ServerPlayer target, RaceAbilityConfig ability) {
		if (dictator == null || target == null || ability == null) {
			return;
		}
		LITTLE_DICTATOR_SANCTIONS.put(
				target.getUUID(),
				new LittleDictatorSanctionsSession(
						Math.max(1L, asTicks(getLittleDictatorDecreeSanctionsDurationSeconds(ability))),
						getLittleDictatorDecreeSanctionsDropChance(ability)
				)
		);
		refreshLittleDictatorSanctionsFatigue(target);
		spawnLittleDictatorDecreeParticles((ServerLevel) target.level(), target.position().add(0.0D, target.getBbHeight() * 0.55D, 0.0D));
		dictator.displayClientMessage(
				Component.literal("Санкции наложены на " + target.getGameProfile().name() + ".")
						.withStyle(style -> style.withColor(ChatFormatting.LIGHT_PURPLE).withItalic(false)),
				true
		);
	}

	private static void applyLittleDictatorTaxes(ServerPlayer dictator, ServerPlayer target, RaceAbilityConfig ability) {
		if (dictator == null || target == null || ability == null) {
			return;
		}
		long durationTicks = Math.max(1L, asTicks(getLittleDictatorDecreeTaxesDurationSeconds(ability)));
		long intervalTicks = Math.max(1L, asTicks(getLittleDictatorDecreeTaxesIntervalSeconds(ability)));
		LittleDictatorTaxesSession existing = LITTLE_DICTATOR_TAXES.get(target.getUUID());
		if (existing != null) {
			existing.remainingTicks = durationTicks;
		} else {
			LITTLE_DICTATOR_TAXES.put(
					target.getUUID(),
					new LittleDictatorTaxesSession(
						dictator.getUUID(),
						durationTicks,
						intervalTicks
					)
			);
		}
		spawnLittleDictatorDecreeParticles((ServerLevel) target.level(), target.position().add(0.0D, target.getBbHeight() * 0.55D, 0.0D));
		dictator.displayClientMessage(
				Component.literal("Налоги наложены на " + target.getGameProfile().name() + ".")
						.withStyle(style -> style.withColor(ChatFormatting.LIGHT_PURPLE).withItalic(false)),
				true
		);
	}

	private static void applyLittleDictatorPropaganda(ServerPlayer dictator, RaceAbilityConfig ability) {
		if (dictator == null || ability == null || !(dictator.level() instanceof ServerLevel level)) {
			return;
		}
		finishLittleDictatorPropaganda(dictator, false);
		LITTLE_DICTATOR_PROPAGANDA.put(
				dictator.getUUID(),
				new LittleDictatorPropagandaSession(
						Math.max(1L, asTicks(getLittleDictatorDecreePropagandaDurationSeconds(ability))),
						getLittleDictatorDecreePropagandaTradeDiscount(ability)
				)
		);
		storeLittleDictatorPropagandaNaturalHaste(dictator, dictator.getEffect(MobEffects.HASTE));
		refreshLittleDictatorPropagandaHaste(dictator);
		spawnLittleDictatorDecreeParticles(level, dictator.position().add(0.0D, dictator.getBbHeight() * 0.55D, 0.0D));
		dictator.displayClientMessage(
				Component.literal("Пропаганда активирована.")
						.withStyle(style -> style.withColor(ChatFormatting.LIGHT_PURPLE).withItalic(false)),
				true
		);
	}

	private static boolean isDuplicateLittleDictatorDecreeUse(ServerPlayer player) {
		if (player == null || player.level() == null) {
			return false;
		}
		long nowTick = player.level().getGameTime();
		Long previousTick = LITTLE_DICTATOR_LAST_DECREE_USE_TICKS.put(player.getUUID(), nowTick);
		return previousTick != null && previousTick == nowTick;
	}

	private static void consumeLittleDictatorDecree(ServerPlayer player, ItemStack stack) {
		if (player == null || stack == null || stack.isEmpty()) {
			return;
		}
		stack.shrink(1);
		player.containerMenu.broadcastChanges();
	}

	private static void spawnLittleDictatorDecreeParticles(ServerLevel level, Vec3 center) {
		if (level == null || center == null) {
			return;
		}
		level.sendParticles(
				ParticleTypes.END_ROD,
				center.x,
				center.y,
				center.z,
				LITTLE_DICTATOR_DECREE_PARTICLE_COUNT,
				0.2D,
				0.3D,
				0.2D,
				0.03D
		);
	}

	private static ItemStack createLittleDictatorDecreeStack(LittleDictatorDecreeType type) {
		ItemStack stack = new ItemStack(ModItems.LITTLE_DICTATOR_DECREE);
		CustomData.update(DataComponents.CUSTOM_DATA, stack, tag -> {
			CompoundTag root = tag.getCompoundOrEmpty(LITTLE_DICTATOR_DECREE_DATA_TAG);
			root.putString(LITTLE_DICTATOR_DECREE_TYPE_TAG, type == null ? "" : type.id);
			tag.put(LITTLE_DICTATOR_DECREE_DATA_TAG, root);
		});
		stack.set(DataComponents.CUSTOM_NAME, getLittleDictatorDecreeName(type));
		stack.set(DataComponents.ITEM_MODEL, LITTLE_DICTATOR_DECREE_ITEM_MODEL_ID);
		ItemLore lore = ItemLore.EMPTY;
		for (Component line : getLittleDictatorDecreeLore(type)) {
			lore = lore.withLineAdded(line);
		}
		stack.set(DataComponents.LORE, lore);
		return stack;
	}

	private static MutableComponent getLittleDictatorDecreeName(LittleDictatorDecreeType type) {
		if (type == null) {
			return Component.literal("Указ").withStyle(style -> style.withColor(ChatFormatting.GOLD).withItalic(false));
		}
		String name = switch (type) {
			case SANCTIONS -> "Указ: Санкции";
			case TAXES -> "Указ: Налоги";
			case PROPAGANDA -> "Указ: Пропаганда";
		};
		return Component.literal(name).withStyle(style -> style.withColor(ChatFormatting.GOLD).withItalic(false));
	}

	private static List<Component> getLittleDictatorDecreeLore(LittleDictatorDecreeType type) {
		if (type == null) {
			return List.of(Component.literal("Особый указ диктатора.").withStyle(style -> style.withColor(ChatFormatting.GRAY).withItalic(false)));
		}
        String first = switch (type) {
            case SANCTIONS -> "ПКМ по игроку: ослабляет его добычу и отключает торговлю с жителями.";
            case TAXES -> "ПКМ по игроку: запускает регулярный сбор случайных предметов в налоговые сундуки.";
            case PROPAGANDA -> "ПКМ для себя: усиливает добычу, рыбалку, копание и торговлю.";
        };
        return List.of(Component.literal(first).withStyle(style -> style.withColor(ChatFormatting.GRAY).withItalic(false)));
	}

	private static LittleDictatorDecreeType getLittleDictatorDecreeType(ItemStack stack) {
		if (stack == null || stack.isEmpty() || !stack.is(ModItems.LITTLE_DICTATOR_DECREE)) {
			return null;
		}
		CustomData customData = stack.get(DataComponents.CUSTOM_DATA);
		if (customData == null) {
			return null;
		}
		CompoundTag root = customData.copyTag().getCompoundOrEmpty(LITTLE_DICTATOR_DECREE_DATA_TAG);
		return LittleDictatorDecreeType.byId(root.getStringOr(LITTLE_DICTATOR_DECREE_TYPE_TAG, ""));
	}

	private static void tickLittleDictatorShnyaga(MinecraftServer server) {
		if (server == null) {
			return;
		}
		if (pruneLittleDictatorTaxChests(server)) {
			saveLittleDictatorTaxChests(server);
		}
		long nowTick = server.overworld().getGameTime();
		for (ServerPlayer player : server.getPlayerList().getPlayers()) {
			tickLittleDictatorSanctions(player);
			tickLittleDictatorTaxes(server, player);
			tickLittleDictatorPropaganda(player);
			syncLittleDictatorMerchantOffers(player);
			if (LITTLE_DICTATOR_TAX_CHEST_PENDING.contains(player.getUUID()) && (nowTick + player.getId()) % 10L == 0L) {
				displayLittleDictatorTaxChestPrompt(player);
			}
			if ((nowTick + player.getId()) % 20L == 0L) {
				syncLittleDictatorTaxChestHighlights(server, player);
			}
		}
	}

	private static void tickLittleDictatorSanctions(ServerPlayer player) {
		LittleDictatorSanctionsSession session = LITTLE_DICTATOR_SANCTIONS.get(player.getUUID());
		if (session == null) {
			return;
		}
		if (--session.remainingTicks <= 0L) {
			LITTLE_DICTATOR_SANCTIONS.remove(player.getUUID());
			removeLittleDictatorSanctionsFatigue(player);
			return;
		}
		refreshLittleDictatorSanctionsFatigue(player);
	}

	private static void refreshLittleDictatorSanctionsFatigue(ServerPlayer player) {
		if (player == null || !LITTLE_DICTATOR_SANCTIONS.containsKey(player.getUUID())) {
			return;
		}
		MobEffectInstance current = player.getEffect(MobEffects.MINING_FATIGUE);
		if (isLittleDictatorSanctionsManagedFatigue(current)) {
			return;
		}
		player.addEffect(new MobEffectInstance(
				MobEffects.MINING_FATIGUE,
				MobEffectInstance.INFINITE_DURATION,
				0,
				false,
				false,
				true
		));
	}

	private static void removeLittleDictatorSanctionsFatigue(ServerPlayer player) {
		if (player == null) {
			return;
		}
		if (isLittleDictatorSanctionsManagedFatigue(player.getEffect(MobEffects.MINING_FATIGUE))) {
			player.removeEffect(MobEffects.MINING_FATIGUE);
		}
	}

	private static boolean isLittleDictatorSanctionsManagedFatigue(MobEffectInstance effect) {
		return effect != null
				&& effect.getEffect().equals(MobEffects.MINING_FATIGUE)
				&& effect.getAmplifier() == 0
				&& effect.getDuration() == MobEffectInstance.INFINITE_DURATION
				&& !effect.isVisible()
				&& effect.showIcon();
	}

	private static void tickLittleDictatorTaxes(MinecraftServer server, ServerPlayer target) {
		if (server == null || target == null) {
			return;
		}
		LittleDictatorTaxesSession session = LITTLE_DICTATOR_TAXES.get(target.getUUID());
		if (session == null) {
			return;
		}
		if (--session.remainingTicks <= 0L) {
			LITTLE_DICTATOR_TAXES.remove(target.getUUID());
			return;
		}
		if (--session.nextTaxTicks > 0L) {
			return;
		}
		session.nextTaxTicks = session.intervalTicks;
		collectLittleDictatorTax(server, target, session.dictatorId);
	}

	private static void tickLittleDictatorPropaganda(ServerPlayer player) {
		if (player == null) {
			return;
		}
		LittleDictatorPropagandaSession session = LITTLE_DICTATOR_PROPAGANDA.get(player.getUUID());
		if (session == null) {
			return;
		}
		if (--session.remainingTicks <= 0L) {
			finishLittleDictatorPropaganda(player, true);
			return;
		}
		tickLittleDictatorPropagandaNaturalHaste(player);
		refreshLittleDictatorPropagandaHaste(player);
	}

	private static void finishLittleDictatorPropaganda(ServerPlayer player, boolean removeSession) {
		if (player == null) {
			return;
		}
		UUID playerId = player.getUUID();
		MobEffectInstance current = player.getEffect(MobEffects.HASTE);
		Integer managedAmplifier = LITTLE_DICTATOR_PROPAGANDA_MANAGED_HASTE.remove(playerId);
		boolean removeManagedHaste = isLittleDictatorPropagandaManagedHaste(current, managedAmplifier);
		MobEffectInstance naturalHaste = getLittleDictatorPropagandaNaturalHaste(player);
		LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE.remove(playerId);
		LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE_END_TICKS.remove(playerId);
		if (removeSession) {
			LITTLE_DICTATOR_PROPAGANDA.remove(playerId);
		}
		if (removeManagedHaste) {
			player.removeEffect(MobEffects.HASTE);
		}
		if (naturalHaste != null && (naturalHaste.getDuration() > 0 || naturalHaste.getDuration() == MobEffectInstance.INFINITE_DURATION)) {
			LITTLE_DICTATOR_PROPAGANDA_APPLYING_HASTE.set(Boolean.TRUE);
			try {
				player.addEffect(naturalHaste);
			} finally {
				LITTLE_DICTATOR_PROPAGANDA_APPLYING_HASTE.set(Boolean.FALSE);
			}
		}
	}

	private static void tickLittleDictatorPropagandaNaturalHaste(ServerPlayer player) {
		if (player == null) {
			return;
		}
		UUID playerId = player.getUUID();
		MobEffectInstance natural = getLittleDictatorPropagandaNaturalHaste(player);
		if (natural == null) {
			LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE.remove(playerId);
			LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE_END_TICKS.remove(playerId);
		}
	}

	private static void refreshLittleDictatorPropagandaHaste(ServerPlayer player) {
		if (player == null || !LITTLE_DICTATOR_PROPAGANDA.containsKey(player.getUUID())) {
			return;
		}
		UUID playerId = player.getUUID();
		MobEffectInstance naturalHaste = getLittleDictatorPropagandaNaturalHaste(player);
		int baseAmplifier = naturalHaste == null ? -1 : naturalHaste.getAmplifier();
		int amplifier = Math.min(MobEffectInstance.MAX_AMPLIFIER, baseAmplifier + 1);
		MobEffectInstance current = player.getEffect(MobEffects.HASTE);
		Integer managedAmplifier = LITTLE_DICTATOR_PROPAGANDA_MANAGED_HASTE.get(playerId);
		if (isLittleDictatorPropagandaManagedHaste(current, managedAmplifier) && current.getAmplifier() == amplifier) {
			return;
		}
		if (isLittleDictatorPropagandaManagedHaste(current, managedAmplifier)) {
			player.removeEffect(MobEffects.HASTE);
		} else if (current != null && current.getEffect().equals(MobEffects.HASTE)) {
			MobEffectInstance currentNatural = copyLittleDictatorPropagandaNaturalHaste(current);
			if (currentNatural != null && shouldReplaceLittleDictatorPropagandaNaturalHaste(player, currentNatural)) {
				storeLittleDictatorPropagandaNaturalHaste(player, currentNatural);
				naturalHaste = getLittleDictatorPropagandaNaturalHaste(player);
				baseAmplifier = naturalHaste == null ? -1 : naturalHaste.getAmplifier();
				amplifier = Math.min(MobEffectInstance.MAX_AMPLIFIER, baseAmplifier + 1);
			}
			player.removeEffect(MobEffects.HASTE);
		}
		LITTLE_DICTATOR_PROPAGANDA_APPLYING_HASTE.set(Boolean.TRUE);
		try {
			player.addEffect(new MobEffectInstance(MobEffects.HASTE, MobEffectInstance.INFINITE_DURATION, amplifier, false, false, false));
			LITTLE_DICTATOR_PROPAGANDA_MANAGED_HASTE.put(playerId, amplifier);
		} finally {
			LITTLE_DICTATOR_PROPAGANDA_APPLYING_HASTE.set(Boolean.FALSE);
		}
	}

	private static boolean isLittleDictatorPropagandaManagedHaste(ServerPlayer player, MobEffectInstance effect) {
		if (player == null || effect == null || !LITTLE_DICTATOR_PROPAGANDA.containsKey(player.getUUID())) {
			return false;
		}
		return isLittleDictatorPropagandaManagedHaste(effect, LITTLE_DICTATOR_PROPAGANDA_MANAGED_HASTE.get(player.getUUID()));
	}

	private static boolean isLittleDictatorPropagandaManagedHaste(MobEffectInstance effect, Integer managedAmplifier) {
		if (effect == null || managedAmplifier == null) {
			return false;
		}
		return effect.getEffect().equals(MobEffects.HASTE)
				&& effect.getAmplifier() == managedAmplifier
				&& effect.getDuration() == MobEffectInstance.INFINITE_DURATION
				&& !effect.isVisible()
				&& !effect.showIcon();
	}

	private static MobEffectInstance copyLittleDictatorPropagandaNaturalHaste(MobEffectInstance effect) {
		if (effect == null || !effect.getEffect().equals(MobEffects.HASTE)) {
			return null;
		}
		return copyLittleDictatorPropagandaNaturalHaste(effect, effect.getDuration());
	}

	private static MobEffectInstance copyLittleDictatorPropagandaNaturalHaste(MobEffectInstance effect, int duration) {
		if (effect == null
				|| !effect.getEffect().equals(MobEffects.HASTE)
				|| (duration <= 0 && duration != MobEffectInstance.INFINITE_DURATION)) {
			return null;
		}
		return new MobEffectInstance(
				MobEffects.HASTE,
				duration,
				effect.getAmplifier(),
				effect.isAmbient(),
				effect.isVisible(),
				effect.showIcon()
		);
	}

	private static void storeLittleDictatorPropagandaNaturalHaste(ServerPlayer player, MobEffectInstance effect) {
		if (player == null) {
			return;
		}
		UUID playerId = player.getUUID();
		MobEffectInstance copy = copyLittleDictatorPropagandaNaturalHaste(effect);
		if (copy == null) {
			LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE.remove(playerId);
			LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE_END_TICKS.remove(playerId);
			return;
		}
		LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE.put(playerId, copy);
		long endTick = copy.getDuration() == MobEffectInstance.INFINITE_DURATION
				? Long.MAX_VALUE
				: player.level().getGameTime() + copy.getDuration();
		LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE_END_TICKS.put(playerId, endTick);
	}

	private static MobEffectInstance getLittleDictatorPropagandaNaturalHaste(ServerPlayer player) {
		if (player == null) {
			return null;
		}
		UUID playerId = player.getUUID();
		MobEffectInstance stored = LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE.get(playerId);
		Long endTick = LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE_END_TICKS.get(playerId);
		if (stored == null || endTick == null) {
			LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE.remove(playerId);
			LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE_END_TICKS.remove(playerId);
			return null;
		}
		if (endTick == Long.MAX_VALUE || stored.getDuration() == MobEffectInstance.INFINITE_DURATION) {
			return copyLittleDictatorPropagandaNaturalHaste(stored, MobEffectInstance.INFINITE_DURATION);
		}
		long remaining = endTick - player.level().getGameTime();
		if (remaining <= 0L) {
			LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE.remove(playerId);
			LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE_END_TICKS.remove(playerId);
			return null;
		}
		return copyLittleDictatorPropagandaNaturalHaste(stored, (int) Math.min(Integer.MAX_VALUE, remaining));
	}

	public static boolean handleLittleDictatorPropagandaIncomingHaste(LivingEntity entity, MobEffectInstance effect) {
		if (!(entity instanceof ServerPlayer player)
				|| effect == null
				|| !effect.getEffect().equals(MobEffects.HASTE)
				|| !LITTLE_DICTATOR_PROPAGANDA.containsKey(player.getUUID())
				|| LITTLE_DICTATOR_PROPAGANDA_APPLYING_HASTE.get()) {
			return false;
		}
		MobEffectInstance incoming = copyLittleDictatorPropagandaNaturalHaste(effect);
		if (incoming == null) {
			return true;
		}
		if (shouldReplaceLittleDictatorPropagandaNaturalHaste(player, incoming)) {
			storeLittleDictatorPropagandaNaturalHaste(player, incoming);
		}
		refreshLittleDictatorPropagandaHaste(player);
		return true;
	}

	private static boolean shouldReplaceLittleDictatorPropagandaNaturalHaste(ServerPlayer player, MobEffectInstance incoming) {
		if (player == null || incoming == null) {
			return false;
		}
		MobEffectInstance previous = getLittleDictatorPropagandaNaturalHaste(player);
		if (previous == null) {
			return true;
		}
		if (incoming.getAmplifier() != previous.getAmplifier()) {
			return incoming.getAmplifier() > previous.getAmplifier();
		}
		if (incoming.getDuration() < previous.getDuration() && previous.getDuration() != MobEffectInstance.INFINITE_DURATION) {
			return true;
		}
		long incomingEndTick = incoming.getDuration() == MobEffectInstance.INFINITE_DURATION
				? Long.MAX_VALUE
				: player.level().getGameTime() + incoming.getDuration();
		Long previousEndTick = LITTLE_DICTATOR_PROPAGANDA_NATURAL_HASTE_END_TICKS.get(player.getUUID());
		if (incomingEndTick == Long.MAX_VALUE) {
			return previousEndTick == null || previousEndTick != Long.MAX_VALUE;
		}
		if (previousEndTick == null || previousEndTick == Long.MAX_VALUE) {
			return false;
		}
		return incomingEndTick > previousEndTick;
	}

	private static void collectLittleDictatorTax(MinecraftServer server, ServerPlayer target, UUID dictatorId) {
		if (server == null || target == null || dictatorId == null) {
			return;
		}
		Container container = getRandomLittleDictatorTaxContainer(server, dictatorId, target.getRandom());
		if (container == null) {
			return;
		}
		Inventory inventory = target.getInventory();
		List<Integer> slots = new ArrayList<>();
		for (int slot = 0; slot < inventory.getContainerSize(); slot++) {
			ItemStack stack = inventory.getItem(slot);
			if (!stack.isEmpty()) {
				slots.add(slot);
			}
		}
		if (slots.isEmpty()) {
			return;
		}
		int slot = slots.get(target.getRandom().nextInt(slots.size()));
		ItemStack source = inventory.getItem(slot);
		if (source.isEmpty()) {
			return;
		}
		int count = 1 + target.getRandom().nextInt(source.getCount());
		ItemStack removed = inventory.removeItem(slot, count);
		if (removed.isEmpty()) {
			return;
		}
		ItemStack remaining = removed;
		try {
			remaining = insertIntoLittleDictatorTaxContainer(container, removed);
			markLittleDictatorTaxContainerChanged(container);
		} catch (RuntimeException exception) {
			Lg2.LOGGER.error("Failed to insert little dictator tax into a tax chest", exception);
		}
		if (!remaining.isEmpty()) {
			if (!inventory.add(remaining)) {
				target.drop(remaining, false);
			}
		}
		inventory.setChanged();
		target.containerMenu.broadcastChanges();
	}

	private static Container getRandomLittleDictatorTaxContainer(MinecraftServer server, UUID dictatorId, RandomSource random) {
		Set<LittleDictatorTaxChestRef> refs = LITTLE_DICTATOR_TAX_CHESTS.get(dictatorId);
		if (server == null || refs == null || refs.isEmpty()) {
			return null;
		}
		List<LittleDictatorTaxChestRef> shuffled = new ArrayList<>(refs);
		Collections.shuffle(shuffled, new java.util.Random(random == null ? 0L : random.nextLong()));
		for (LittleDictatorTaxChestRef ref : shuffled) {
			try {
				Container container = getLittleDictatorTaxContainer(server, ref);
				if (container != null) {
					return container;
				}
			} catch (RuntimeException exception) {
				Lg2.LOGGER.error("Failed to resolve little dictator tax chest at {}", ref, exception);
			}
		}
		return null;
	}

	private static Container getLittleDictatorTaxContainer(MinecraftServer server, LittleDictatorTaxChestRef ref) {
		if (server == null || ref == null) {
			return null;
		}
		ServerLevel level = server.getLevel(ref.dimension());
		if (level == null) {
			return null;
		}
		level.getChunkAt(ref.pos());
		BlockState state = level.getBlockState(ref.pos());
		if (!isLittleDictatorTaxChestBlock(state)) {
			return null;
		}
		BlockEntity blockEntity = level.getBlockEntity(ref.pos());
		if (!(blockEntity instanceof Container container)) {
			return null;
		}
		if (!(state.getBlock() instanceof ChestBlock) || !state.hasProperty(ChestBlock.TYPE) || state.getValue(ChestBlock.TYPE) == ChestType.SINGLE) {
			return container;
		}
		Direction facing = state.hasProperty(ChestBlock.FACING) ? state.getValue(ChestBlock.FACING) : Direction.SOUTH;
		BlockPos connectedPos = findLittleDictatorConnectedChestPos(level, ref.pos(), state, facing);
		if (connectedPos == null) {
			return container;
		}
		BlockEntity connectedBlockEntity = level.getBlockEntity(connectedPos);
		if (!(connectedBlockEntity instanceof Container connectedContainer)) {
			return container;
		}
		Container first = ref.pos().asLong() <= connectedPos.asLong() ? container : connectedContainer;
		Container second = first == container ? connectedContainer : container;
		return new CompoundContainer(first, second);
	}

	private static ItemStack insertIntoLittleDictatorTaxContainer(Container container, ItemStack stack) {
		if (container == null || stack == null || stack.isEmpty()) {
			return ItemStack.EMPTY;
		}
		ItemStack remaining = stack.copy();

		// Mimic a normal shift-click: top off existing compatible stacks first.
		for (int slot = 0; slot < container.getContainerSize() && !remaining.isEmpty(); slot++) {
			ItemStack existing = container.getItem(slot);
			if (existing.isEmpty() || !ItemStack.isSameItemSameComponents(existing, remaining)) {
				continue;
			}
			if (!container.canPlaceItem(slot, remaining)) {
				continue;
			}
			int limit = Math.min(container.getMaxStackSize(), existing.getMaxStackSize());
			int free = Math.max(0, limit - existing.getCount());
			if (free <= 0) {
				continue;
			}
			int move = Math.min(remaining.getCount(), free);
			existing.grow(move);
			remaining.shrink(move);
			container.setItem(slot, existing);
		}

		// Then fill empty slots in order from left to right.
		for (int slot = 0; slot < container.getContainerSize() && !remaining.isEmpty(); slot++) {
			ItemStack existing = container.getItem(slot);
			if (!existing.isEmpty() || !container.canPlaceItem(slot, remaining)) {
				continue;
			}
			int move = Math.min(remaining.getCount(), Math.min(container.getMaxStackSize(), remaining.getMaxStackSize()));
			if (move <= 0) {
				continue;
			}
			container.setItem(slot, remaining.copyWithCount(move));
			remaining.shrink(move);
		}

		markLittleDictatorTaxContainerChanged(container);
		return remaining;
	}

	private static void markLittleDictatorTaxContainerChanged(Container container) {
		if (container == null) {
			return;
		}
		try {
			container.setChanged();
		} catch (RuntimeException exception) {
			Lg2.LOGGER.error("Failed to mark little dictator tax container as changed", exception);
		}
	}

	private static boolean pruneLittleDictatorTaxChests(MinecraftServer server) {
		if (server == null || LITTLE_DICTATOR_TAX_CHESTS.isEmpty()) {
			return false;
		}
		boolean changed = false;
		Iterator<Map.Entry<UUID, Set<LittleDictatorTaxChestRef>>> iterator = LITTLE_DICTATOR_TAX_CHESTS.entrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, Set<LittleDictatorTaxChestRef>> entry = iterator.next();
			Set<LittleDictatorTaxChestRef> refs = entry.getValue();
			if (refs == null) {
				iterator.remove();
				changed = true;
				continue;
			}
			int before = refs.size();
			refs.removeIf(ref -> getLittleDictatorTaxContainer(server, ref) == null);
			if (refs.size() != before) {
				changed = true;
			}
			if (refs.isEmpty()) {
				iterator.remove();
				changed = true;
			}
		}
		return changed;
	}

	private static void syncLittleDictatorTaxChestHighlights(MinecraftServer server, ServerPlayer owner) {
		if (server == null || owner == null || owner.connection == null || !(owner.level() instanceof ServerLevel ownerLevel)) {
			return;
		}
		Set<LittleDictatorTaxChestRef> visibleRefs = resolveVisibleLittleDictatorTaxChests(ownerLevel, owner);
		List<LittleDictatorTaxChestHighlightPart> visibleParts = resolveLittleDictatorTaxChestHighlightParts(server, visibleRefs);
		Map<LittleDictatorTaxChestRef, BlockState> visibleStates = new LinkedHashMap<>();
		for (LittleDictatorTaxChestHighlightPart part : visibleParts) {
			if (part != null && part.ref() != null && part.state() != null) {
				visibleStates.put(part.ref(), part.state());
			}
		}
		LittleDictatorTaxChestHighlightState previous = LITTLE_DICTATOR_TAX_CHEST_HIGHLIGHTS.get(owner.getUUID());
		if (previous != null && previous.refs().equals(visibleRefs) && previous.blockStates().equals(visibleStates)) {
			return;
		}
		clearLittleDictatorTaxChestHighlights(owner);
		if (visibleRefs.isEmpty() || visibleStates.isEmpty()) {
			return;
		}

		List<Integer> entityIds = new ArrayList<>();
		visibleParts.sort(Comparator
				.comparing((LittleDictatorTaxChestHighlightPart part) -> part.ref().dimension().toString())
				.thenComparingInt(part -> part.ref().pos().getX())
				.thenComparingInt(part -> part.ref().pos().getY())
				.thenComparingInt(part -> part.ref().pos().getZ()));
		for (LittleDictatorTaxChestHighlightPart part : visibleParts) {
			ServerLevel level = server.getLevel(part.ref().dimension());
			if (level == null) {
				continue;
			}
			Display.ItemDisplay display = createLittleDictatorTaxChestHighlightDisplay(level, part.ref().pos(), part.state());
			if (display == null) {
				continue;
			}
			entityIds.add(display.getId());
			sendLittleDictatorTaxChestHighlightSpawn(owner, display);
		}
		if (entityIds.isEmpty()) {
			return;
		}
		int[] ids = new int[entityIds.size()];
		for (int i = 0; i < entityIds.size(); i++) {
			ids[i] = entityIds.get(i);
		}
		LITTLE_DICTATOR_TAX_CHEST_HIGHLIGHTS.put(owner.getUUID(), new LittleDictatorTaxChestHighlightState(visibleRefs, visibleStates, ids));
	}

	private static List<LittleDictatorTaxChestHighlightPart> resolveLittleDictatorTaxChestHighlightParts(MinecraftServer server, Set<LittleDictatorTaxChestRef> refs) {
		if (server == null || refs == null || refs.isEmpty()) {
			return List.of();
		}
		Map<LittleDictatorTaxChestRef, BlockState> states = new LinkedHashMap<>();
		for (LittleDictatorTaxChestRef ref : refs) {
			if (ref == null) {
				continue;
			}
			ServerLevel level = server.getLevel(ref.dimension());
			if (level == null) {
				continue;
			}
			BlockState state = level.getBlockState(ref.pos());
			if (isLittleDictatorTaxChestBlock(state)) {
				addLittleDictatorTaxChestHighlightStates(level, ref, state, states);
			}
		}
		List<LittleDictatorTaxChestHighlightPart> parts = new ArrayList<>();
		for (Map.Entry<LittleDictatorTaxChestRef, BlockState> entry : states.entrySet()) {
			parts.add(new LittleDictatorTaxChestHighlightPart(entry.getKey(), entry.getValue()));
		}
		return parts;
	}

	private static void addLittleDictatorTaxChestHighlightStates(
			ServerLevel level,
			LittleDictatorTaxChestRef ref,
			BlockState state,
			Map<LittleDictatorTaxChestRef, BlockState> states
	) {
		if (level == null || ref == null || state == null || states == null || !(state.getBlock() instanceof ChestBlock)) {
			return;
		}
		Direction facing = state.hasProperty(ChestBlock.FACING) ? state.getValue(ChestBlock.FACING) : Direction.SOUTH;
		BlockPos connectedPos = findLittleDictatorConnectedChestPos(level, ref.pos(), state, facing);
		if (connectedPos == null) {
			states.put(ref, state.setValue(ChestBlock.TYPE, ChestType.SINGLE));
			return;
		}
		BlockState connectedState = level.getBlockState(connectedPos);
		Direction right = facing.getClockWise();
		int deltaX = connectedPos.getX() - ref.pos().getX();
		int deltaZ = connectedPos.getZ() - ref.pos().getZ();
		boolean currentIsLeft = deltaX * right.getStepX() + deltaZ * right.getStepZ() > 0;
		ChestType currentType = currentIsLeft ? ChestType.LEFT : ChestType.RIGHT;
		ChestType connectedType = currentIsLeft ? ChestType.RIGHT : ChestType.LEFT;
		states.put(ref, state.setValue(ChestBlock.FACING, facing).setValue(ChestBlock.TYPE, currentType));
		states.put(
				new LittleDictatorTaxChestRef(ref.dimension(), connectedPos),
				connectedState.setValue(ChestBlock.FACING, facing).setValue(ChestBlock.TYPE, connectedType)
		);
	}

	private static BlockPos findLittleDictatorConnectedChestPos(ServerLevel level, BlockPos pos, BlockState state, Direction facing) {
		if (level == null || pos == null || state == null || facing == null) {
			return null;
		}
		if (state.hasProperty(ChestBlock.TYPE) && state.getValue(ChestBlock.TYPE) != ChestType.SINGLE) {
			BlockPos connectedPos = ChestBlock.getConnectedBlockPos(pos, state);
			if (isMatchingLittleDictatorChestHalf(level.getBlockState(connectedPos), state, facing)) {
				return connectedPos;
			}
		}
		for (Direction direction : List.of(facing.getClockWise(), facing.getCounterClockWise())) {
			BlockPos candidate = pos.relative(direction);
			if (isMatchingLittleDictatorChestHalf(level.getBlockState(candidate), state, facing)) {
				return candidate;
			}
		}
		return null;
	}

	private static boolean isMatchingLittleDictatorChestHalf(BlockState candidate, BlockState source, Direction facing) {
		return candidate != null
				&& source != null
				&& candidate.getBlock() == source.getBlock()
				&& candidate.hasProperty(ChestBlock.FACING)
				&& candidate.getValue(ChestBlock.FACING) == facing;
	}

	private static Set<LittleDictatorTaxChestRef> resolveVisibleLittleDictatorTaxChests(ServerLevel ownerLevel, ServerPlayer owner) {
		if (ownerLevel == null || owner == null) {
			return Set.of();
		}
		Set<LittleDictatorTaxChestRef> refs = LITTLE_DICTATOR_TAX_CHESTS.get(owner.getUUID());
		if (refs == null || refs.isEmpty()) {
			return Set.of();
		}
		Set<LittleDictatorTaxChestRef> visible = new HashSet<>();
		double maxDistanceSqr = LITTLE_DICTATOR_TAX_CHEST_HIGHLIGHT_RANGE_BLOCKS * LITTLE_DICTATOR_TAX_CHEST_HIGHLIGHT_RANGE_BLOCKS;
		for (LittleDictatorTaxChestRef ref : refs) {
			if (ref == null || !ref.dimension().equals(ownerLevel.dimension())) {
				continue;
			}
			Vec3 center = Vec3.atCenterOf(ref.pos());
			if (center.distanceToSqr(owner.position()) <= maxDistanceSqr) {
				visible.add(ref);
			}
		}
		return visible;
	}

	private static Display.ItemDisplay createLittleDictatorTaxChestHighlightDisplay(ServerLevel level, BlockPos pos, BlockState state) {
		if (level == null || pos == null || state == null) {
			return null;
		}
		if (!isLittleDictatorTaxChestBlock(state)) {
			return null;
		}
		Display.ItemDisplay display = new Display.ItemDisplay(EntityType.ITEM_DISPLAY, level);
		display.setPos(pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D);
		display.setYRot(0.0F);
		display.setXRot(0.0F);
		display.setYHeadRot(0.0F);
		display.setYBodyRot(0.0F);
		display.setTransformation(createLittleDictatorTaxChestHighlightTransformation(level, pos, state));
		display.setNoGravity(true);
		display.setInvulnerable(true);
		display.setSilent(true);
		display.setShadowRadius(0.0F);
		display.setShadowStrength(0.0F);
		display.setGlowingTag(true);
		display.setViewRange(LITTLE_DICTATOR_TAX_CHEST_HIGHLIGHT_VIEW_RANGE);
		display.setItemStack(ServerSelectionHighlightSystem.createHighlightCarrierStack());
		display.setItemTransform(ItemDisplayContext.FIXED);
		display.setBillboardConstraints(Display.BillboardConstraints.FIXED);
		return display;
	}

	private static Transformation createLittleDictatorTaxChestHighlightTransformation(ServerLevel level, BlockPos pos, BlockState state) {
		float halfPixel = 0.5F / 16.0F;
		float quarterPixel = 0.125F / 16.0F;
		float minX = 1.0F / 16.0F;
		float maxX = 15.0F / 16.0F;
		float minY = 0.25F / 16.0F;
		float maxY = 14.5F / 16.0F;
		float minZ = 1.0F / 16.0F;
		float maxZ = 15.0F / 16.0F;
		if (level != null
				&& pos != null
				&& state != null
				&& state.getBlock() instanceof ChestBlock
				&& state.hasProperty(ChestBlock.TYPE)
				&& state.getValue(ChestBlock.TYPE) != ChestType.SINGLE) {
			BlockPos connectedPos = ChestBlock.getConnectedBlockPos(pos, state);
			int deltaX = connectedPos.getX() - pos.getX();
			int deltaZ = connectedPos.getZ() - pos.getZ();
			if (deltaX > 0) {
				maxX = 1.0F;
			} else if (deltaX < 0) {
				minX = 0.0F;
			}
			if (deltaZ > 0) {
				maxZ = 1.0F;
			} else if (deltaZ < 0) {
				minZ = 0.0F;
			}
			if (state.hasProperty(ChestBlock.FACING)) {
				Direction facing = state.getValue(ChestBlock.FACING);
				if (facing.getAxis() == Direction.Axis.Z) {
					minX -= halfPixel;
					maxX += halfPixel;
				} else {
					minZ -= halfPixel;
					maxZ += halfPixel;
				}
			}
		}
		float centerX = ((minX + maxX) * 0.5F - 0.5F) * LITTLE_DICTATOR_TAX_CHEST_ITEM_DISPLAY_BLOCK_SCALE;
		float centerY = (((minY + maxY) * 0.5F - 0.5F) + quarterPixel) * LITTLE_DICTATOR_TAX_CHEST_ITEM_DISPLAY_BLOCK_SCALE;
		float centerZ = ((minZ + maxZ) * 0.5F - 0.5F) * LITTLE_DICTATOR_TAX_CHEST_ITEM_DISPLAY_BLOCK_SCALE;
		return new Transformation(
				new Vector3f(centerX, centerY, centerZ),
				new Quaternionf(),
				new Vector3f(
						(maxX - minX) * LITTLE_DICTATOR_TAX_CHEST_ITEM_DISPLAY_BLOCK_SCALE,
						(maxY - minY) * LITTLE_DICTATOR_TAX_CHEST_ITEM_DISPLAY_BLOCK_SCALE,
						(maxZ - minZ) * LITTLE_DICTATOR_TAX_CHEST_ITEM_DISPLAY_BLOCK_SCALE
				),
				new Quaternionf()
		);
	}
	@SuppressWarnings("unchecked")
	private static void sendLittleDictatorTaxChestHighlightSpawn(ServerPlayer owner, Entity entity) {
		if (owner == null || entity == null || owner.connection == null || !(entity.level() instanceof ServerLevel level)) {
			return;
		}
		ServerEntity tracker = new ServerEntity(
				level,
				entity,
				1,
				false,
				LITTLE_DICTATOR_TAX_CHEST_NOOP_SYNCHRONIZER
		);
		tracker.sendPairingData(owner, packet -> owner.connection.send((Packet<? super ClientGamePacketListener>) packet));
		List<SynchedEntityData.DataValue<?>> values = entity.getEntityData().getNonDefaultValues();
		if (values != null && !values.isEmpty()) {
			owner.connection.send(new ClientboundSetEntityDataPacket(entity.getId(), values));
		}
	}

	private static void clearLittleDictatorTaxChestHighlights(ServerPlayer owner) {
		if (owner == null) {
			return;
		}
		LittleDictatorTaxChestHighlightState previous = LITTLE_DICTATOR_TAX_CHEST_HIGHLIGHTS.remove(owner.getUUID());
		if (owner.connection != null && previous != null && previous.entityIds().length > 0) {
			owner.connection.send(new ClientboundRemoveEntitiesPacket(previous.entityIds()));
		}
	}

	private static final ServerEntity.Synchronizer LITTLE_DICTATOR_TAX_CHEST_NOOP_SYNCHRONIZER = new ServerEntity.Synchronizer() {
		@Override
		public void sendToTrackingPlayers(Packet<? super ClientGamePacketListener> packet) {
		}

		@Override
		public void sendToTrackingPlayersAndSelf(Packet<? super ClientGamePacketListener> packet) {
		}

		@Override
		public void sendToTrackingPlayersFiltered(Packet<? super ClientGamePacketListener> packet, java.util.function.Predicate<ServerPlayer> predicate) {
		}
	};

	private static void syncLittleDictatorMerchantOffers(ServerPlayer player) {
		if (player == null) {
			return;
		}
		String mode = getLittleDictatorMerchantMode(player);
		if (!(player.containerMenu instanceof MerchantMenu menu)) {
			LITTLE_DICTATOR_SYNCED_MERCHANT_MENUS.remove(player.getUUID());
			return;
		}
		LittleDictatorMerchantOfferSync synced = LITTLE_DICTATOR_SYNCED_MERCHANT_MENUS.get(player.getUUID());
		if (mode == null) {
			if (synced != null && synced.containerId() == menu.containerId) {
				restoreLittleDictatorMerchantOffers(player, menu);
			}
			LITTLE_DICTATOR_SYNCED_MERCHANT_MENUS.remove(player.getUUID());
			return;
		}
		if (synced != null && synced.containerId() == menu.containerId && mode.equals(synced.mode())) {
			return;
		}

		Merchant merchant = ((MerchantMenuAccessor) menu).lg2$getTrader();
		if (merchant == null) {
			return;
		}
		MerchantOffers originalOffers = merchant.getOffers();
		if (originalOffers == null) {
			return;
		}
		MerchantOffers adjusted = buildLittleDictatorAdjustedOffers(originalOffers, player);
		menu.setOffers(adjusted);
		player.sendMerchantOffers(
				menu.containerId,
				adjusted,
				menu.getTraderLevel(),
				menu.getTraderXp(),
				menu.showProgressBar(),
				menu.canRestock()
		);
		LITTLE_DICTATOR_SYNCED_MERCHANT_MENUS.put(player.getUUID(), new LittleDictatorMerchantOfferSync(menu.containerId, mode));
	}

	private static String getLittleDictatorMerchantMode(ServerPlayer player) {
		if (player == null) {
			return null;
		}
		if (isLittleDictatorSanctioned(player)) {
			return "sanctions";
		}
		LittleDictatorPropagandaSession session = LITTLE_DICTATOR_PROPAGANDA.get(player.getUUID());
		if (session != null) {
			return "propaganda:" + session.tradeDiscount;
		}
		return null;
	}

	private static MerchantOffers buildLittleDictatorAdjustedOffers(MerchantOffers originalOffers, ServerPlayer player) {
		MerchantOffers adjusted = originalOffers == null ? new MerchantOffers() : originalOffers.copy();
		if (player == null) {
			return adjusted;
		}
		if (isLittleDictatorSanctioned(player)) {
			for (MerchantOffer offer : adjusted) {
				if (offer != null) {
					offer.setToOutOfStock();
				}
			}
			return adjusted;
		}
		LittleDictatorPropagandaSession session = LITTLE_DICTATOR_PROPAGANDA.get(player.getUUID());
		if (session == null || session.tradeDiscount <= 0.0D) {
			return adjusted;
		}
		for (MerchantOffer offer : adjusted) {
			if (offer == null) {
				continue;
			}
			int baseCount = offer.getBaseCostA().getCount();
			if (baseCount <= 1) {
				continue;
			}
			int discountedCount = Math.max(1, (int) Math.ceil(baseCount * (1.0D - session.tradeDiscount)));
			int desiredSpecialDiff = discountedCount - baseCount;
			int currentSpecialDiff = offer.getSpecialPriceDiff();
			if (desiredSpecialDiff < currentSpecialDiff) {
				offer.addToSpecialPriceDiff(desiredSpecialDiff - currentSpecialDiff);
			}
		}
		return adjusted;
	}

	private static void restoreLittleDictatorMerchantOffers(ServerPlayer player, MerchantMenu menu) {
		if (player == null || menu == null) {
			return;
		}
		Merchant merchant = ((MerchantMenuAccessor) menu).lg2$getTrader();
		if (merchant == null || merchant.getOffers() == null) {
			return;
		}
		MerchantOffers restored = merchant.getOffers().copy();
		menu.setOffers(restored);
		player.sendMerchantOffers(
				menu.containerId,
				restored,
				menu.getTraderLevel(),
				menu.getTraderXp(),
				menu.showProgressBar(),
				menu.canRestock()
		);
	}

	private static boolean isLittleDictatorSanctioned(ServerPlayer player) {
		return player != null && LITTLE_DICTATOR_SANCTIONS.containsKey(player.getUUID());
	}

	public static boolean isLittleDictatorPropagandaActive(ServerPlayer player) {
		return player != null && LITTLE_DICTATOR_PROPAGANDA.containsKey(player.getUUID());
	}

    public static float getLittleDictatorUniqueVoiceIntensity(ServerPlayer player) {
        if (player == null || !(player.level() instanceof ServerLevel level)) {
            return 0.0F;
        }
        LittleDictatorUniqueSession session = LITTLE_DICTATOR_UNIQUE_SESSIONS.get(player.getUUID());
        if (session == null || !level.dimension().equals(session.dimension)) {
            return 0.0F;
        }
        double scale = getLittleDictatorUniqueScale(session, level.getGameTime());
        if (scale <= 1.001D) {
            return 0.0F;
        }
        double targetScale = Math.max(1.0D, session.targetScale);
        double normalized = targetScale <= 1.0D ? 1.0D : Mth.clamp((scale - 1.0D) / (targetScale - 1.0D), 0.0D, 1.0D);
        return (float) normalized;
    }

    public static float getLittleDictatorUniqueVoicePitchFactor(ServerPlayer player) {
        return (float) Mth.lerp(getLittleDictatorUniqueVoiceIntensity(player), 1.0D, 0.7D);
    }

	public static void beginLittleDictatorBlockLootContext(ServerPlayer player) {
		LITTLE_DICTATOR_DROP_CONTEXT_PLAYER.set(player);
		LITTLE_DICTATOR_ENCHANTMENT_CONTEXT_PLAYER.set(player);
	}

	public static void beginLittleDictatorDeathLootContext(ServerLevel level, LivingEntity victim, DamageSource damageSource) {
		if (level == null || victim == null || damageSource == null) {
			return;
		}
		LivingEntity attacker = resolveMarkKillAttacker(victim, damageSource);
		ServerPlayer player = attacker instanceof ServerPlayer serverPlayer ? serverPlayer : null;
		LITTLE_DICTATOR_DROP_CONTEXT_PLAYER.set(player);
		LITTLE_DICTATOR_ENCHANTMENT_CONTEXT_PLAYER.set(player);
	}

	public static void endLittleDictatorLootContext() {
		LITTLE_DICTATOR_DROP_CONTEXT_PLAYER.remove();
		LITTLE_DICTATOR_ENCHANTMENT_CONTEXT_PLAYER.remove();
	}

	public static boolean shouldCancelLittleDictatorContextDrop() {
		ServerPlayer player = LITTLE_DICTATOR_DROP_CONTEXT_PLAYER.get();
		if (player == null) {
			return false;
		}
		LittleDictatorSanctionsSession session = LITTLE_DICTATOR_SANCTIONS.get(player.getUUID());
		if (session == null) {
			return false;
		}
		return player.getRandom().nextDouble() >= session.dropChance;
	}

	public static int getLittleDictatorPropagandaEnchantmentBonus(Holder<net.minecraft.world.item.enchantment.Enchantment> enchantment) {
		ServerPlayer player = LITTLE_DICTATOR_ENCHANTMENT_CONTEXT_PLAYER.get();
		if (player == null || enchantment == null || !isLittleDictatorPropagandaActive(player)) {
			return 0;
		}
		if (enchantment.is(Enchantments.FORTUNE)
				|| enchantment.is(Enchantments.LOOTING)
				|| enchantment.is(Enchantments.LUCK_OF_THE_SEA)
				|| enchantment.is(Enchantments.LURE)) {
			return 1;
		}
		return 0;
	}

	public static int getLittleDictatorPropagandaFishingBonus(Player player) {
		return player instanceof ServerPlayer serverPlayer && isLittleDictatorPropagandaActive(serverPlayer) ? 1 : 0;
	}

	public static void handleLittleDictatorPlayerKill(ServerLevel level, LivingEntity victim, DamageSource damageSource) {
		if (level == null || !(victim instanceof ServerPlayer) || damageSource == null) {
			return;
		}
		long nowTick = level.getGameTime();
		LITTLE_DICTATOR_HANDLED_PLAYER_KILL_TICKS.entrySet().removeIf(entry -> entry.getValue() == null || nowTick - entry.getValue() > 40L);
		Long handledTick = LITTLE_DICTATOR_HANDLED_PLAYER_KILL_TICKS.get(victim.getUUID());
		if (handledTick != null && handledTick == nowTick) {
			return;
		}
		LITTLE_DICTATOR_HANDLED_PLAYER_KILL_TICKS.put(victim.getUUID(), nowTick);

		LivingEntity attacker = resolveMarkKillAttacker(victim, damageSource);
		if (!(attacker instanceof ServerPlayer dictator) || dictator == victim || getLittleDictatorShnyagaAbility(dictator) == null) {
			return;
		}
		LittleDictatorDecreeType[] types = LittleDictatorDecreeType.values();
		LittleDictatorDecreeType type = types[level.random.nextInt(types.length)];
		ItemStack decree = createLittleDictatorDecreeStack(type);
		if (!dictator.getInventory().add(decree)) {
			dictator.drop(decree, false);
		}
		dictator.containerMenu.broadcastChanges();
	}

	private static double getLittleDictatorDecreeSanctionsDurationSeconds(RaceAbilityConfig ability) {
		return positiveOrDefault(
				ability == null ? 0.0D : ability.littleDictatorDecreeSanctionsDurationSeconds,
				LITTLE_DICTATOR_DECREE_DEFAULT_SANCTIONS_DURATION_SECONDS
		);
	}

	private static double getLittleDictatorDecreeSanctionsDropChance(RaceAbilityConfig ability) {
		return Mth.clamp(
				ability == null || ability.littleDictatorDecreeSanctionsDropChance <= 0.0D
						? LITTLE_DICTATOR_DECREE_DEFAULT_SANCTIONS_DROP_CHANCE
						: ability.littleDictatorDecreeSanctionsDropChance,
				0.0D,
				1.0D
		);
	}

	private static double getLittleDictatorDecreeTaxesDurationSeconds(RaceAbilityConfig ability) {
		return positiveOrDefault(
				ability == null ? 0.0D : ability.littleDictatorDecreeTaxesDurationSeconds,
				LITTLE_DICTATOR_DECREE_DEFAULT_TAXES_DURATION_SECONDS
		);
	}

	private static double getLittleDictatorDecreeTaxesIntervalSeconds(RaceAbilityConfig ability) {
		return positiveOrDefault(
				ability == null ? 0.0D : ability.littleDictatorDecreeTaxesIntervalSeconds,
				LITTLE_DICTATOR_DECREE_DEFAULT_TAXES_INTERVAL_SECONDS
		);
	}

	private static double getLittleDictatorDecreePropagandaDurationSeconds(RaceAbilityConfig ability) {
		return positiveOrDefault(
				ability == null ? 0.0D : ability.littleDictatorDecreePropagandaDurationSeconds,
				LITTLE_DICTATOR_DECREE_DEFAULT_PROPAGANDA_DURATION_SECONDS
		);
	}

	private static double getLittleDictatorDecreePropagandaTradeDiscount(RaceAbilityConfig ability) {
		return Mth.clamp(
				ability == null || ability.littleDictatorDecreePropagandaTradeDiscount <= 0.0D
						? LITTLE_DICTATOR_DECREE_DEFAULT_PROPAGANDA_TRADE_DISCOUNT
						: ability.littleDictatorDecreePropagandaTradeDiscount,
				0.0D,
				1.0D
		);
	}

	private static void tickLittleDictatorUnique(MinecraftServer server) {
		if (server == null) {
			return;
		}
		tickLittleDictatorUniqueShockWaves(server);
		if (LITTLE_DICTATOR_UNIQUE_SESSIONS.isEmpty()) {
			return;
		}

		long nowTick = server.overworld().getGameTime();
		Iterator<Map.Entry<UUID, LittleDictatorUniqueSession>> iterator = LITTLE_DICTATOR_UNIQUE_SESSIONS.entrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, LittleDictatorUniqueSession> entry = iterator.next();
			UUID dictatorId = entry.getKey();
			LittleDictatorUniqueSession session = entry.getValue();
			ServerPlayer dictator = server.getPlayerList().getPlayer(dictatorId);
			ServerLevel level = session == null ? null : server.getLevel(session.dimension);
			if (session == null || level == null || dictator == null || !dictator.isAlive() || dictator.isSpectator() || nowTick >= session.endTick) {
				iterator.remove();
				cleanupLittleDictatorUniqueSession(server, dictatorId, session, false);
				continue;
			}

			boolean active = nowTick < session.activeEndTick;
			lockLittleDictatorUniqueCasterMovement(dictator, session);
			if (!active) {
				endLittleDictatorUniqueActiveEffects(server, session);
			}
			double scale = getLittleDictatorUniqueScale(session, nowTick);
			syncLittleDictatorUniqueScale(dictator, scale);

			boolean visualTransition = nowTick < session.startTick + LITTLE_DICTATOR_UNIQUE_GROWTH_TICKS || !active;
			if (visualTransition && (nowTick - session.startTick) % 3L == 0L) {
				spawnLittleDictatorUniqueGrowthParticles(level, dictator, scale);
			}

			if (!active) {
				continue;
			}

			syncLittleDictatorUniqueTargets(server, level, dictator, session);

			if (nowTick >= session.nextDrainTick) {
				performLittleDictatorUniqueDrain(level, dictator, session);
				do {
					session.nextDrainTick += LITTLE_DICTATOR_UNIQUE_DRAIN_INTERVAL_TICKS;
				} while (session.nextDrainTick <= nowTick);
			} else if (dictator.getHealth() < dictator.getMaxHealth()
					&& (nowTick - session.startTick) % LITTLE_DICTATOR_UNIQUE_DRAIN_PARTICLE_INTERVAL_TICKS == 0L) {
				spawnLittleDictatorUniqueAmbientDrainParticles(level, dictator, session);
			}

			if (nowTick >= session.nextShockTick) {
				performLittleDictatorUniqueShock(level, dictator, session);
				do {
					session.nextShockTick += session.shockIntervalTicks;
				} while (session.nextShockTick <= nowTick);
			}
		}
	}

	public static boolean handleLittleDictatorUniqueInputPacket(ServerPlayer player, net.minecraft.world.entity.player.Input input) {
		if (player == null) {
			return false;
		}
		LittleDictatorUniqueSession casterSession = LITTLE_DICTATOR_UNIQUE_SESSIONS.get(player.getUUID());
		if (casterSession == null || !casterSession.dimension.equals(player.level().dimension())) {
			return false;
		}
		if (player.level().getGameTime() >= casterSession.endTick) {
			return false;
		}
		boolean shifting = input != null && input.shift();
		player.setLastClientInput(new net.minecraft.world.entity.player.Input(
				false,
				false,
				false,
				false,
				false,
				shifting,
				false
		));
		player.setShiftKeyDown(shifting);
		lockLittleDictatorUniqueCasterMovement(player, casterSession);
		return true;
	}

	public static ServerboundMovePlayerPacket sanitizeLittleDictatorUniqueMovementPacket(
			ServerPlayer player,
			ServerboundMovePlayerPacket packet
	) {
		if (player == null || packet == null || !packet.hasPosition()) {
			return packet;
		}
		LittleDictatorUniqueSession session = LITTLE_DICTATOR_UNIQUE_SESSIONS.get(player.getUUID());
		if (session == null
				|| !session.dimension.equals(player.level().dimension())
				|| player.level().getGameTime() >= session.endTick) {
			return packet;
		}
		requestLittleDictatorUniqueCasterClientPositionSync(player, session, packet);
		double y = packet.getY(player.getY());
		boolean onGround = packet.isOnGround();
		boolean horizontalCollision = packet.horizontalCollision();
		if (packet.hasRotation()) {
			return new ServerboundMovePlayerPacket.PosRot(
					session.lockedPosition.x,
					y,
					session.lockedPosition.z,
					packet.getYRot(player.getYRot()),
					packet.getXRot(player.getXRot()),
					onGround,
					horizontalCollision
			);
		}
		return new ServerboundMovePlayerPacket.Pos(
				session.lockedPosition.x,
				y,
				session.lockedPosition.z,
				onGround,
				horizontalCollision
		);
	}

	public static ServerboundMovePlayerPacket sanitizeKilkaStockLandMovementPacket(
			ServerPlayer player,
			ServerboundMovePlayerPacket packet
	) {
		if (player == null || packet == null || !packet.hasPosition()) {
			return packet;
		}
		if (!shouldSlowKilkaStockLandMovement(player, packet)) {
			return packet;
		}
		double multiplier = getKilkaLandMovementInputMultiplier(getKilkaBootsEnchantmentLevel(player, Enchantments.DEPTH_STRIDER), player.isSprinting());
		if (multiplier >= 1.0D - 1.0E-6D) {
			return packet;
		}
		double packetX = packet.getX(player.getX());
		double packetY = packet.getY(player.getY());
		double packetZ = packet.getZ(player.getZ());
		if (!Double.isFinite(packetX) || !Double.isFinite(packetY) || !Double.isFinite(packetZ)) {
			return packet;
		}
		double dx = packetX - player.getX();
		double dz = packetZ - player.getZ();
		if (dx * dx + dz * dz <= 1.0E-10D) {
			return packet;
		}
		double cappedX = player.getX() + dx * multiplier;
		double cappedZ = player.getZ() + dz * multiplier;
		boolean onGround = packet.isOnGround();
		boolean horizontalCollision = packet.horizontalCollision();
		if (packet.hasRotation()) {
			return new ServerboundMovePlayerPacket.PosRot(
					cappedX,
					packetY,
					cappedZ,
					packet.getYRot(player.getYRot()),
					packet.getXRot(player.getXRot()),
					onGround,
					horizontalCollision
			);
		}
		return new ServerboundMovePlayerPacket.Pos(cappedX, packetY, cappedZ, onGround, horizontalCollision);
	}

	private static boolean shouldSlowKilkaStockLandMovement(ServerPlayer player, ServerboundMovePlayerPacket packet) {
		if (player == null || packet == null || !player.isAlive() || player.isSpectator() || player.isPassenger()) {
			return false;
		}
		if (player.getAbilities().flying || player.isFallFlying()) {
			return false;
		}
		if (getKilkaStockAbility(player) == null || isKilkaSalmonForm(player)) {
			return false;
		}
		if (isKilkaFeetInWater(player) || isKilkaHeadUnderwater(player)) {
			return false;
		}
		return player.onGround() || packet.isOnGround();
	}
	public static ServerboundMovePlayerPacket sanitizeKilkaSalmonMovementPacket(
			ServerPlayer player,
			ServerboundMovePlayerPacket packet
	) {
		if (player == null || packet == null || !packet.hasPosition()) {
			return packet;
		}
		if (!isKilkaSalmonForm(player) || !player.isAlive() || player.isSpectator() || player.isPassenger()) {
			return packet;
		}
		if (player.getAbilities().flying || player.isFallFlying()) {
			return packet;
		}

		KilkaSalmonFormSession session = KILKA_SALMON_FORMS.get(player.getUUID());
		long currentTick = player.level().getGameTime();
		if (session != null && session.externalMotionUntilTick >= currentTick) {
			return packet;
		}
		boolean inWater = session != null && isKilkaSalmonInWater(player);
		boolean targetInWater = isKilkaSalmonPacketTargetInWater(player, packet);
		boolean landingOnSolidGround = !targetInWater && isKilkaSalmonLandingAt(player, packet);
		if (landingOnSolidGround || (!inWater && (player.onGround() || packet.isOnGround()))) {
			// Evaluate the packet target as well as the current position. Otherwise the
			// first packet that leaves water is incorrectly capped as aquatic movement.
			syncKilkaSalmonAquaticSpeedModifier(player, session, false);
			syncKilkaSalmonLandSpeedModifier(player, true);
			return packet;
		}
		double packetX = packet.getX(player.getX());
		double packetY = packet.getY(player.getY());
		double packetZ = packet.getZ(player.getZ());
		if (!Double.isFinite(packetX) || !Double.isFinite(packetY) || !Double.isFinite(packetZ)) {
			return packet;
		}
		if (inWater) {
			double deltaX = packetX - player.getX();
			double deltaZ = packetZ - player.getZ();
			double rawHorizontalDistance = Math.sqrt(deltaX * deltaX + deltaZ * deltaZ);
			if (rawHorizontalDistance > 1.0E-8D) {
				boolean sprintSwimming = isKilkaSalmonSprintSwimming(player, session, true);
				// The input packet is accepted at the exact form speed. Vanilla player
				// sprint-swimming is 0.20 blocks/tick; ordinary salmon swim is 0.07.
				double targetDistance = sprintSwimming
						? KILKA_SALMON_PLAYER_SPRINT_SWIM_BLOCKS_PER_TICK * getKilkaSalmonSprintSwimMultiplier(session)
						: KILKA_SALMON_NORMAL_SWIM_BLOCKS_PER_TICK;
				// Never amplify a tiny client correction near a wall. Only cap a move
				// that exceeds the form's allowed distance; the synced attributes drive
				// normal movement and preserve vanilla collision resolution.
				if (rawHorizontalDistance > targetDistance) {
					double scale = targetDistance / rawHorizontalDistance;
					packetX = player.getX() + deltaX * scale;
					packetZ = player.getZ() + deltaZ * scale;
				}
			}
		} else {
			return packet;
		}
		boolean onGround = false;
		boolean horizontalCollision = packet.horizontalCollision();
		if (packet.hasRotation()) {
			return new ServerboundMovePlayerPacket.PosRot(
					packetX,
					packetY,
					packetZ,
					packet.getYRot(player.getYRot()),
					packet.getXRot(player.getXRot()),
					onGround,
					horizontalCollision
			);
		}
		return new ServerboundMovePlayerPacket.Pos(packetX, packetY, packetZ, onGround, horizontalCollision);
	}
	private static boolean isKilkaSalmonLandingAt(ServerPlayer player, ServerboundMovePlayerPacket packet) {
		if (player == null || packet == null || !packet.hasPosition() || !(player.level() instanceof ServerLevel level)) {
			return false;
		}
		double x = packet.getX(player.getX());
		double y = packet.getY(player.getY());
		double z = packet.getZ(player.getZ());
		if (!Double.isFinite(x) || !Double.isFinite(y) || !Double.isFinite(z)) {
			return false;
		}
		BlockPos below = BlockPos.containing(x, y - 0.02D, z);
		net.minecraft.world.phys.shapes.VoxelShape shape = level.getBlockState(below).getCollisionShape(level, below);
		if (shape.isEmpty()) {
			return false;
		}
		double top = below.getY() + shape.max(Direction.Axis.Y);
		return Math.abs(y - top) <= 0.08D;
	}
	private static boolean isKilkaSalmonPacketTargetInWater(ServerPlayer player, ServerboundMovePlayerPacket packet) {
		if (player == null || packet == null || !(player.level() instanceof ServerLevel level)) {
			return false;
		}
		double x = packet.getX(player.getX());
		double y = packet.getY(player.getY());
		double z = packet.getZ(player.getZ());
		if (!Double.isFinite(x) || !Double.isFinite(y) || !Double.isFinite(z)) {
			return isKilkaSalmonInWater(player);
		}
		double height = Math.max(0.35D, player.getBbHeight());
		return level.getFluidState(BlockPos.containing(x, y + 0.08D, z)).is(net.minecraft.tags.FluidTags.WATER)
				|| level.getFluidState(BlockPos.containing(x, y + height * 0.45D, z)).is(net.minecraft.tags.FluidTags.WATER)
				|| level.getFluidState(BlockPos.containing(x, y + height * 0.85D, z)).is(net.minecraft.tags.FluidTags.WATER);
	}

	private static ServerboundMovePlayerPacket copyKilkaSalmonMovePacketAtCurrentHorizontalPosition(ServerPlayer player, ServerboundMovePlayerPacket packet) {
		if (player == null || packet == null) {
			return packet;
		}
		double y = packet.getY(player.getY());
		if (packet.hasRotation()) {
			return new ServerboundMovePlayerPacket.PosRot(
					player.getX(),
					y,
					player.getZ(),
					packet.getYRot(player.getYRot()),
					packet.getXRot(player.getXRot()),
					packet.isOnGround(),
					packet.horizontalCollision()
			);
		}
		return new ServerboundMovePlayerPacket.Pos(player.getX(), y, player.getZ(), packet.isOnGround(), packet.horizontalCollision());
	}
	private static void requestLittleDictatorUniqueCasterClientPositionSync(
			ServerPlayer player,
			LittleDictatorUniqueSession session,
			ServerboundMovePlayerPacket packet
	) {
		if (player == null || player.connection == null || session == null || packet == null || !packet.hasPosition()) {
			return;
		}
		Vec3 lockedPosition = session.lockedPosition;
		if (lockedPosition == null) {
			return;
		}
		double packetX = packet.getX(player.getX());
		double packetZ = packet.getZ(player.getZ());
		if (Math.abs(packetX - lockedPosition.x) <= LITTLE_DICTATOR_UNIQUE_CLIENT_POSITION_EPSILON
				&& Math.abs(packetZ - lockedPosition.z) <= LITTLE_DICTATOR_UNIQUE_CLIENT_POSITION_EPSILON) {
			return;
		}
		double y = packet.getY(player.getY());
		float yaw = packet.hasRotation() ? packet.getYRot(player.getYRot()) : player.getYRot();
		float pitch = packet.hasRotation() ? Mth.clamp(packet.getXRot(player.getXRot()), -90.0F, 90.0F) : player.getXRot();
		player.connection.teleport(lockedPosition.x, y, lockedPosition.z, yaw, pitch);
	}

	public static boolean handleLittleDictatorUniqueMovementPacket(ServerPlayer player, ServerboundMovePlayerPacket packet) {
		if (player == null || packet == null) {
			return false;
		}
		MinecraftServer server = player.level() == null ? null : player.level().getServer();
		if (server == null) {
			return false;
		}
		LittleDictatorUniqueSession casterSession = LITTLE_DICTATOR_UNIQUE_SESSIONS.get(player.getUUID());
		if (casterSession != null && casterSession.dimension.equals(player.level().dimension())) {
			if (packet.hasRotation()) {
				float yaw = packet.getYRot(player.getYRot());
				float pitch = Mth.clamp(packet.getXRot(player.getXRot()), -90.0F, 90.0F);
				player.setYRot(yaw);
				player.setXRot(pitch);
				player.yRotO = yaw;
				player.xRotO = pitch;
				player.setYHeadRot(yaw);
				player.yHeadRotO = yaw;
				player.setYBodyRot(yaw);
				player.yBodyRotO = yaw;
			}
			lockLittleDictatorUniqueCasterMovement(player, casterSession);
			return false;
		}
		if (packet.hasRotation()) {
			ServerPlayer dictator = findLittleDictatorUniqueCameraLockDictator(server, player);
			if (dictator != null) {
				if (shouldSyncLittleDictatorUniqueLook(player)) {
					forceLittleDictatorUniqueLookAtCaster(player, dictator, LITTLE_DICTATOR_UNIQUE_LOOK_RETURN_STEP_DEGREES);
				}
				return !packet.hasPosition();
			}
		}
		return false;
	}

	public static boolean handleLittleDictatorUniqueVehicleMovePacket(ServerPlayer player) {
		if (player == null) {
			return false;
		}
		MinecraftServer server = player.level() == null ? null : player.level().getServer();
		if (server == null) {
			return false;
		}
		LittleDictatorUniqueSession casterSession = LITTLE_DICTATOR_UNIQUE_SESSIONS.get(player.getUUID());
		if (casterSession != null && player.level().getGameTime() < casterSession.endTick) {
			player.stopRiding();
			lockLittleDictatorUniqueCasterMovement(player);
			return true;
		}
		ServerPlayer dictator = findLittleDictatorUniqueCameraLockDictator(server, player);
		if (dictator == null) {
			return false;
		}
		return false;
	}

	private static ServerPlayer findLittleDictatorUniqueCameraLockDictator(MinecraftServer server, ServerPlayer target) {
		if (server == null || target == null || LITTLE_DICTATOR_UNIQUE_SESSIONS.isEmpty()) {
			return null;
		}
		long nowTick = server.overworld().getGameTime();
		UUID targetId = target.getUUID();
		for (Map.Entry<UUID, LittleDictatorUniqueSession> entry : LITTLE_DICTATOR_UNIQUE_SESSIONS.entrySet()) {
			LittleDictatorUniqueSession session = entry.getValue();
			if (session == null || nowTick >= session.activeEndTick || !session.gazeLockedPlayers.contains(targetId)) {
				continue;
			}
			ServerPlayer dictator = server.getPlayerList().getPlayer(entry.getKey());
			if (dictator != null
					&& dictator.isAlive()
					&& dictator.level() == target.level()
					&& dictator.level() instanceof ServerLevel level
					&& hasLittleDictatorUniqueLineOfSight(level, dictator, target)) {
				return dictator;
			}
		}
		return null;
	}

	private static void lockLittleDictatorUniqueCasterMovement(ServerPlayer player) {
		LittleDictatorUniqueSession session = player == null ? null : LITTLE_DICTATOR_UNIQUE_SESSIONS.get(player.getUUID());
		lockLittleDictatorUniqueCasterMovement(player, session);
	}

	private static void lockLittleDictatorUniqueCasterMovement(ServerPlayer player, LittleDictatorUniqueSession session) {
		if (player == null || player.connection == null) {
			return;
		}
		if (session == null || !session.dimension.equals(player.level().dimension())) {
			return;
		}
		if (player.level().getGameTime() >= session.endTick) {
			return;
		}
		syncLittleDictatorUniqueMovementLock(player, true);
		player.setNoGravity(false);
		player.setSprinting(false);
		player.setYBodyRot(player.getYRot());
		player.yBodyRotO = player.getYRot();
		Vec3 lockedPosition = session.lockedPosition;
		double currentY = player.getY();
		if (lockedPosition != null
				&& (Math.abs(player.getX() - lockedPosition.x) > 1.0E-5D
				|| Math.abs(player.getZ() - lockedPosition.z) > 1.0E-5D)) {
			player.connection.teleport(lockedPosition.x, currentY, lockedPosition.z, player.getYRot(), player.getXRot());
		}
		Vec3 currentVelocity = player.getDeltaMovement();
		if (Math.abs(currentVelocity.x) > 1.0E-5D || Math.abs(currentVelocity.z) > 1.0E-5D) {
			player.setDeltaMovement(0.0D, currentVelocity.y, 0.0D);
			player.hurtMarked = true;
			player.connection.send(new ClientboundSetEntityMotionPacket(player));
		}
	}

	private static void syncLittleDictatorUniqueTargets(MinecraftServer server, ServerLevel level, ServerPlayer dictator, LittleDictatorUniqueSession session) {
		if (server == null || level == null || dictator == null || session == null) {
			return;
		}
		Set<UUID> currentTargets = new HashSet<>();
		for (ServerPlayer target : getLittleDictatorUniquePlayersInRadius(level, dictator, session.radius)) {
			if (target == dictator || target.isSpectator() || !target.isAlive()) {
				continue;
			}
			if (!hasLittleDictatorUniqueLineOfSight(level, dictator, target)) {
				continue;
			}
			UUID targetId = target.getUUID();
			currentTargets.add(targetId);
			session.gazeLockedPlayers.add(targetId);
			applyLittleDictatorUniqueSlowness(target, session);
			if (shouldSyncLittleDictatorUniqueLook(target)) {
				forceLittleDictatorUniqueLookAtCaster(target, dictator);
			}
		}
		for (UUID targetId : new ArrayList<>(session.gazeLockedPlayers)) {
			if (currentTargets.contains(targetId)) {
				continue;
			}
			ServerPlayer target = server.getPlayerList().getPlayer(targetId);
			if (target != null) {
				removeLittleDictatorUniqueSlowness(target);
			}
			session.gazeLockedPlayers.remove(targetId);
			session.slowedPlayers.remove(targetId);
		}
	}

	private static void syncLittleDictatorUniqueTargetLook(ServerPlayer target) {
		if (target == null) {
			return;
		}
		MinecraftServer server = target.level() == null ? null : target.level().getServer();
		ServerPlayer dictator = findLittleDictatorUniqueCameraLockDictator(server, target);
		if (dictator != null && shouldSyncLittleDictatorUniqueLook(target)) {
			forceLittleDictatorUniqueLookAtCaster(target, dictator);
		}
	}

	private static boolean shouldSyncLittleDictatorUniqueLook(ServerPlayer target) {
		if (target == null || target.level() == null) {
			return false;
		}
		return target.level().getGameTime() % LITTLE_DICTATOR_UNIQUE_LOOK_SYNC_INTERVAL_TICKS == 0L;
	}

	private static boolean hasLittleDictatorUniqueLineOfSight(ServerLevel level, ServerPlayer dictator, ServerPlayer target) {
		if (level == null || dictator == null || target == null || dictator.level() != level || target.level() != level) {
			return false;
		}
		Vec3 start = dictator.getEyePosition();
		Vec3 end = target.getEyePosition();
		BlockHitResult hit = level.clip(new ClipContext(start, end, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, dictator));
		return hit.getType() == HitResult.Type.MISS;
	}

	private static double getLittleDictatorUniqueScale(LittleDictatorUniqueSession session, long nowTick) {
		if (session == null) {
			return 1.0D;
		}
		if (nowTick < session.activeEndTick) {
			long growthTicks = Math.max(1L, session.growthEndTick - session.startTick);
			double progress = Mth.clamp((nowTick - session.startTick) / (double) growthTicks, 0.0D, 1.0D);
			double eased = progress * progress * (3.0D - 2.0D * progress);
			return 1.0D + (session.targetScale - 1.0D) * eased;
		}
		long shrinkTicks = Math.max(1L, session.endTick - session.activeEndTick);
		double progress = Mth.clamp((nowTick - session.activeEndTick) / (double) shrinkTicks, 0.0D, 1.0D);
		double eased = progress * progress * (3.0D - 2.0D * progress);
		return 1.0D + (session.targetScale - 1.0D) * (1.0D - eased);
	}

	private static void syncLittleDictatorUniqueScale(ServerPlayer player, double scale) {
		if (player == null) {
			return;
		}
		AttributeInstance attribute = player.getAttribute(Attributes.SCALE);
		if (attribute == null) {
			return;
		}
		double amount = Math.max(1.0D, scale) - 1.0D;
		AttributeModifier current = attribute.getModifier(LITTLE_DICTATOR_UNIQUE_SCALE_MODIFIER_ID);
		if (Math.abs(amount) <= 1.0E-6D) {
			if (current != null) {
				attribute.removeModifier(LITTLE_DICTATOR_UNIQUE_SCALE_MODIFIER_ID);
			}
			return;
		}
		if (current == null
				|| current.operation() != AttributeModifier.Operation.ADD_VALUE
				|| Double.compare(current.amount(), amount) != 0) {
			if (current != null) {
				attribute.removeModifier(LITTLE_DICTATOR_UNIQUE_SCALE_MODIFIER_ID);
			}
			attribute.addTransientModifier(new AttributeModifier(LITTLE_DICTATOR_UNIQUE_SCALE_MODIFIER_ID, amount, AttributeModifier.Operation.ADD_VALUE));
		}
	}

	private static void syncLittleDictatorUniqueMovementLock(ServerPlayer player, boolean locked) {
		if (player == null) {
			return;
		}
		syncLittleDictatorUniqueLockAttribute(player.getAttribute(Attributes.JUMP_STRENGTH), LITTLE_DICTATOR_UNIQUE_JUMP_LOCK_MODIFIER_ID, locked);
	}

	private static void syncLittleDictatorUniqueLockAttribute(AttributeInstance attribute, Identifier modifierId, boolean locked) {
		if (attribute == null || modifierId == null) {
			return;
		}
		AttributeModifier current = attribute.getModifier(modifierId);
		if (!locked) {
			if (current != null) {
				attribute.removeModifier(modifierId);
			}
			return;
		}
		if (current == null
				|| current.operation() != AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL
				|| Double.compare(current.amount(), -1.0D) != 0) {
			if (current != null) {
				attribute.removeModifier(modifierId);
			}
			attribute.addTransientModifier(new AttributeModifier(modifierId, -1.0D, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
		}
	}
	private static void forceLittleDictatorUniqueLookAtCaster(ServerPlayer target, ServerPlayer dictator) {
		forceLittleDictatorUniqueLookAtCaster(target, dictator, LITTLE_DICTATOR_UNIQUE_LOOK_STEP_DEGREES);
	}

	private static void forceLittleDictatorUniqueLookAtCaster(ServerPlayer target, ServerPlayer dictator, float stepDegrees) {
		if (target == null || dictator == null || target.connection == null || target.level() != dictator.level()) {
			return;
		}
		Vec3 direction = dictator.getEyePosition().subtract(target.getEyePosition());
		if (direction.lengthSqr() <= 1.0E-6D) {
			return;
		}
		float targetYaw = yawFromDirection(direction);
		float targetPitch = Mth.clamp(pitchFromDirection(direction), -90.0F, 90.0F);
		float clampedStep = Math.max(0.5F, stepDegrees);
		float yaw = approachAngleDegrees(target.getYRot(), targetYaw, clampedStep);
		float pitch = approachDegrees(target.getXRot(), targetPitch, clampedStep);
		target.setYRot(yaw);
		target.setXRot(pitch);
		target.yRotO = yaw;
		target.xRotO = pitch;
		target.setYHeadRot(yaw);
		target.yHeadRotO = yaw;
		target.connection.send(new ClientboundPlayerRotationPacket(yaw, false, pitch, false));
	}

	private static double getLittleDictatorUniqueVisualScale(ServerPlayer dictator) {
		if (dictator == null) {
			return 1.0D;
		}
		AttributeInstance scaleAttribute = dictator.getAttribute(Attributes.SCALE);
		if (scaleAttribute == null) {
			return 1.0D;
		}
		return Math.max(1.0D, scaleAttribute.getValue());
	}

	private static Vec3 getLittleDictatorUniqueBodyCenter(ServerPlayer dictator) {
		if (dictator == null) {
			return Vec3.ZERO;
		}
		double visualHeight = Math.max(dictator.getBbHeight(), 1.8D * getLittleDictatorUniqueVisualScale(dictator));
		return dictator.position().add(0.0D, visualHeight * 0.5D, 0.0D);
	}

	private static List<ServerPlayer> getLittleDictatorUniquePlayersInRadius(ServerLevel level, ServerPlayer dictator, double radius) {
		if (level == null || dictator == null || radius <= 0.0D) {
			return List.of();
		}
		double radiusSqr = radius * radius;
		Vec3 center = getLittleDictatorUniqueBodyCenter(dictator);
		AABB area = new AABB(
				center.x - radius,
				center.y - radius,
				center.z - radius,
				center.x + radius,
				center.y + radius,
				center.z + radius
		);
		return level.getEntitiesOfClass(ServerPlayer.class, area, candidate -> {
			if (candidate == null || candidate.isSpectator() || !candidate.isAlive()) {
				return false;
			}
			Vec3 candidateCenter = candidate.position().add(0.0D, Math.max(0.5D, candidate.getBbHeight() * 0.5D), 0.0D);
			return candidateCenter.distanceToSqr(center) <= radiusSqr;
		});
	}

	private static void applyLittleDictatorUniqueSlowness(ServerPlayer target, LittleDictatorUniqueSession session) {
		if (target == null || session == null) {
			return;
		}
		session.slowedPlayers.add(target.getUUID());
		MobEffectInstance current = target.getEffect(MobEffects.SLOWNESS);
		int amplifier = LITTLE_DICTATOR_UNIQUE_SLOWNESS_LEVEL - 1;
		if (current != null && current.getAmplifier() >= amplifier && current.getDuration() == MobEffectInstance.INFINITE_DURATION) {
			return;
		}
		target.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, MobEffectInstance.INFINITE_DURATION, amplifier, false, true, true));
	}

	private static void removeLittleDictatorUniqueSlowness(ServerPlayer target) {
		if (target == null) {
			return;
		}
		MobEffectInstance current = target.getEffect(MobEffects.SLOWNESS);
		if (current != null
				&& current.getAmplifier() == LITTLE_DICTATOR_UNIQUE_SLOWNESS_LEVEL - 1
				&& current.getDuration() == MobEffectInstance.INFINITE_DURATION) {
			target.removeEffect(MobEffects.SLOWNESS);
		}
	}

	private static void performLittleDictatorUniqueShock(ServerLevel level, ServerPlayer dictator, LittleDictatorUniqueSession session) {
		if (level == null || dictator == null || session == null) {
			return;
		}
		List<ServerPlayer> targets = getLittleDictatorUniquePlayersInRadius(level, dictator, session.radius).stream()
				.filter(target -> target != dictator)
				.toList();
		if (!targets.isEmpty()) {
			for (ServerPlayer target : targets) {
				double targetCountMultiplier = getLittleDictatorUniqueShockTargetCountMultiplier(session.shockTargetCountMultiplierMin, session.shockTargetCountMultiplierMax, dictator, target, session.radius);
				float ratio = (float) (0.10D + targetCountMultiplier * targets.size());
				float health = target.getHealth();
				int damage = Math.max(0, Math.round(health * ratio));
				if (damage <= 0) {
					continue;
				}
				target.invulnerableTime = 0;
				target.setLastHurtByPlayer(dictator, 100);
				target.setLastHurtByMob(dictator);
				dictator.setLastHurtMob(target);
				if (damage >= health) {
					target.setHealth(0.0F);
				} else {
					target.setHealth(Math.max(0.0F, health - damage));
				}
				target.hurtMarked = true;
			}
		}
		Vec3 origin = getLittleDictatorUniqueBodyCenter(dictator);
		for (ServerPlayer target : targets) {
			shakeLittleDictatorUniqueScreen(target, origin);
		}
		shakeLittleDictatorUniqueScreen(dictator, origin);
		playLittleDictatorUniqueShockSound(level, origin);
		spawnLittleDictatorUniqueShockParticles(level, origin, session.radius);
		startLittleDictatorUniqueShockWave(level, dictator, Math.max(3.0D, session.radius));
	}

	private static void shakeLittleDictatorUniqueScreen(ServerPlayer player, Vec3 origin) {
		if (player == null || player.connection == null || origin == null) {
			return;
		}
		Vec3 direction = player.position().subtract(origin);
		float yaw = direction.lengthSqr() <= 1.0E-6D ? player.getYRot() : yawFromDirection(direction);
		player.connection.send(new ClientboundHurtAnimationPacket(player.getId(), yaw));
	}

	private static void playLittleDictatorUniqueShockSound(ServerLevel level, Vec3 origin) {
		if (level == null || origin == null) {
			return;
		}
		double maxDistanceSqr = LITTLE_DICTATOR_UNIQUE_SHOCK_SOUND_RANGE_BLOCKS * LITTLE_DICTATOR_UNIQUE_SHOCK_SOUND_RANGE_BLOCKS;
		long seed = level.getRandom().nextLong();
		for (ServerPlayer player : level.players()) {
			if (player == null || player.connection == null || player.isSpectator() || !player.isAlive()) {
				continue;
			}
			if (player.distanceToSqr(origin.x, origin.y, origin.z) > maxDistanceSqr) {
				continue;
			}
			if (PolymerResourcePackUtils.hasMainPack(player)) {
				player.connection.send(new ClientboundSoundPacket(
						LITTLE_DICTATOR_UNIQUE_SHOCK_SOUND,
						SoundSource.PLAYERS,
						origin.x,
						origin.y,
						origin.z,
						LITTLE_DICTATOR_UNIQUE_SHOCK_SOUND_VOLUME,
						LITTLE_DICTATOR_UNIQUE_SHOCK_SOUND_PITCH,
						seed
				));
				continue;
			}
			player.connection.send(new ClientboundSoundPacket(
					BuiltInRegistries.SOUND_EVENT.wrapAsHolder(SoundEvents.WARDEN_SONIC_BOOM),
					SoundSource.PLAYERS,
					origin.x,
					origin.y,
					origin.z,
					4.0F,
					0.72F,
					seed
			));
			player.connection.send(new ClientboundSoundPacket(
					BuiltInRegistries.SOUND_EVENT.wrapAsHolder(SoundEvents.GENERIC_EXPLODE.value()),
					SoundSource.PLAYERS,
					origin.x,
					origin.y,
					origin.z,
					2.3F,
					0.55F,
					seed + 1L
			));
			player.connection.send(new ClientboundSoundPacket(
					BuiltInRegistries.SOUND_EVENT.wrapAsHolder(SoundEvents.ANVIL_LAND),
					SoundSource.PLAYERS,
					origin.x,
					origin.y,
					origin.z,
					1.8F,
					0.45F,
					seed + 2L
			));
		}
	}

	private static void performLittleDictatorUniqueDrain(ServerLevel level, ServerPlayer dictator, LittleDictatorUniqueSession session) {
		if (level == null || dictator == null || session == null || dictator.getHealth() >= dictator.getMaxHealth()) {
			return;
		}
		for (ServerPlayer target : getLittleDictatorUniquePlayersInRadius(level, dictator, session.radius)) {
			if (dictator.getHealth() >= dictator.getMaxHealth()) {
				break;
			}
			if (target == dictator || target.isSpectator() || !target.isAlive()) {
				continue;
			}
			if (!hasLittleDictatorUniqueLineOfSight(level, dictator, target)) {
				continue;
			}
			if (drainLittleDictatorUniqueResource(level, target, dictator, session)) {
				spawnLittleDictatorUniqueDrainParticles(level, target, dictator);
			}
		}
	}

	private static boolean drainLittleDictatorUniqueResource(ServerLevel level, ServerPlayer target, ServerPlayer dictator, LittleDictatorUniqueSession session) {
		if (level == null || target == null || dictator == null || session == null || dictator.getHealth() >= dictator.getMaxHealth()) {
			return false;
		}
		boolean hasXp = getLittleDictatorUniqueTotalExperience(target) > 0;
		boolean hasFood = hasLittleDictatorUniqueFoodResource(target);
		if (!hasXp && !hasFood) {
			return false;
		}
		boolean drainXp = hasXp && (!hasFood || level.random.nextBoolean());
		if (drainXp) {
			int drained = drainLittleDictatorUniqueExperience(target, 1);
			if (drained <= 0) {
				return false;
			}
			session.drainedExperienceBank += drained;
		} else {
			double drained = drainLittleDictatorUniqueFood(target, 1.0D);
			if (drained <= 1.0E-6D) {
				return false;
			}
			session.drainedFoodBank += drained;
		}
		convertLittleDictatorUniqueDrainedResourcesToHealth(dictator, session);
		return true;
	}

	private static void convertLittleDictatorUniqueDrainedResourcesToHealth(ServerPlayer dictator, LittleDictatorUniqueSession session) {
		if (dictator == null || session == null) {
			return;
		}
		while (dictator.getHealth() < dictator.getMaxHealth() && session.drainedExperienceBank + 1.0E-6D >= session.xpPerHealth) {
			session.drainedExperienceBank -= session.xpPerHealth;
			dictator.heal(1.0F);
		}
		while (dictator.getHealth() < dictator.getMaxHealth() && session.drainedFoodBank + 1.0E-6D >= session.foodPerHealth) {
			session.drainedFoodBank -= session.foodPerHealth;
			dictator.heal(1.0F);
		}
	}

	private static boolean hasLittleDictatorUniqueFoodResource(ServerPlayer target) {
		if (target == null || target.getFoodData() == null) {
			return false;
		}
		FoodData foodData = target.getFoodData();
		return foodData.getFoodLevel() > 0 || foodData.getSaturationLevel() > 1.0E-4F;
	}

	private static double drainLittleDictatorUniqueFood(ServerPlayer target, double amount) {
		if (target == null || target.getFoodData() == null || amount <= 0.0D) {
			return 0.0D;
		}
		FoodData foodData = target.getFoodData();
		double remaining = amount;
		double drained = 0.0D;
		int foodLevel = foodData.getFoodLevel();
		int foodDrain = Math.min(foodLevel, (int) Math.ceil(remaining));
		if (foodDrain > 0) {
			foodData.setFoodLevel(foodLevel - foodDrain);
			remaining -= foodDrain;
			drained += foodDrain;
		}
		float saturation = foodData.getSaturationLevel();
		if (remaining > 0.0D && saturation > 0.0F) {
			float saturationDrain = Math.min(saturation, (float) remaining);
			foodData.setSaturation(Math.max(0.0F, saturation - saturationDrain));
			drained += saturationDrain;
		}
		return drained;
	}

	private static int getLittleDictatorUniqueTotalExperience(ServerPlayer player) {
		if (player == null) {
			return 0;
		}
		return Math.max(0, player.totalExperience);
	}

	private static int drainLittleDictatorUniqueExperience(ServerPlayer player, int amount) {
		if (player == null || amount <= 0) {
			return 0;
		}
		int current = getLittleDictatorUniqueTotalExperience(player);
		if (current <= 0) {
			return 0;
		}
		int drained = Math.min(current, amount);
		setLittleDictatorUniqueTotalExperience(player, current - drained);
		return drained;
	}

	private static void setLittleDictatorUniqueTotalExperience(ServerPlayer player, int totalExperience) {
		if (player == null) {
			return;
		}
		int remaining = Math.max(0, totalExperience);
		int level = 0;
		while (remaining >= getLittleDictatorUniqueXpNeededForNextLevel(level)) {
			remaining -= getLittleDictatorUniqueXpNeededForNextLevel(level);
			level++;
		}
		int needed = Math.max(1, getLittleDictatorUniqueXpNeededForNextLevel(level));
		player.totalExperience = totalExperience;
		player.experienceLevel = level;
		player.experienceProgress = remaining / (float) needed;
		if (player.connection != null) {
			player.connection.send(new ClientboundSetExperiencePacket(player.experienceProgress, player.totalExperience, player.experienceLevel));
		}
	}

	private static int getLittleDictatorUniqueXpNeededForNextLevel(int level) {
		if (level >= 30) {
			return 112 + (level - 30) * 9;
		}
		if (level >= 15) {
			return 37 + (level - 15) * 5;
		}
		return 7 + level * 2;
	}

	private static void spawnLittleDictatorUniqueActivationParticles(ServerLevel level, ServerPlayer dictator) {
		if (level == null || dictator == null) {
			return;
		}
		Vec3 center = getLittleDictatorUniqueBodyCenter(dictator);
		double visualScale = Math.max(1.0D, getLittleDictatorUniqueVisualScale(dictator));
		double radius = Math.min(4.7D, 0.24D * visualScale + 1.45D);
		DustParticleOptions crimson = new DustParticleOptions(0x8C0A24, 2.05F);
		DustParticleOptions blue = new DustParticleOptions(0x316DFF, 1.9F);
		DustParticleOptions whiteHot = new DustParticleOptions(0xF8FCFF, 1.7F);
		for (int layer = 0; layer < 3; layer++) {
			double layerFactor = 0.34D + layer * 0.26D;
			int points = 52 + layer * 34;
			for (int i = 0; i < points; i++) {
				double unitY = 1.0D - 2.0D * ((i + 0.5D) / points);
				double horizontal = Math.sqrt(Math.max(0.0D, 1.0D - unitY * unitY));
				double angle = i * 2.399963229728653D + layer * 0.63D;
				Vec3 normal = new Vec3(Math.cos(angle) * horizontal, unitY * 0.95D, Math.sin(angle) * horizontal);
				double wobble = Math.sin(angle * 3.2D + layer * 1.4D) * 0.16D;
				Vec3 pos = center.add(normal.scale(radius * layerFactor + wobble));
				Vec3 velocity = normal.scale(0.16D + layer * 0.05D + (i % 4) * 0.015D);
				DustParticleOptions dust = switch ((i + layer) % 6) {
					case 0, 3 -> whiteHot;
					case 1, 4 -> blue;
					default -> crimson;
				};
				level.sendParticles(dust, pos.x, pos.y, pos.z, 0, velocity.x, velocity.y + 0.025D, velocity.z, 1.0D);
			}
		}
		for (int i = 0; i < 34; i++) {
			double angle = (Math.PI * 2.0D * i) / 34.0D;
			double ringRadius = radius * (0.44D + 0.08D * Math.sin(i * 0.7D));
			double x = dictator.getX() + Math.cos(angle) * ringRadius;
			double z = dictator.getZ() + Math.sin(angle) * ringRadius;
			level.sendParticles(i % 2 == 0 ? ParticleTypes.END_ROD : ParticleTypes.ENCHANT, x, dictator.getY() + 0.08D, z, 1, 0.03D, 0.34D, 0.03D, 0.02D);
		}
		level.sendParticles(ParticleTypes.REVERSE_PORTAL, center.x, center.y, center.z, 44, 0.85D, 1.15D, 0.85D, 0.06D);
		level.sendParticles(ParticleTypes.SMOKE, center.x, center.y, center.z, 28, 0.6D, 0.95D, 0.6D, 0.03D);
		level.sendParticles(ParticleTypes.CLOUD, center.x, center.y, center.z, 24, 0.5D, 0.85D, 0.5D, 0.03D);
	}

	private static void spawnLittleDictatorUniqueGrowthParticles(ServerLevel level, ServerPlayer dictator, double scale) {
		if (level == null || dictator == null) {
			return;
		}
		Vec3 center = getLittleDictatorUniqueBodyCenter(dictator);
		double visualScale = Math.max(1.0D, scale);
		double visualHeight = Math.max(dictator.getBbHeight(), 1.8D * getLittleDictatorUniqueVisualScale(dictator));
		double pulse = Mth.clamp((visualScale - 1.0D) / Math.max(0.001D, LITTLE_DICTATOR_UNIQUE_TARGET_SCALE - 1.0D), 0.0D, 1.0D);
		double burstRadius = 0.55D + pulse * 1.85D;
		double phase = (level.getGameTime() - dictator.getId() * 0.23D) * 0.28D;
		DustParticleOptions crimson = new DustParticleOptions(0x8B001F, 1.38F);
		DustParticleOptions blue = new DustParticleOptions(0x245FFF, 1.22F);
		DustParticleOptions whiteHot = new DustParticleOptions(0xF6FBFF, 1.08F);
		for (int i = 0; i < 28; i++) {
			double t = i / 28.0D;
			double angle = phase + t * Math.PI * 7.2D;
			double y = dictator.getY() + 0.18D + visualHeight * t;
			double radius = burstRadius * (0.22D + t * 0.56D);
			Vec3 pos = new Vec3(center.x + Math.cos(angle) * radius, y, center.z + Math.sin(angle) * radius);
			DustParticleOptions dust = i % 5 == 0 ? whiteHot : (i % 2 == 0 ? blue : crimson);
			level.sendParticles(dust, pos.x, pos.y, pos.z, 0, 0.0D, 0.055D + t * 0.01D, 0.0D, 1.0D);
		}
		for (int i = 0; i < 12; i++) {
			double unitY = -0.2D + 1.4D * (i / 17.0D);
			double angle = phase * 1.4D + i * 2.399963229728653D;
			double horizontal = 0.25D + pulse * 0.55D;
			Vec3 pos = new Vec3(center.x + Math.cos(angle) * horizontal, dictator.getY() + visualHeight * (0.08D + i / 22.0D), center.z + Math.sin(angle) * horizontal);
			level.sendParticles(i % 3 == 0 ? ParticleTypes.END_ROD : ParticleTypes.ENCHANT, pos.x, pos.y, pos.z, 1, 0.01D, 0.05D, 0.01D, 0.01D);
		}
	}
	private static void spawnLittleDictatorUniqueAuraParticles(ServerLevel level, ServerPlayer dictator, LittleDictatorUniqueSession session, double scale, boolean active) {
	}

	private static void spawnLittleDictatorUniqueShockParticles(ServerLevel level, Vec3 origin, double radius) {
		if (level == null || origin == null || radius <= 0.0D) {
			return;
		}
		double maxRadius = Math.max(3.0D, radius);
		level.sendParticles(ParticleTypes.SONIC_BOOM, origin.x, origin.y, origin.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
		level.sendParticles(ParticleTypes.EXPLOSION, origin.x, origin.y, origin.z, 22, 3.5D, 1.9D, 3.5D, 0.0D);
		level.sendParticles(ParticleTypes.LARGE_SMOKE, origin.x, origin.y, origin.z, 104, 3.2D, 2.0D, 3.2D, 0.11D);
		level.sendParticles(ParticleTypes.CLOUD, origin.x, origin.y, origin.z, 68, 3.1D, 1.8D, 3.1D, 0.11D);
		DustParticleOptions whiteHot = new DustParticleOptions(0xF8FDFF, 2.1F);
		DustParticleOptions blue = new DustParticleOptions(0x2F82FF, 2.0F);
		DustParticleOptions red = new DustParticleOptions(0xD91E36, 2.0F);
		for (int layer = 0; layer < 3; layer++) {
			int points = 82 + layer * 34;
			for (int i = 0; i < points; i++) {
				double radialStep = (i + 0.5D) / points;
				double ySeed = radialStep * 1.618033988749895D + layer * 0.17D;
				double unitY = 1.0D - 2.0D * (ySeed - Math.floor(ySeed));
				double horizontal = Math.sqrt(Math.max(0.0D, 1.0D - unitY * unitY));
				double angle = i * 2.399963229728653D + layer * 0.4D;
				Vec3 normal = new Vec3(Math.cos(angle) * horizontal, unitY, Math.sin(angle) * horizontal);
				double spawnRadius = maxRadius * (0.04D + 0.24D * Math.pow(radialStep, 1.72D)) + layer * 0.16D;
				Vec3 pos = origin.add(normal.scale(spawnRadius));
				Vec3 velocity = normal.scale(0.22D + spawnRadius / maxRadius * 0.42D + layer * 0.05D);
				DustParticleOptions dust = switch ((i + layer) % 6) {
					case 0, 3 -> whiteHot;
					case 1, 4 -> blue;
					default -> red;
				};
				level.sendParticles(dust, pos.x, pos.y, pos.z, 0, velocity.x, velocity.y, velocity.z, 1.0D);
			}
		}
		spawnLittleDictatorUniqueShockWaveFrame(level, origin, maxRadius, 0.03D, 0);
	}

	private static void startLittleDictatorUniqueShockWave(ServerLevel level, ServerPlayer dictator, double radius) {
		if (level == null || dictator == null || radius <= 0.0D) {
			return;
		}
		long startTick = level.getGameTime();
		LITTLE_DICTATOR_UNIQUE_SHOCK_WAVES.add(new LittleDictatorUniqueShockWaveSession(
				level.dimension(),
				dictator.getUUID(),
				startTick,
				startTick + LITTLE_DICTATOR_UNIQUE_SHOCK_WAVE_TICKS,
				radius
		));
	}

	private static void tickLittleDictatorUniqueShockWaves(MinecraftServer server) {
		if (server == null || LITTLE_DICTATOR_UNIQUE_SHOCK_WAVES.isEmpty()) {
			return;
		}
		Iterator<LittleDictatorUniqueShockWaveSession> iterator = LITTLE_DICTATOR_UNIQUE_SHOCK_WAVES.iterator();
		while (iterator.hasNext()) {
			LittleDictatorUniqueShockWaveSession session = iterator.next();
			ServerLevel level = server.getLevel(session.dimension());
			if (level == null) {
				iterator.remove();
				continue;
			}
			long nowTick = level.getGameTime();
			if (nowTick > session.endTick()) {
				iterator.remove();
				continue;
			}
			long ageTicks = nowTick - session.startTick();
			if (ageTicks > 0L && nowTick < session.endTick() && ageTicks % LITTLE_DICTATOR_UNIQUE_SHOCK_WAVE_FRAME_INTERVAL_TICKS != 0L) {
				continue;
			}
			double duration = Math.max(1.0D, session.endTick() - session.startTick());
			double progress = Mth.clamp(ageTicks / duration, 0.0D, 1.0D);
			ServerPlayer dictator = server.getPlayerList().getPlayer(session.dictatorId());
			if (dictator == null || !dictator.isAlive() || dictator.isSpectator() || dictator.level() != level) {
				iterator.remove();
				continue;
			}
			Vec3 origin = getLittleDictatorUniqueBodyCenter(dictator);
			spawnLittleDictatorUniqueShockWaveFrame(level, origin, session.maxRadius(), progress, (int) ageTicks);
		}
	}

	private static void spawnLittleDictatorUniqueShockWaveFrame(ServerLevel level, Vec3 origin, double maxRadius, double progress, int ageTicks) {
		if (level == null || origin == null || maxRadius <= 0.0D) {
			return;
		}
		double eased = 1.0D - Math.pow(1.0D - Mth.clamp(progress, 0.0D, 1.0D), 1.8D);
		double frontRadius = Math.max(1.0D, maxRadius * eased);
		double shellThickness = 0.55D + frontRadius * 0.03D;
		double phase = ageTicks * 0.22D;
		DustParticleOptions whiteHot = new DustParticleOptions(0xF8FDFF, 2.45F);
		DustParticleOptions blue = new DustParticleOptions(0x2F82FF, 2.25F);
		DustParticleOptions red = new DustParticleOptions(0xD61D34, 2.25F);
		int shellPoints = Math.max(230, Math.min(560, (int) Math.round(frontRadius * 13.6D)));
		for (int layer = 0; layer < 4; layer++) {
			double layerOffset = (layer - 1.5D) * shellThickness * 0.58D;
			double layerVelocity = 0.18D + progress * 0.34D + layer * 0.035D;
			for (int i = 0; i < shellPoints; i++) {
				double unitY = 1.0D - 2.0D * ((i + 0.5D) / shellPoints);
				double horizontal = Math.sqrt(Math.max(0.0D, 1.0D - unitY * unitY));
				double angle = i * 2.399963229728653D + phase + layer * 0.31D;
				Vec3 normal = new Vec3(Math.cos(angle) * horizontal, unitY, Math.sin(angle) * horizontal);
				double ripple = Math.sin(angle * 4.6D + ageTicks * 0.78D + layer * 0.7D) * shellThickness * 0.34D;
				Vec3 pos = origin.add(normal.scale(frontRadius + layerOffset + ripple));
				Vec3 velocity = normal.scale(layerVelocity);
				DustParticleOptions dust = switch ((i + layer) % 6) {
					case 0, 3 -> whiteHot;
					case 1, 4 -> blue;
					default -> red;
				};
				level.sendParticles(dust, pos.x, pos.y, pos.z, 0, velocity.x, velocity.y, velocity.z, 1.0D);
			}
		}
		int coreBursts = Math.max(78, Math.min(190, (int) Math.round(frontRadius * 4.9D)));
		for (int i = 0; i < coreBursts; i++) {
			double radialStep = (i + 0.5D) / coreBursts;
			double ySeed = radialStep * 1.618033988749895D;
			double unitY = 1.0D - 2.0D * (ySeed - Math.floor(ySeed));
			double horizontal = Math.sqrt(Math.max(0.0D, 1.0D - unitY * unitY));
			double angle = i * 2.399963229728653D - phase * 0.65D;
			Vec3 normal = new Vec3(Math.cos(angle) * horizontal, unitY, Math.sin(angle) * horizontal);
			double burstRadius = frontRadius * (0.08D + 0.66D * Math.pow(radialStep, 1.85D));
			Vec3 pos = origin.add(normal.scale(burstRadius));
			Vec3 velocity = normal.scale(0.08D + progress * 0.2D + burstRadius / Math.max(1.0D, frontRadius) * 0.16D);
			DustParticleOptions dust = switch (i % 6) {
				case 0, 3 -> whiteHot;
				case 1, 4 -> blue;
				default -> red;
			};
			level.sendParticles(dust, pos.x, pos.y, pos.z, 0, velocity.x, velocity.y, velocity.z, 1.0D);
		}
		int shockRays = 64;
		for (int i = 0; i < shockRays; i++) {
			double unitY = 1.0D - 2.0D * ((i + 0.5D) / shockRays);
			double horizontal = Math.sqrt(Math.max(0.0D, 1.0D - unitY * unitY));
			double angle = phase * 0.72D + i * 2.399963229728653D;
			Vec3 dir = new Vec3(Math.cos(angle) * horizontal, unitY, Math.sin(angle) * horizontal);
			for (int segment = 1; segment <= 5; segment++) {
				double segmentStep = segment / 5.0D;
				double distance = frontRadius * (0.12D + 0.88D * Math.pow(segmentStep, 1.55D));
				Vec3 pos = origin.add(dir.scale(distance));
				DustParticleOptions dust = segment >= 4 ? whiteHot : (segment % 2 == 0 ? blue : red);
				level.sendParticles(dust, pos.x, pos.y, pos.z, 0, dir.x * 0.22D, dir.y * 0.22D, dir.z * 0.22D, 1.0D);
			}
		}
		if ((ageTicks & 1) == 0) {
			level.sendParticles(ParticleTypes.CLOUD, origin.x, origin.y, origin.z, 42, frontRadius * 0.38D, frontRadius * 0.38D, frontRadius * 0.38D, 0.1D);
			level.sendParticles(ParticleTypes.POOF, origin.x, origin.y, origin.z, 28, frontRadius * 0.3D, frontRadius * 0.3D, frontRadius * 0.3D, 0.055D);
			level.sendParticles(ParticleTypes.EXPLOSION, origin.x, origin.y, origin.z, 5, frontRadius * 0.22D, frontRadius * 0.22D, frontRadius * 0.22D, 0.0D);
		}
	}

	private static void spawnLittleDictatorUniqueAmbientDrainParticles(ServerLevel level, ServerPlayer dictator, LittleDictatorUniqueSession session) {
		if (level == null || dictator == null || session == null) {
			return;
		}
		List<ServerPlayer> targets = getLittleDictatorUniquePlayersInRadius(level, dictator, session.radius).stream()
				.filter(target -> target != dictator && hasLittleDictatorUniqueLineOfSight(level, dictator, target))
				.toList();
		for (ServerPlayer target : targets) {
			if (level.random.nextFloat() < 0.65F) {
				spawnLittleDictatorUniqueDrainParticles(level, target, dictator);
			}
		}
	}

	private static void spawnLittleDictatorUniqueDrainParticles(ServerLevel level, ServerPlayer target, ServerPlayer dictator) {
		if (level == null || target == null || dictator == null) {
			return;
		}
		Vec3 start = target.position().add(0.0D, Math.max(0.7D, target.getBbHeight() * 0.55D), 0.0D);
		Vec3 end = getLittleDictatorUniqueBodyCenter(dictator);
		Vec3 delta = end.subtract(start);
		double length = delta.length();
		if (length <= 1.0E-6D) {
			return;
		}
		Vec3 axis = delta.scale(1.0D / length);
		Vec3 right = axis.cross(new Vec3(0.0D, 1.0D, 0.0D));
		if (right.lengthSqr() <= 1.0E-6D) {
			right = new Vec3(1.0D, 0.0D, 0.0D);
		} else {
			right = right.normalize();
		}
		Vec3 up = right.cross(axis).normalize();
		int steps = Math.max(7, Math.min(12, (int)Math.round(length * 0.82D)));
		double phase = level.getGameTime() * 0.32D + target.getId() * 0.45D;
		DustParticleOptions life = new DustParticleOptions(0x7EFF22, 1.45F);
		DustParticleOptions darkLife = new DustParticleOptions(0x2F8F1B, 1.18F);
		DustParticleOptions hunger = new DustParticleOptions(0xBFFF40, 1.18F);
		DustParticleOptions core = new DustParticleOptions(0xE2FF96, 0.95F);
		for (int i = 1; i <= steps; i++) {
			double t = i / (double) steps;
			Vec3 base = start.add(delta.scale(t));
			double radius = 0.1D + (1.0D - t) * 0.22D + Math.sin(Math.PI * t) * 0.28D;
			double angleA = phase + t * Math.PI * 7.0D;
			double angleB = angleA + Math.PI;
			Vec3 a = base.add(right.scale(Math.cos(angleA) * radius)).add(up.scale(Math.sin(angleA) * radius));
			Vec3 b = base.add(right.scale(Math.cos(angleB) * radius * 0.8D)).add(up.scale(Math.sin(angleB) * radius * 0.8D));
			Vec3 c = base.add(right.scale(Math.cos(angleA + Math.PI * 0.5D) * radius * 0.4D)).add(up.scale(Math.sin(angleA + Math.PI * 0.5D) * radius * 0.4D));
			Vec3 velocity = axis.scale(0.22D + (1.0D - t) * 0.1D);
			level.sendParticles(i % 2 == 0 ? life : darkLife, a.x, a.y, a.z, 0, velocity.x, velocity.y, velocity.z, 1.0D);
			level.sendParticles(i % 3 == 0 ? core : hunger, b.x, b.y, b.z, 0, velocity.x * 0.86D, velocity.y * 0.86D, velocity.z * 0.86D, 1.0D);
			if (i % 3 == 0) {
				level.sendParticles(core, c.x, c.y, c.z, 0, velocity.x, velocity.y, velocity.z, 1.0D);
			}
		}
		for (int i = 0; i < 5; i++) {
			double angle = phase + i * (Math.PI * 2.0D / 8.0D);
			double radius = 0.38D + i * 0.04D;
			Vec3 pos = end.add(right.scale(Math.cos(angle) * radius)).add(up.scale(Math.sin(angle) * radius));
			Vec3 inward = end.subtract(pos).normalize().scale(0.16D).add(axis.scale(0.08D));
			level.sendParticles(i % 2 == 0 ? life : hunger, pos.x, pos.y, pos.z, 0, inward.x, inward.y, inward.z, 1.0D);
		}
		level.sendParticles(core, end.x, end.y, end.z, 4, 0.22D, 0.18D, 0.22D, 0.022D);
	}

	private static void cleanupAllLittleDictatorUniqueSessions(MinecraftServer server) {
		if (LITTLE_DICTATOR_UNIQUE_SESSIONS.isEmpty()) {
			return;
		}
		List<Map.Entry<UUID, LittleDictatorUniqueSession>> sessions = new ArrayList<>(LITTLE_DICTATOR_UNIQUE_SESSIONS.entrySet());
		LITTLE_DICTATOR_UNIQUE_SESSIONS.clear();
		for (Map.Entry<UUID, LittleDictatorUniqueSession> entry : sessions) {
			cleanupLittleDictatorUniqueSession(server, entry.getKey(), entry.getValue(), false);
		}
	}

	private static void endLittleDictatorUniqueActiveEffects(MinecraftServer server, LittleDictatorUniqueSession session) {
		if (server == null || session == null || session.activeEffectsEnded) {
			return;
		}
		session.activeEffectsEnded = true;
		for (UUID targetId : new ArrayList<>(session.slowedPlayers)) {
			ServerPlayer target = server.getPlayerList().getPlayer(targetId);
			removeLittleDictatorUniqueSlowness(target);
		}
		session.slowedPlayers.clear();
		session.gazeLockedPlayers.clear();
	}

	private static void cleanupLittleDictatorUniqueSession(MinecraftServer server, UUID dictatorId, LittleDictatorUniqueSession session, boolean emitParticles) {
		if (dictatorId == null || session == null) {
			return;
		}
		endLittleDictatorUniqueActiveEffects(server, session);
		ServerPlayer dictator = server == null ? null : server.getPlayerList().getPlayer(dictatorId);
		if (dictator != null) {
			dictator.setNoGravity(session.originalNoGravity);
			syncLittleDictatorUniqueMovementLock(dictator, false);
			syncLittleDictatorUniqueScale(dictator, 1.0D);
			if (emitParticles && dictator.level() instanceof ServerLevel level) {
				Vec3 center = getLittleDictatorUniqueBodyCenter(dictator);
				level.sendParticles(ParticleTypes.SMOKE, center.x, center.y, center.z, 24, 0.45D, 0.6D, 0.45D, 0.025D);
			}
		}
		if (server != null) {
			for (UUID targetId : session.slowedPlayers) {
				ServerPlayer target = server.getPlayerList().getPlayer(targetId);
				removeLittleDictatorUniqueSlowness(target);
			}
		}
	}

	private static void clearLittleDictatorUniqueTargetState(ServerPlayer player) {
		if (player == null) {
			return;
		}
		UUID playerId = player.getUUID();
		removeLittleDictatorUniqueSlowness(player);
		for (LittleDictatorUniqueSession session : LITTLE_DICTATOR_UNIQUE_SESSIONS.values()) {
			if (session == null) {
				continue;
			}
			session.gazeLockedPlayers.remove(playerId);
			session.slowedPlayers.remove(playerId);
		}
	}

	private static boolean isLittleDictatorPlayer(ServerPlayer player) {
		if (player == null) {
			return false;
		}
		return getRace(player)
				.map(race -> LITTLE_DICTATOR_RACE_ID.equals(sanitizePath(race.id)))
				.orElse(false);
	}

	private static void tickLittleDictatorDefense(MinecraftServer server) {
		if (server == null) {
			return;
		}
		tickLittleDictatorDefenseWaves(server);
		tickLittleDictatorDelayedPackets(server);
		tickLittleDictatorPingEffects(server);
	}

	private static void tickLittleDictatorDelayedPackets(MinecraftServer server) {
		if (server == null) {
			return;
		}

		long nowTick = server.overworld().getGameTime();
		List<LittleDictatorDelayedPacket> readyPackets = new ArrayList<>();
		synchronized (LITTLE_DICTATOR_DELAYED_PACKETS) {
			if (LITTLE_DICTATOR_DELAYED_PACKETS.isEmpty()) {
				return;
			}
			Iterator<LittleDictatorDelayedPacket> iterator = LITTLE_DICTATOR_DELAYED_PACKETS.iterator();
			while (iterator.hasNext()) {
				LittleDictatorDelayedPacket delayedPacket = iterator.next();
				if (delayedPacket == null || nowTick < delayedPacket.releaseTick()) {
					continue;
				}
				iterator.remove();
				if (delayedPacket.playerId() == null
						|| server.getPlayerList().getPlayer(delayedPacket.playerId()) == null
						|| delayedPacket.action() == null) {
					continue;
				}
				readyPackets.add(delayedPacket);
			}
		}
		for (LittleDictatorDelayedPacket delayedPacket : readyPackets) {
			LITTLE_DICTATOR_REPLAYING_DELAYED_PACKET.set(Boolean.TRUE);
			try {
				delayedPacket.action().run();
			} catch (RuntimeException exception) {
				Lg2.LOGGER.warn("Failed to replay delayed Little Dictator packet for {}", delayedPacket.playerId(), exception);
			} finally {
				LITTLE_DICTATOR_REPLAYING_DELAYED_PACKET.set(Boolean.FALSE);
			}
		}
	}

	private static void tickLittleDictatorDefenseWaves(MinecraftServer server) {
		if (server == null || LITTLE_DICTATOR_DEFENSE_WAVES.isEmpty()) {
			return;
		}

		Iterator<LittleDictatorDefenseWaveSession> iterator = LITTLE_DICTATOR_DEFENSE_WAVES.iterator();
		while (iterator.hasNext()) {
			LittleDictatorDefenseWaveSession session = iterator.next();
			ServerLevel level = server.getLevel(session.dimension());
			if (level == null) {
				iterator.remove();
				continue;
			}

			long nowTick = level.getGameTime();
			if (nowTick > session.endTick()) {
				iterator.remove();
				continue;
			}

			double duration = Math.max(1.0D, session.endTick() - session.startTick());
			double progress = Mth.clamp((nowTick - session.startTick()) / duration, 0.0D, 1.0D);
			double radius = Math.max(0.25D, session.maxRadius() * progress);
			spawnLittleDictatorDefenseWaveParticles(level, session.origin(), radius);
		}
	}

	private static void tickLittleDictatorPingEffects(MinecraftServer server) {
		if (server == null || LITTLE_DICTATOR_PING_SESSIONS.isEmpty()) {
			return;
		}

		long nowTick = server.overworld().getGameTime();
		Iterator<Map.Entry<UUID, LittleDictatorPingSession>> iterator = LITTLE_DICTATOR_PING_SESSIONS.entrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, LittleDictatorPingSession> entry = iterator.next();
			UUID playerId = entry.getKey();
			LittleDictatorPingSession session = entry.getValue();
			if (session == null) {
				LITTLE_DICTATOR_PING_OVERLAY_ACTIVE.remove(playerId);
				LITTLE_DICTATOR_LAST_DELAYED_PACKET_RELEASE_TICKS.remove(playerId);
				iterator.remove();
				continue;
			}

			ServerPlayer player = server.getPlayerList().getPlayer(playerId);
			if (player == null || player.connection == null) {
				entry.setValue(new LittleDictatorPingSession(
						session.endTick() + 1L,
						session.minPingMs(),
						session.maxPingMs(),
						session.nextUpdateTick() + 1L,
						session.lastSentPingMs()
				));
				continue;
			}
			if (nowTick >= session.endTick()) {
				clearLittleDictatorPingEffect(player);
				LITTLE_DICTATOR_LAST_DELAYED_PACKET_RELEASE_TICKS.remove(playerId);
				iterator.remove();
				continue;
			}
			if (isLittleDictatorPlayer(player)) {
				clearLittleDictatorPingEffect(player);
				LITTLE_DICTATOR_LAST_DELAYED_PACKET_RELEASE_TICKS.remove(playerId);
				iterator.remove();
				continue;
			}

			if (nowTick >= session.nextUpdateTick()) {
				int fakePingMs = Mth.nextInt(player.getRandom(), session.minPingMs(), session.maxPingMs());
				sendLittleDictatorLatency(player, fakePingMs);
				syncLittleDictatorDefenseOverlay(player, true, true);
				entry.setValue(new LittleDictatorPingSession(
						session.endTick(),
						session.minPingMs(),
						session.maxPingMs(),
						nowTick + LITTLE_DICTATOR_DEFENSE_PING_UPDATE_TICKS,
						fakePingMs
				));
				continue;
			}

			if ((nowTick + player.getId()) % LITTLE_DICTATOR_DEFENSE_OVERLAY_FRAME_TICKS == 0L) {
				syncLittleDictatorDefenseOverlay(player, true, true);
			}
		}
	}

	private static void clearLittleDictatorPingEffect(ServerPlayer player) {
		if (player == null || player.connection == null) {
			return;
		}
		sendLittleDictatorActualLatency(player);
		syncLittleDictatorDefenseOverlay(player, false, true);
	}

	public static boolean delayLittleDictatorServerboundPacket(ServerPlayer player, Runnable action) {
		if (player == null || player.connection == null || action == null) {
			return false;
		}
		if (isLittleDictatorPlayer(player)) {
			return false;
		}
		if (Boolean.TRUE.equals(LITTLE_DICTATOR_REPLAYING_DELAYED_PACKET.get())) {
			return false;
		}
		LittleDictatorPingSession session = LITTLE_DICTATOR_PING_SESSIONS.get(player.getUUID());
		if (session == null) {
			return false;
		}
		MinecraftServer server = player.level() instanceof ServerLevel serverLevel ? serverLevel.getServer() : null;
		long nowTick = server == null ? player.level().getGameTime() : server.overworld().getGameTime();
		if (nowTick >= session.endTick()) {
			return false;
		}

		int pingMs = session.lastSentPingMs() > 0
				? session.lastSentPingMs()
				: Mth.nextInt(player.getRandom(), session.minPingMs(), session.maxPingMs());
		int delayTicks = Mth.clamp(
				(int) Math.ceil(pingMs / 50.0D),
				LITTLE_DICTATOR_DEFENSE_MIN_PACKET_DELAY_TICKS,
				LITTLE_DICTATOR_DEFENSE_MAX_PACKET_DELAY_TICKS
		);
		return enqueueLittleDictatorDelayedPacket(player, delayTicks, action);
	}

	public static boolean delayLittleDictatorClientboundPacket(ServerPlayer player, Packet<?> packet, Runnable action) {
		if (player == null || player.connection == null || packet == null || action == null) {
			return false;
		}
		if (isLittleDictatorPlayer(player)) {
			return false;
		}
		if (Boolean.TRUE.equals(LITTLE_DICTATOR_REPLAYING_DELAYED_PACKET.get())) {
			return false;
		}
		LittleDictatorPingSession session = LITTLE_DICTATOR_PING_SESSIONS.get(player.getUUID());
		if (session == null) {
			return false;
		}
		MinecraftServer server = player.level() instanceof ServerLevel serverLevel ? serverLevel.getServer() : null;
		long nowTick = server == null ? player.level().getGameTime() : server.overworld().getGameTime();
		if (nowTick >= session.endTick()) {
			return false;
		}

		int pingMs = session.lastSentPingMs() > 0
				? session.lastSentPingMs()
				: Mth.nextInt(player.getRandom(), session.minPingMs(), session.maxPingMs());
		int delayTicks = Mth.clamp(
				(int) Math.ceil(pingMs / 50.0D),
				LITTLE_DICTATOR_DEFENSE_MIN_PACKET_DELAY_TICKS,
				LITTLE_DICTATOR_DEFENSE_MAX_PACKET_DELAY_TICKS
		);
		return enqueueLittleDictatorDelayedPacket(player, delayTicks, action);
	}

	private static boolean enqueueLittleDictatorDelayedPacket(ServerPlayer player, int delayTicks, Runnable action) {
		if (player == null || action == null) {
			return false;
		}
		MinecraftServer server = player.level() instanceof ServerLevel serverLevel ? serverLevel.getServer() : null;
		long nowTick = server == null ? player.level().getGameTime() : server.overworld().getGameTime();
		UUID playerId = player.getUUID();
		long targetReleaseTick = nowTick + delayTicks;
		long lastReleaseTick = LITTLE_DICTATOR_LAST_DELAYED_PACKET_RELEASE_TICKS.getOrDefault(playerId, Long.MIN_VALUE);
		long releaseTick = Math.max(targetReleaseTick, lastReleaseTick);
		LITTLE_DICTATOR_LAST_DELAYED_PACKET_RELEASE_TICKS.put(playerId, releaseTick);
		synchronized (LITTLE_DICTATOR_DELAYED_PACKETS) {
			int queuedForPlayer = 0;
			Iterator<LittleDictatorDelayedPacket> iterator = LITTLE_DICTATOR_DELAYED_PACKETS.iterator();
			while (iterator.hasNext()) {
				LittleDictatorDelayedPacket delayedPacket = iterator.next();
				if (delayedPacket != null && playerId.equals(delayedPacket.playerId())) {
					queuedForPlayer++;
					if (queuedForPlayer >= LITTLE_DICTATOR_DEFENSE_MAX_DELAYED_PACKETS_PER_PLAYER) {
						iterator.remove();
						break;
					}
				}
			}
			LITTLE_DICTATOR_DELAYED_PACKETS.add(new LittleDictatorDelayedPacket(playerId, releaseTick, action));
		}
		return true;
	}

	private static void sendLittleDictatorActualLatency(ServerPlayer player) {
		if (player == null || player.connection == null) {
			return;
		}
		sendLittleDictatorLatency(player, Math.max(0, player.connection.latency()));
	}

	private static void sendLittleDictatorLatency(ServerPlayer player, int latencyMs) {
		if (player == null || player.connection == null) {
			return;
		}
		ClientboundPlayerInfoUpdatePacket packet = PolymerEntityUtils.createMutablePlayerListPacket(
				EnumSet.of(ClientboundPlayerInfoUpdatePacket.Action.UPDATE_LATENCY)
		);
		packet.entries().add(new ClientboundPlayerInfoUpdatePacket.Entry(
				player.getUUID(),
				player.getGameProfile(),
				true,
				Math.max(0, latencyMs),
				player.gameMode == null ? GameType.SURVIVAL : player.gameMode.getGameModeForPlayer(),
				player.getTabListDisplayName(),
				true,
				0,
				(RemoteChatSession.Data) null
		));
		player.connection.send(packet);
	}

	private static void syncLittleDictatorDefenseOverlay(ServerPlayer player, boolean enabled, boolean force) {
		if (player == null || player.connection == null) {
			return;
		}
		UUID playerId = player.getUUID();
		if (!enabled) {
			if (force || LITTLE_DICTATOR_PING_OVERLAY_ACTIVE.remove(playerId)) {
				player.connection.send(new ClientboundSetTitlesAnimationPacket(0, 0, 10));
				player.connection.send(new ClientboundSetTitleTextPacket(Component.empty()));
			}
			return;
		}
		if (!force && LITTLE_DICTATOR_PING_OVERLAY_ACTIVE.contains(playerId)) {
			return;
		}
		player.connection.send(new ClientboundSetTitlesAnimationPacket(0, 12, 0));
		player.connection.send(new ClientboundSetTitleTextPacket(buildLittleDictatorDefenseTitle(player)));
		LITTLE_DICTATOR_PING_OVERLAY_ACTIVE.add(playerId);
	}

	private static Component buildLittleDictatorDefenseTitle(ServerPlayer player) {
		long gameTime = player == null || player.level() == null ? 0L : player.level().getGameTime();
		int frameIndex = (int) ((gameTime / LITTLE_DICTATOR_DEFENSE_OVERLAY_FRAME_TICKS) % LITTLE_DICTATOR_DEFENSE_GLYPH_FRAMES.length);
		if (PolymerResourcePackUtils.hasMainPack(player)) {
			Component glyph = Component.literal(LITTLE_DICTATOR_DEFENSE_GLYPH_FRAMES[frameIndex])
					.withStyle(style -> style
							.withColor(LITTLE_DICTATOR_DEFENSE_TITLE_COLOR)
							.withItalic(false)
							.withFont(LITTLE_DICTATOR_DEFENSE_FONT)
							.withShadowColor(0x00000000));
			return glyph;
		}
		return Component.empty();
	}

	private static void playLittleDictatorDefenseActivationSound(ServerPlayer player, Vec3 origin) {
		if (player == null || player.connection == null || origin == null) {
			return;
		}
		Holder<SoundEvent> sound = PolymerResourcePackUtils.hasMainPack(player)
				? LITTLE_DICTATOR_DEFENSE_SOUND
				: LITTLE_DICTATOR_DEFENSE_FALLBACK_SOUND;
		player.connection.send(new ClientboundSoundPacket(
				sound,
				SoundSource.PLAYERS,
				origin.x,
				origin.y,
				origin.z,
				LITTLE_DICTATOR_DEFENSE_SOUND_VOLUME,
				LITTLE_DICTATOR_DEFENSE_SOUND_PITCH,
				player.level().getGameTime() ^ player.getUUID().getLeastSignificantBits()
		));
	}

	private static void spawnLittleDictatorDefenseWaveParticles(ServerLevel level, Vec3 origin, double radius) {
		if (level == null || origin == null || radius <= 0.0D) {
			return;
		}

		DustParticleOptions primary = new DustParticleOptions(LITTLE_DICTATOR_DEFENSE_WAVE_PRIMARY_COLOR, 0.92F);
		DustParticleOptions secondary = new DustParticleOptions(LITTLE_DICTATOR_DEFENSE_WAVE_SECONDARY_COLOR, 0.68F);
		int points = Math.max(18, (int) Math.round(radius * 5.0D));
		double[] verticalOffsets = { -1.0D, -0.45D, 0.15D, 0.75D };

		for (double verticalOffset : verticalOffsets) {
			double ringRadius = Math.max(0.35D, radius * (1.0D - Math.abs(verticalOffset) * 0.2D));
			for (int index = 0; index < points; index++) {
				double angle = (Math.PI * 2.0D * index) / points;
				double x = origin.x + Math.cos(angle) * ringRadius;
				double y = origin.y + verticalOffset;
				double z = origin.z + Math.sin(angle) * ringRadius;
				DustParticleOptions particle = (index & 1) == 0 ? primary : secondary;
				level.sendParticles(particle, x, y, z, 1, 0.01D, 0.01D, 0.01D, 0.0D);
			}
		}
	}

	private static boolean hasMilkAbsoluteHeartToSpend(ServerPlayer player) {
		if (player == null) {
			return false;
		}
		return player.getMaxHealth() > 2.0F + 1.0E-3F;
	}

	public static boolean handleMilkAbsoluteAttack(ServerLevel level, LivingEntity victim, DamageSource damageSource, float damage) {
		if (level == null
				|| victim == null
				|| damageSource == null
				|| damage <= 0.0F
				|| !damageSource.is(DamageTypes.PLAYER_ATTACK)) {
			return false;
		}
		if (!(damageSource.getEntity() instanceof ServerPlayer attacker)
				|| damageSource.getDirectEntity() != attacker
				|| attacker == victim
				|| !MILK_ABSOLUTE_ATTACK_READY.contains(attacker.getUUID())
				|| !canUseMilkAbsoluteAttack(attacker)) {
			return false;
		}

		MILK_ABSOLUTE_ATTACK_READY.remove(attacker.getUUID());
		syncMilkAbsoluteAttackHud(attacker, false, true);
		applyMilkAbsoluteHeartCost(level, attacker);
		forceMilkAbsoluteKill(level, attacker, victim);
		return true;
	}

	private static boolean canUseMilkAbsoluteAttack(ServerPlayer player) {
		if (player == null || !player.isAlive() || player.isSpectator()) {
			return false;
		}
		Optional<PlayerRaceConfig> raceOptional = getRace(player);
		if (raceOptional.isEmpty()) {
			return false;
		}
		PlayerRaceConfig race = raceOptional.get();
		return MILK_OLIGARCH_RACE_ID.equals(sanitizePath(race.id))
				&& race.attack != null
				&& race.attack.enabled
				&& hasUnlockedAbility(player, race, RaceAbilitySlot.ATTACK);
	}

	private static int useMilkOligarchDefense(ServerPlayer player, PlayerRaceConfig race, RaceAbilityConfig ability) {
		if (player == null || ability == null || player.isSpectator() || !player.isAlive()) {
			return 0;
		}
		if (!(player.level() instanceof ServerLevel level)) {
			return 0;
		}
		long remainingCooldownTicks = getRemainingOnlineCooldownTicks(MILK_DEFENSE_COOLDOWNS, player.getUUID());
		if (displayRemainingCooldown(player, remainingCooldownTicks)) {
			return 0;
		}

		long durationTicks = Math.max(1L, asTicks(positiveOrDefault(ability.durationSeconds, MILK_DEFENSE_DEFAULT_DURATION_SECONDS)));
		long cooldownTicks = Math.max(1L, asTicks(positiveOrDefault(ability.cooldownSeconds, MILK_DEFENSE_DEFAULT_COOLDOWN_SECONDS)));
		double teleportDistance = positiveOrDefault(ability.milkDefenseTeleportDistanceBlocks, MILK_DEFENSE_DEFAULT_TELEPORT_DISTANCE_BLOCKS);
		MILK_DEFENSE_SESSIONS.put(
				player.getUUID(),
				new MilkDefenseSession(level.dimension(), level.getGameTime() + durationTicks, teleportDistance)
		);
		startOnlineCooldown(MILK_DEFENSE_COOLDOWNS, player.getUUID(), cooldownTicks);
		spawnMilkDefenseActivationParticles(level, player);
		level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.BREEZE_LAND, SoundSource.PLAYERS, 0.85F, 1.02F);
		Lg2.LOGGER.info(
				"Player {} activated milk oligarch defense '{}' from race '{}'",
				player.getGameProfile().name(),
				ability.abilityId,
				race.id
		);
		return 1;
	}

	private static void spawnMilkDefenseActivationParticles(ServerLevel level, ServerPlayer player) {
		if (level == null || player == null) {
			return;
		}

		Vec3 forward = new Vec3(player.getLookAngle().x, 0.0D, player.getLookAngle().z);
		if (forward.lengthSqr() <= 1.0E-6D) {
			forward = Vec3.directionFromRotation(0.0F, player.getYRot());
			forward = new Vec3(forward.x, 0.0D, forward.z);
		}
		if (forward.lengthSqr() <= 1.0E-6D) {
			forward = new Vec3(0.0D, 0.0D, 1.0D);
		}
		forward = forward.normalize();
		Vec3 right = new Vec3(-forward.z, 0.0D, forward.x);
		Vec3 base = player.position().add(0.0D, 0.08D, 0.0D);

		DustParticleOptions ivory = new DustParticleOptions(MILK_DEFENSE_ACTIVATION_IVORY_COLOR, 0.74F);
		DustParticleOptions blue = new DustParticleOptions(MILK_DEFENSE_ACTIVATION_BLUE_COLOR, 0.55F);

		for (int i = 0; i < 14; i++) {
			double t = (Math.PI * 2.0D * i) / 14.0D;
			Vec3 offset = right.scale(Math.cos(t) * 0.52D).add(forward.scale(Math.sin(t) * 0.30D));
			Vec3 pos = base.add(offset).add(0.0D, Math.sin(t * 2.0D) * 0.025D, 0.0D);
			level.sendParticles(i % 4 == 0 ? blue : ivory, pos.x, pos.y, pos.z, 1, 0.006D, 0.008D, 0.006D, 0.0D);
		}

		Vec3 chest = player.position().add(0.0D, Math.max(0.72D, player.getBbHeight() * 0.58D), 0.0D);
		for (int sideIndex = -1; sideIndex <= 1; sideIndex += 2) {
			for (int i = 0; i < 5; i++) {
				double progress = i / 4.0D;
				Vec3 pos = chest
						.add(right.scale(sideIndex * (0.16D + progress * 0.18D)))
						.subtract(forward.scale(0.08D + progress * 0.42D))
						.add(0.0D, progress * 0.18D, 0.0D);
				level.sendParticles(progress > 0.55D ? blue : ivory, pos.x, pos.y, pos.z, 1, 0.004D, 0.008D, 0.004D, 0.0D);
			}
		}

		Vec3 rear = player.position().subtract(forward.scale(0.28D)).add(0.0D, 0.18D, 0.0D);
		level.sendParticles(ParticleTypes.POOF, player.getX(), player.getY() + 0.42D, player.getZ(), 3, 0.12D, 0.12D, 0.12D, 0.015D);
		level.sendParticles(ParticleTypes.CLOUD, rear.x, rear.y, rear.z, 0, -forward.x * 0.025D, 0.006D, -forward.z * 0.025D, 1.0D);
	}

	public static void handleMilkDefenseDodge(ServerLevel level, LivingEntity victim, DamageSource damageSource, float damage, boolean applied) {
		if (!applied || level == null || victim == null || damageSource == null || damage <= 0.0F || !(victim instanceof ServerPlayer player)) {
			return;
		}
		MilkDefenseSession session = MILK_DEFENSE_SESSIONS.get(player.getUUID());
		if (session == null) {
			return;
		}
		if (!session.dimension().equals(level.dimension()) || level.getGameTime() >= session.endTick() || !canUseMilkDefense(player)) {
			MILK_DEFENSE_SESSIONS.remove(player.getUUID());
			return;
		}
		if (!isMilkDefenseMeleeAttack(damageSource) || !(damageSource.getEntity() instanceof LivingEntity attacker)) {
			return;
		}
		if (attacker == player || attacker.level() != level || !attacker.isAlive()) {
			return;
		}

		Vec3 teleportPos = findMilkDefenseDodgePosition(level, player, attacker, session.teleportDistanceBlocks());
		if (teleportPos == null) {
			return;
		}

		lookAndTeleportMilkDefensePlayer(level, player, attacker, teleportPos);
		level.playSound(
				null,
				teleportPos.x,
				teleportPos.y,
				teleportPos.z,
				SoundEvents.ENDERMAN_TELEPORT,
				SoundSource.PLAYERS,
				1.0F,
				1.0F
		);
	}

	private static boolean canUseMilkDefense(ServerPlayer player) {
		if (player == null || !player.isAlive() || player.isSpectator()) {
			return false;
		}
		Optional<PlayerRaceConfig> raceOptional = getRace(player);
		if (raceOptional.isEmpty()) {
			return false;
		}
		PlayerRaceConfig race = raceOptional.get();
		return MILK_OLIGARCH_RACE_ID.equals(sanitizePath(race.id))
				&& race.defense != null
				&& race.defense.enabled
				&& hasUnlockedAbility(player, race, RaceAbilitySlot.DEFENSE);
	}

	private static boolean isMilkDefenseMeleeAttack(DamageSource damageSource) {
		if (damageSource == null || damageSource.getEntity() == null || damageSource.getDirectEntity() != damageSource.getEntity()) {
			return false;
		}
		return damageSource.is(DamageTypes.PLAYER_ATTACK)
				|| damageSource.is(DamageTypes.MOB_ATTACK);
	}

	private static Vec3 findMilkDefenseDodgePosition(ServerLevel level, ServerPlayer player, LivingEntity attacker, double distance) {
		if (level == null || player == null || attacker == null) {
			return null;
		}
		Vec3 attackerForward = attacker.getLookAngle();
		Vec3 horizontalForward = new Vec3(attackerForward.x, 0.0D, attackerForward.z);
		if (horizontalForward.lengthSqr() <= 1.0E-6D) {
			horizontalForward = Vec3.directionFromRotation(0.0F, attacker.getYRot());
		}
		if (horizontalForward.lengthSqr() <= 1.0E-6D) {
			horizontalForward = new Vec3(attacker.getX() - player.getX(), 0.0D, attacker.getZ() - player.getZ());
		}
		if (horizontalForward.lengthSqr() <= 1.0E-6D) {
			horizontalForward = new Vec3(1.0D, 0.0D, 0.0D);
		}
		horizontalForward = horizontalForward.normalize();

		double safeDistance = Math.max(0.25D, distance);
		Vec3 desired = attacker.position().subtract(horizontalForward.scale(safeDistance));
		Vec3 resolved = resolveMilkDefenseDodgeCandidate(level, player, attacker, desired);
		if (resolved != null) {
			return resolved;
		}

		for (int ring = 1; ring <= MILK_DEFENSE_POSITION_SEARCH_RINGS; ring++) {
			double radius = ring * MILK_DEFENSE_POSITION_SEARCH_STEP_BLOCKS;
			for (int step = 0; step < MILK_DEFENSE_POSITION_SEARCH_DIRECTIONS; step++) {
				double angle = (Math.PI * 2.0D * step) / MILK_DEFENSE_POSITION_SEARCH_DIRECTIONS;
				Vec3 candidate = desired.add(Math.cos(angle) * radius, 0.0D, Math.sin(angle) * radius);
				resolved = resolveMilkDefenseDodgeCandidate(level, player, attacker, candidate);
				if (resolved != null) {
					return resolved;
				}
			}
		}
		return null;
	}

	private static Vec3 resolveMilkDefenseDodgeCandidate(ServerLevel level, ServerPlayer player, LivingEntity attacker, Vec3 candidate) {
		if (candidate == null) {
			return null;
		}
		int baseY = (int) Math.floor(candidate.y);
		int[] yOffsets = {0, 1, -1, 2, -2};
		for (int yOffset : yOffsets) {
			double y = baseY + yOffset;
			Vec3 resolved = new Vec3(candidate.x, y, candidate.z);
			if (canMilkDefenseStandAt(level, player, resolved) && hasMilkDefenseLineOfSight(level, player, attacker, resolved)) {
				return resolved;
			}
		}
		return null;
	}

	private static boolean canMilkDefenseStandAt(ServerLevel level, ServerPlayer player, Vec3 pos) {
		if (level == null || player == null || pos == null) {
			return false;
		}
		EntityDimensions dimensions = player.getDimensions(Pose.STANDING);
		AABB box = dimensions.makeBoundingBox(pos.x, pos.y, pos.z).inflate(-1.0E-5D);
		if (!level.noCollision(player, box)) {
			return false;
		}
		BlockPos belowPos = BlockPos.containing(pos.x, pos.y - 0.05D, pos.z);
		BlockState belowState = level.getBlockState(belowPos);
		return !belowState.getCollisionShape(level, belowPos, CollisionContext.of(player)).isEmpty();
	}

	private static boolean hasMilkDefenseLineOfSight(ServerLevel level, ServerPlayer player, LivingEntity attacker, Vec3 pos) {
		if (level == null || player == null || attacker == null || pos == null) {
			return false;
		}
		Vec3 start = pos.add(0.0D, Math.max(0.4D, player.getBbHeight() * 0.85D), 0.0D);
		Vec3 end = attacker.getEyePosition();
		BlockHitResult hit = level.clip(new ClipContext(start, end, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, player));
		return hit.getType() == HitResult.Type.MISS;
	}

	private static void lookAndTeleportMilkDefensePlayer(ServerLevel level, ServerPlayer player, LivingEntity attacker, Vec3 teleportPos) {
		Vec3 lookDirection = attacker.getEyePosition().subtract(teleportPos.add(0.0D, Math.max(0.4D, player.getBbHeight() * 0.85D), 0.0D));
		if (lookDirection.lengthSqr() <= 1.0E-6D) {
			lookDirection = new Vec3(attacker.getX() - teleportPos.x, 0.0D, attacker.getZ() - teleportPos.z);
		}
		if (lookDirection.lengthSqr() <= 1.0E-6D) {
			lookDirection = Vec3.directionFromRotation(0.0F, player.getYRot());
		}
		float yaw = yawFromDirection(lookDirection);
		float pitch = pitchFromDirection(lookDirection);
		player.connection.teleport(teleportPos.x, teleportPos.y, teleportPos.z, yaw, pitch);
		player.setYRot(yaw);
		player.setXRot(pitch);
		player.connection.send(new ClientboundPlayerRotationPacket(yaw, false, pitch, false));
	}

	private static int useMilkOligarchUnique(ServerPlayer player, PlayerRaceConfig race, RaceAbilityConfig ability) {
		if (player == null || ability == null || player.isSpectator() || !player.isAlive()) {
			return 0;
		}
		if (!(player.level() instanceof ServerLevel level)) {
			return 0;
		}
		if (MILK_MOUSE_SESSIONS.containsKey(player.getUUID())) {
			player.displayClientMessage(
					Component.literal("Мистер Мыша уже активен.")
							.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
					true
			);
			return 0;
		}
		if (displayGenericAbilityCooldown(player, RaceAbilitySlot.UNIQUE_ABILITY)) {
			return 0;
		}

		int count = getMilkMouseSilverfishCount(ability);
		long durationTicks = Math.max(1L, asTicks(positiveOrDefault(ability.durationSeconds, MILK_MOUSE_DEFAULT_DURATION_SECONDS)));
		List<Silverfish> silverfish = spawnMilkMouseSilverfish(level, player, count);
		if (silverfish.isEmpty()) {
			return 0;
		}

		Silverfish controlled = silverfish.get(level.random.nextInt(silverfish.size()));
		prepareMilkMouseControlledSilverfish(controlled);
		List<UUID> silverfishIds = silverfish.stream().map(Entity::getUUID).toList();
		for (Silverfish fish : silverfish) {
			MILK_MOUSE_SILVERFISH_OWNER_BY_ENTITY.put(fish.getUUID(), player.getUUID());
			spawnMilkMousePoof(level, fish.position(), 8);
		}
		level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.SILVERFISH_STEP, SoundSource.PLAYERS, 0.85F, 0.96F);
		scheduleMilkMouseStepSounds(level, player.position());

		MilkMouseSession previous = MILK_MOUSE_SESSIONS.put(
				player.getUUID(),
				new MilkMouseSession(
						level.dimension(),
						level.getGameTime() + durationTicks,
						controlled.getUUID(),
						silverfishIds,
						player.isInvisible(),
						player.isNoGravity(),
						player.noPhysics,
						controlled.position(),
						player.getYRot(),
						player.getXRot()
				)
		);
		if (previous != null) {
			cleanupMilkMouseSession(level.getServer(), player.getUUID(), previous, true, true);
		}

		hideMilkMousePlayerFromOthers(player);
		activateMilkMousePlayerView(player, controlled);
		startGenericAbilityCooldownSeconds(player, RaceAbilitySlot.UNIQUE_ABILITY, positiveOrDefault(ability.cooldownSeconds, MILK_MOUSE_DEFAULT_COOLDOWN_SECONDS));
		Lg2.LOGGER.info(
				"Player {} activated milk oligarch unique '{}' from race '{}'",
				player.getGameProfile().name(),
				ability.abilityId,
				race.id
		);
		return 1;
	}

	private static int useMilkOligarchShnyaga(ServerPlayer player, PlayerRaceConfig race, RaceAbilityConfig ability) {
		if (player == null || ability == null || player.isSpectator() || !player.isAlive()) {
			return 0;
		}

		List<ServerPlayer> candidates = collectMilkPocketInviteCandidates(player);
		if (candidates.isEmpty()) {
			player.displayClientMessage(
					Component.literal("Некого приглашать.")
							.withStyle(style -> style.withColor(ChatFormatting.RED).withItalic(false)),
					true
			);
			return 0;
		}

		openMilkPocketInviteMenu(player, candidates, 0, ability);
		return 1;
	}

	private static List<ServerPlayer> collectMilkPocketInviteCandidates(ServerPlayer owner) {
		if (owner == null || owner.level().getServer() == null) {
			return List.of();
		}

		List<ServerPlayer> candidates = new ArrayList<>();
		for (ServerPlayer player : owner.level().getServer().getPlayerList().getPlayers()) {
			if (player == null || player == owner || !player.isAlive() || player.isSpectator()) {
				continue;
			}
			if (ServerMilkPocketDimensionSystem.hasPocketAccess(player)) {
				continue;
			}
			candidates.add(player);
		}
		return candidates;
	}

	private static void openMilkPocketInviteMenu(ServerPlayer owner, List<ServerPlayer> candidates, int selectedIndex, RaceAbilityConfig ability) {
		if (owner == null) {
			return;
		}
		int normalizedIndex = candidates == null || candidates.isEmpty() ? 0 : Math.floorMod(selectedIndex, candidates.size());
		ServerPlayer selectedPlayer = candidates == null || candidates.isEmpty() ? null : candidates.get(normalizedIndex);
		owner.openMenu(new SimpleMenuProvider(
				(syncId, inventory, menuPlayer) -> new MilkPocketInviteMenu(syncId, inventory, owner, ability, normalizedIndex),
				buildMilkPocketInviteMenuTitle(owner, selectedPlayer)
		));
	}

	private static List<Silverfish> spawnMilkMouseSilverfish(ServerLevel level, ServerPlayer player, int count) {
		List<Silverfish> spawned = new ArrayList<>();
		if (level == null || player == null || count <= 0) {
			return spawned;
		}

		RandomSource random = player.getRandom();
		AABB box = player.getBoundingBox();
		double widthX = Math.max(0.05D, box.getXsize());
		double widthZ = Math.max(0.05D, box.getZsize());
		double height = Math.max(0.05D, box.getYsize());
		for (int i = 0; i < count; i++) {
			Silverfish fish = EntityType.SILVERFISH.create(level, EntitySpawnReason.TRIGGERED);
			if (fish == null) {
				continue;
			}
			double x = box.minX + random.nextDouble() * widthX;
			double y = box.minY + random.nextDouble() * height;
			double z = box.minZ + random.nextDouble() * widthZ;
			fish.setPos(x, y, z);
			fish.setYRot(random.nextFloat() * 360.0F);
			fish.setYHeadRot(fish.getYRot());
			fish.setYBodyRot(fish.getYRot());
			fish.addTag(MILK_MOUSE_SILVERFISH_TAG);
			fish.setInvulnerable(false);
			fish.setCanPickUpLoot(false);
			if (fish.getAttribute(Attributes.MAX_HEALTH) != null) {
				fish.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1.0D);
			}
			fish.setHealth(1.0F);
			fish.setTarget(null);
			((MobXpRewardAccessor) fish).lg2$setXpReward(0);
			level.addFreshEntity(fish);
			spawned.add(fish);
		}
		return spawned;
	}

	private static void activateMilkMousePlayerView(ServerPlayer player, Silverfish controlled) {
		if (player == null || controlled == null || player.connection == null) {
			return;
		}
		prepareMilkMouseControlledSilverfish(controlled);
		player.setInvisible(true);
		player.setNoGravity(true);
		player.noPhysics = true;
		player.setCamera(controlled);
		player.connection.send(new ClientboundSetCameraPacket(controlled));
		player.setDeltaMovement(Vec3.ZERO);
	}

	private static void hideMilkMousePlayerFromOthers(ServerPlayer player) {
		if (player == null || !(player.level() instanceof ServerLevel level)) {
			return;
		}
		ClientboundRemoveEntitiesPacket removeEntityPacket = new ClientboundRemoveEntitiesPacket(player.getId());
		ClientboundTrackedWaypointPacket removeWaypointPacket = ClientboundTrackedWaypointPacket.removeWaypoint(player.getUUID());
		for (ServerPlayer viewer : level.players()) {
			if (viewer == null || viewer == player || viewer.connection == null) {
				continue;
			}
			viewer.connection.send(removeEntityPacket);
			viewer.connection.send(removeWaypointPacket);
		}
	}

	private static void prepareMilkMouseControlledSilverfish(Silverfish controlled) {
		if (controlled == null) {
			return;
		}
		controlled.setNoAi(false);
		controlled.setInvulnerable(false);
		if (controlled.getAttribute(Attributes.MAX_HEALTH) != null) {
			controlled.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1.0D);
		}
		if (controlled.getHealth() > 1.0F) {
			controlled.setHealth(1.0F);
		}
		controlled.setTarget(null);
		controlled.setAggressive(false);
		controlled.setCanPickUpLoot(false);
		((MobXpRewardAccessor) controlled).lg2$setXpReward(0);
	}

	private static void tickMilkOligarchUnique(MinecraftServer server) {
		if (server == null) {
			return;
		}
		tickMilkMouseStepSounds(server);
		if (MILK_MOUSE_SESSIONS.isEmpty()) {
			return;
		}

		Iterator<Map.Entry<UUID, MilkMouseSession>> iterator = MILK_MOUSE_SESSIONS.entrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, MilkMouseSession> entry = iterator.next();
			UUID playerId = entry.getKey();
			MilkMouseSession session = entry.getValue();
			ServerPlayer player = server.getPlayerList().getPlayer(playerId);
			ServerLevel level = session == null ? null : server.getLevel(session.dimension);
			if (session == null || player == null || level == null || !player.level().dimension().equals(session.dimension) || !canUseMilkMouse(player)) {
				cleanupMilkMouseSession(server, playerId, session, player != null, true);
				iterator.remove();
				continue;
			}

			Entity controlledEntity = level.getEntity(session.controlledSilverfishId);
			if (!(controlledEntity instanceof Silverfish controlled) || !controlled.isAlive()) {
				cleanupMilkMouseSession(server, playerId, session, true, true);
				iterator.remove();
				continue;
			}

			session.lastPosition = controlled.position();
			if (level.getGameTime() >= session.endTick) {
				cleanupMilkMouseSession(server, playerId, session, true, true);
				iterator.remove();
				continue;
			}

			tickMilkMouseControlledSilverfish(level, player, controlled, session);
			tickMilkMouseDecoys(level, session, playerId);
		}
	}

	private static void tickMilkMouseControlledSilverfish(ServerLevel level, ServerPlayer player, Silverfish controlled, MilkMouseSession session) {
		if (level == null || player == null || controlled == null || session == null || !controlled.isAlive()) {
			return;
		}
		prepareMilkMouseControlledSilverfish(controlled);

		if (controlled.onGround()) {
			controlled.resetFallDistance();
		}
		controlled.setSprinting(false);

		player.setInvisible(true);
		player.setNoGravity(true);
		player.noPhysics = true;
		if (player.getCamera() != controlled) {
			player.setCamera(controlled);
			player.connection.send(new ClientboundSetCameraPacket(controlled));
		}
		player.teleportTo(controlled.getX(), controlled.getY(), controlled.getZ());
		player.setDeltaMovement(Vec3.ZERO);
	}

	private static void tickMilkMouseDecoys(ServerLevel level, MilkMouseSession session, UUID ownerId) {
		if (level == null || session == null) {
			return;
		}
		Iterator<UUID> iterator = session.silverfishIds.iterator();
		while (iterator.hasNext()) {
			UUID fishId = iterator.next();
			Entity entity = level.getEntity(fishId);
			if (!(entity instanceof Silverfish fish) || !fish.isAlive()) {
				MILK_MOUSE_SILVERFISH_OWNER_BY_ENTITY.remove(fishId);
				iterator.remove();
				continue;
			}
			((MobXpRewardAccessor) fish).lg2$setXpReward(0);
			fish.setTarget(null);
			ServerPlayer nearestPlayer = findNearestMilkMouseFleePlayer(level, fish, ownerId);
			if (nearestPlayer == null) {
				continue;
			}
			long nowTick = level.getGameTime();
			PathNavigation navigation = fish.getNavigation();
			if (navigation == null || (!navigation.isDone() && (nowTick + fish.getId()) % MILK_MOUSE_FLEE_NAV_INTERVAL_TICKS != 0L)) {
				continue;
			}
			Vec3 destination = DefaultRandomPos.getPosAway(fish, (int) Math.ceil(MILK_MOUSE_FLEE_RADIUS_BLOCKS), 4, nearestPlayer.position());
			if (destination != null && destination.distanceToSqr(nearestPlayer.position()) > fish.distanceToSqr(nearestPlayer)) {
				navigation.moveTo(destination.x, destination.y, destination.z, MILK_MOUSE_FLEE_SPEED);
			}
		}
	}

	private static ServerPlayer findNearestMilkMouseFleePlayer(ServerLevel level, Silverfish fish, UUID ownerId) {
		if (level == null || fish == null) {
			return null;
		}
		AABB area = fish.getBoundingBox().inflate(MILK_MOUSE_FLEE_RADIUS_BLOCKS);
		ServerPlayer nearest = null;
		double bestDistance = Double.MAX_VALUE;
		for (ServerPlayer player : level.getEntitiesOfClass(ServerPlayer.class, area, candidate ->
				candidate.isAlive()
						&& !candidate.isSpectator()
						&& (ownerId == null || !ownerId.equals(candidate.getUUID()))
						&& !MILK_MOUSE_SESSIONS.containsKey(candidate.getUUID()))) {
			double distance = player.distanceToSqr(fish);
			if (distance < bestDistance) {
				bestDistance = distance;
				nearest = player;
			}
		}
		return nearest;
	}

	private static void scheduleMilkMouseStepSounds(ServerLevel level, Vec3 origin) {
		if (level == null || origin == null) {
			return;
		}
		long startTick = level.getGameTime();
		for (int i = 0; i < 6; i++) {
			float pitch = 0.9F + level.random.nextFloat() * 0.18F;
			MILK_MOUSE_STEP_SOUNDS.add(new MilkMouseStepSound(level.dimension(), origin, startTick + i, 0.62F, pitch));
		}
	}

	private static void tickMilkMouseStepSounds(MinecraftServer server) {
		if (server == null || MILK_MOUSE_STEP_SOUNDS.isEmpty()) {
			return;
		}

		Iterator<MilkMouseStepSound> iterator = MILK_MOUSE_STEP_SOUNDS.iterator();
		while (iterator.hasNext()) {
			MilkMouseStepSound sound = iterator.next();
			ServerLevel level = server.getLevel(sound.dimension());
			if (level == null) {
				iterator.remove();
				continue;
			}
			if (level.getGameTime() < sound.playTick()) {
				continue;
			}
			Vec3 position = sound.position();
			level.playSound(null, position.x, position.y, position.z, SoundEvents.SILVERFISH_STEP, SoundSource.PLAYERS, sound.volume(), sound.pitch());
			iterator.remove();
		}
	}

	private static void cleanupAllMilkMouseSessions(MinecraftServer server, boolean restorePlayers) {
		if (server == null || MILK_MOUSE_SESSIONS.isEmpty()) {
			return;
		}
		for (Map.Entry<UUID, MilkMouseSession> entry : new ArrayList<>(MILK_MOUSE_SESSIONS.entrySet())) {
			cleanupMilkMouseSession(server, entry.getKey(), entry.getValue(), restorePlayers, false);
		}
	}

	private static void cleanupMilkMouseSession(MinecraftServer server, UUID playerId, MilkMouseSession session, boolean restorePlayer, boolean emitParticles) {
		if (server == null || playerId == null || session == null) {
			return;
		}

		ServerLevel level = server.getLevel(session.dimension);
		Vec3 returnPosition = getMilkMouseReturnPosition(level, session);
		if (level != null) {
			for (UUID fishId : new ArrayList<>(session.silverfishIds)) {
				Entity entity = level.getEntity(fishId);
				if (entity != null) {
					if (emitParticles) {
						spawnMilkMousePoof(level, entity.position(), 2);
					}
					entity.discard();
				}
				MILK_MOUSE_SILVERFISH_OWNER_BY_ENTITY.remove(fishId);
			}
		} else {
			for (UUID fishId : session.silverfishIds) {
				MILK_MOUSE_SILVERFISH_OWNER_BY_ENTITY.remove(fishId);
			}
		}

		if (!restorePlayer) {
			return;
		}
		ServerPlayer player = server.getPlayerList().getPlayer(playerId);
		if (player == null) {
			return;
		}
		player.setCamera(player);
		if (player.connection != null) {
			player.connection.send(new ClientboundSetCameraPacket(player));
		}
		player.setInvisible(session.originalInvisible);
		player.setNoGravity(session.originalNoGravity);
		player.noPhysics = session.originalNoPhysics;
		if (returnPosition != null && player.level() instanceof ServerLevel playerLevel && playerLevel.dimension().equals(session.dimension)) {
			player.connection.teleport(returnPosition.x, returnPosition.y, returnPosition.z, player.getYRot(), player.getXRot());
		}
		player.setDeltaMovement(Vec3.ZERO);
	}

	private static Vec3 getMilkMouseReturnPosition(ServerLevel level, MilkMouseSession session) {
		if (session == null) {
			return Vec3.ZERO;
		}
		if (level != null) {
			Entity controlled = level.getEntity(session.controlledSilverfishId);
			if (controlled != null) {
				return controlled.position();
			}
		}
		return session.lastPosition == null ? Vec3.ZERO : session.lastPosition;
	}

	private static boolean canUseMilkMouse(ServerPlayer player) {
		if (player == null || !player.isAlive() || player.isSpectator()) {
			return false;
		}
		Optional<PlayerRaceConfig> raceOptional = getRace(player);
		if (raceOptional.isEmpty()) {
			return false;
		}
		PlayerRaceConfig race = raceOptional.get();
		return MILK_OLIGARCH_RACE_ID.equals(sanitizePath(race.id))
				&& race.uniqueAbility != null
				&& race.uniqueAbility.enabled
				&& hasUnlockedAbility(player, race, RaceAbilitySlot.UNIQUE_ABILITY);
	}

	private static int getMilkMouseSilverfishCount(RaceAbilityConfig ability) {
		if (ability == null || ability.milkMouseSilverfishCount <= 0) {
			return MILK_MOUSE_DEFAULT_SILVERFISH_COUNT;
		}
		return Math.max(1, ability.milkMouseSilverfishCount);
	}

	private static void spawnMilkMousePoof(ServerLevel level, Vec3 position, int count) {
		if (level == null || position == null || count <= 0) {
			return;
		}
		level.sendParticles(ParticleTypes.POOF, position.x, position.y + 0.18D, position.z, count, 0.25D, 0.18D, 0.25D, 0.035D);
		level.sendParticles(ParticleTypes.SMOKE, position.x, position.y + 0.18D, position.z, Math.max(1, count / 3), 0.2D, 0.14D, 0.2D, 0.02D);
	}

	public static boolean isMilkMouseSilverfish(Entity entity) {
		return entity != null && entity.getTags().contains(MILK_MOUSE_SILVERFISH_TAG);
	}

	public static boolean isMilkMouseActive(ServerPlayer player) {
		return player != null && MILK_MOUSE_SESSIONS.containsKey(player.getUUID());
	}

	public static boolean shouldSuppressMilkMouseWaypoint(ServerPlayer receiver, ClientboundTrackedWaypointPacket packet) {
		if (receiver == null || packet == null || packet.waypoint() == null || receiver.level().getServer() == null) {
			return false;
		}
		UUID waypointPlayerId = packet.waypoint().id().left().orElse(null);
		if (waypointPlayerId == null || waypointPlayerId.equals(receiver.getUUID())) {
			return false;
		}
		ServerPlayer waypointPlayer = receiver.level().getServer().getPlayerList().getPlayer(waypointPlayerId);
		return isMilkMouseActive(waypointPlayer);
	}

	public static boolean shouldCancelMilkMouseCombatDamage(LivingEntity victim, DamageSource damageSource) {
		if (victim instanceof ServerPlayer player && MILK_MOUSE_SESSIONS.containsKey(player.getUUID())) {
			return true;
		}
		if (damageSource == null) {
			return false;
		}
		return isMilkMouseSilverfish(damageSource.getEntity()) || isMilkMouseSilverfish(damageSource.getDirectEntity());
	}

	private static void forceMilkAbsoluteKill(ServerLevel level, ServerPlayer attacker, LivingEntity victim) {
		if (level == null || attacker == null || victim == null || victim == attacker || !victim.isAlive()) {
			return;
		}
		DamageSource source = milkAbsoluteAttackDamageSource(level, attacker);
		victim.setLastHurtByPlayer(attacker, 100);
		victim.setLastHurtByMob(attacker);
		attacker.setLastHurtMob(victim);
		victim.invulnerableTime = 0;
		victim.setHealth(0.0F);
		victim.die(source);
	}

	private static DamageSource milkAbsoluteAttackDamageSource(ServerLevel level, ServerPlayer attacker) {
		return new DamageSource(
				level.registryAccess().lookupOrThrow(Registries.DAMAGE_TYPE).getOrThrow(DamageTypes.PLAYER_ATTACK),
				attacker,
				attacker
		);
	}

	private static void applyMilkAbsoluteHeartCost(ServerLevel level, ServerPlayer player) {
		if (level == null || player == null) {
			return;
		}
		AttributeInstance maxHealth = player.getAttribute(Attributes.MAX_HEALTH);
		if (maxHealth != null) {
			double currentBase = maxHealth.getBaseValue();
			double nextBase = Math.max(MILK_ABSOLUTE_ATTACK_MIN_MAX_HEALTH_POINTS, currentBase - MILK_ABSOLUTE_ATTACK_HEALTH_COST_POINTS);
			if (Double.compare(nextBase, currentBase) != 0) {
				maxHealth.setBaseValue(nextBase);
				if (player.getHealth() > nextBase) {
					player.setHealth((float) nextBase);
				}
			}
		}
		level.playSound(
				null,
				player.getX(),
				player.getY(),
				player.getZ(),
				SoundEvents.RESPAWN_ANCHOR_DEPLETE,
				SoundSource.PLAYERS,
				1.0F,
				0.9F
		);
		startMilkLostHeartAnimation(level, player);
		spawnMilkLostHeartDropParticles(level, player);
	}

	private static void startMilkLostHeartAnimation(ServerLevel level, ServerPlayer player) {
		if (level == null || player == null || player.connection == null) {
			return;
		}

		MILK_ABSOLUTE_LOST_HEART_ANIMATIONS.put(
				player.getUUID(),
				new MilkLostHeartAnimationSession(level.getGameTime(), 0)
		);
		MILK_ABSOLUTE_ATTACK_HUD_VISIBLE.remove(player.getUUID());
		player.connection.send(new ClientboundSetTitlesAnimationPacket(0, 0, 0));
		player.connection.send(new ClientboundSetTitleTextPacket(Component.empty()));
		player.connection.send(new ClientboundSetSubtitleTextPacket(Component.empty()));
		sendMilkLostHeartAnimationFrame(player, 0);
	}

	private static void tickMilkLostHeartAnimations(MinecraftServer server) {
		if (server == null || MILK_ABSOLUTE_LOST_HEART_ANIMATIONS.isEmpty()) {
			return;
		}

		long nowTick = server.overworld().getGameTime();
		Iterator<Map.Entry<UUID, MilkLostHeartAnimationSession>> iterator = MILK_ABSOLUTE_LOST_HEART_ANIMATIONS.entrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, MilkLostHeartAnimationSession> entry = iterator.next();
			ServerPlayer player = server.getPlayerList().getPlayer(entry.getKey());
			if (player == null || player.connection == null) {
				iterator.remove();
				continue;
			}

			MilkLostHeartAnimationSession session = entry.getValue();
			long elapsed = Math.max(0L, nowTick - session.startTick());
			long animationTicks = (long) MILK_ABSOLUTE_LOST_HEART_ANIMATION_FRAME_COUNT * MILK_ABSOLUTE_LOST_HEART_ANIMATION_FRAME_TICKS;
			if (elapsed >= animationTicks) {
				player.connection.send(new ClientboundSetTitlesAnimationPacket(0, 0, 0));
				player.connection.send(new ClientboundSetSubtitleTextPacket(Component.empty()));
				iterator.remove();
				continue;
			}

			int frame = Math.min(
					MILK_ABSOLUTE_LOST_HEART_ANIMATION_FRAME_COUNT - 1,
					(int) (elapsed / MILK_ABSOLUTE_LOST_HEART_ANIMATION_FRAME_TICKS)
			);
			sendMilkLostHeartAnimationFrame(player, frame);
			if (frame != session.lastFrame()) {
				entry.setValue(new MilkLostHeartAnimationSession(session.startTick(), frame));
			}
		}
	}

	private static void sendMilkLostHeartAnimationFrame(ServerPlayer player, int frame) {
		if (player == null || player.connection == null) {
			return;
		}

		int clampedFrame = Math.max(0, Math.min(MILK_ABSOLUTE_LOST_HEART_ANIMATION_FRAME_COUNT - 1, frame));
		player.connection.send(new ClientboundSetTitlesAnimationPacket(0, MILK_ABSOLUTE_LOST_HEART_ANIMATION_FRAME_TICKS + 8, 0));
		player.connection.send(new ClientboundSetTitleTextPacket(Component.empty()));
		Component lostHeart = PolymerResourcePackUtils.hasMainPack(player)
				? Component.literal(new String(Character.toChars(MILK_ABSOLUTE_LOST_HEART_ANIMATION_FIRST_GLYPH + clampedFrame)))
						.withStyle(style -> style.withFont(MILK_ABSOLUTE_LOST_HEART_ANIMATION_FONT).withColor(0xFFFFFF).withItalic(false).withShadowColor(0x00000000))
				: Component.literal("\uD83D\uDC94").withStyle(style -> style.withColor(0xD6354A).withItalic(false));
		player.connection.send(new ClientboundSetSubtitleTextPacket(lostHeart));
	}

	private static void spawnMilkLostHeartDropParticles(ServerLevel level, ServerPlayer player) {
		if (level == null || player == null) {
			return;
		}

		RandomSource random = player.getRandom();
		double eyeY = player.getEyeY();
		double radius = Math.max(0.46D, player.getBbWidth() * 0.78D);
		for (int i = 0; i < MILK_ABSOLUTE_LOST_HEART_DROP_PARTICLE_COUNT; i++) {
			double angle = (Math.PI * 2.0D * i) / MILK_ABSOLUTE_LOST_HEART_DROP_PARTICLE_COUNT;
			double ringJitter = (random.nextDouble() - 0.5D) * 0.035D;
			double x = player.getX() + Math.cos(angle) * (radius + ringJitter);
			double y = eyeY + (random.nextDouble() - 0.5D) * 0.08D;
			double z = player.getZ() + Math.sin(angle) * (radius + ringJitter);
			double velocityX = Math.cos(angle) * 0.004D;
			double velocityY = -0.045D - random.nextDouble() * 0.035D;
			double velocityZ = Math.sin(angle) * 0.004D;
			level.sendParticles(MILK_ABSOLUTE_LOST_HEART_DROP_PARTICLE, x, y, z, 0, velocityX, velocityY, velocityZ, 1.0D);
		}
	}

	private static void tickMilkOligarchAttack(MinecraftServer server) {
		if (server == null) {
			return;
		}
		tickMilkLostHeartAnimations(server);
		long nowTick = server.overworld().getGameTime();
		Set<UUID> online = new HashSet<>();
		Iterator<UUID> iterator = MILK_ABSOLUTE_ATTACK_READY.iterator();
		while (iterator.hasNext()) {
			UUID playerId = iterator.next();
			ServerPlayer player = server.getPlayerList().getPlayer(playerId);
			if (player == null || !canUseMilkAbsoluteAttack(player)) {
				iterator.remove();
				if (player != null) {
					syncMilkAbsoluteAttackHud(player, false, true);
				}
				continue;
			}
			online.add(playerId);
			if ((nowTick + player.getId()) % MILK_ABSOLUTE_ATTACK_HUD_REFRESH_TICKS == 0L) {
				syncMilkAbsoluteAttackHud(player, true, true);
			}
		}

		Iterator<UUID> visibleIterator = MILK_ABSOLUTE_ATTACK_HUD_VISIBLE.iterator();
		while (visibleIterator.hasNext()) {
			UUID playerId = visibleIterator.next();
			if (online.contains(playerId) || MILK_ABSOLUTE_ATTACK_READY.contains(playerId)) {
				continue;
			}
			ServerPlayer player = server.getPlayerList().getPlayer(playerId);
			visibleIterator.remove();
			if (player != null) {
				player.connection.send(new ClientboundSetTitlesAnimationPacket(0, 0, 0));
				player.connection.send(new ClientboundSetTitleTextPacket(Component.empty()));
				player.connection.send(new ClientboundSetSubtitleTextPacket(Component.empty()));
			}
		}
	}

	private static void tickMilkOligarchDefense(MinecraftServer server) {
		if (server == null) {
			return;
		}
		tickOnlineCooldowns(server, MILK_DEFENSE_COOLDOWNS);
		if (MILK_DEFENSE_SESSIONS.isEmpty()) {
			return;
		}

		Iterator<Map.Entry<UUID, MilkDefenseSession>> iterator = MILK_DEFENSE_SESSIONS.entrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, MilkDefenseSession> entry = iterator.next();
			ServerPlayer player = server.getPlayerList().getPlayer(entry.getKey());
			MilkDefenseSession session = entry.getValue();
			ServerLevel level = session == null ? null : server.getLevel(session.dimension());
			if (player == null
					|| session == null
					|| level == null
					|| !player.level().dimension().equals(session.dimension())
					|| level.getGameTime() >= session.endTick()
					|| !canUseMilkDefense(player)) {
				iterator.remove();
			}
		}
	}

	private static void clearMilkAbsoluteAttack(ServerPlayer player) {
		if (player == null) {
			return;
		}
		MILK_ABSOLUTE_ATTACK_READY.remove(player.getUUID());
		syncMilkAbsoluteAttackHud(player, false, true);
	}

	private static void syncMilkAbsoluteAttackHud(ServerPlayer player, boolean active, boolean force) {
		if (player == null || player.connection == null) {
			return;
		}
		UUID playerId = player.getUUID();
		if (!active) {
			if (force || MILK_ABSOLUTE_ATTACK_HUD_VISIBLE.remove(playerId)) {
				player.connection.send(new ClientboundSetTitlesAnimationPacket(0, 0, 0));
				player.connection.send(new ClientboundSetTitleTextPacket(Component.empty()));
				player.connection.send(new ClientboundSetSubtitleTextPacket(Component.empty()));
			}
			return;
		}
		if (!force && MILK_ABSOLUTE_ATTACK_HUD_VISIBLE.contains(playerId)) {
			return;
		}
		player.connection.send(new ClientboundSetTitlesAnimationPacket(0, MILK_ABSOLUTE_ATTACK_HUD_STAY_TICKS, 0));
		player.connection.send(new ClientboundSetTitleTextPacket(Component.empty()));
		Component subtitle = PolymerResourcePackUtils.hasMainPack(player)
				? Component.literal(MILK_ABSOLUTE_ATTACK_INDICATOR_GLYPH)
						.withStyle(style -> style.withFont(MILK_ABSOLUTE_ATTACK_INDICATOR_FONT).withColor(0xFFFFFF).withItalic(false).withShadowColor(0x00000000))
				: Component.literal("\uD83D\uDC94").withStyle(style -> style.withColor(0xD6354A).withItalic(false));
		player.connection.send(new ClientboundSetSubtitleTextPacket(subtitle));
		MILK_ABSOLUTE_ATTACK_HUD_VISIBLE.add(playerId);
	}

	public static boolean shouldBlockMarkStockHealing(LivingEntity entity) {
		if (Boolean.TRUE.equals(MARK_STOCK_RESTORING_HEALTH.get()) || !(entity instanceof ServerPlayer player)) {
			return false;
		}
		return getMarkStockAbility(player) != null;
	}

	public static boolean shouldBlockMarkStockRestorativeEffect(LivingEntity entity, MobEffectInstance effect) {
		if (!(entity instanceof ServerPlayer player) || effect == null || getMarkStockAbility(player) == null) {
			return false;
		}
		Holder<MobEffect> effectType = effect.getEffect();
		return effectType.equals(MobEffects.REGENERATION)
				|| effectType.equals(MobEffects.INSTANT_HEALTH)
				|| effectType.equals(MobEffects.SATURATION)
				|| effectType.equals(MobEffects.ABSORPTION);
	}

	public static boolean shouldVoidMarkStockFood(ServerPlayer player, ItemStack stack) {
		return player != null
				&& stack != null
				&& !stack.isEmpty()
				&& stack.get(DataComponents.FOOD) != null
				&& getMarkStockAbility(player) != null;
	}

	public static void restoreMarkStockFoodAfterEating(ServerPlayer player, int beforeFood, float beforeSaturation) {
		if (player == null || player.getFoodData() == null || getMarkStockAbility(player) == null) {
			return;
		}
		player.getFoodData().setFoodLevel(Math.max(0, Math.min(20, beforeFood)));
		player.getFoodData().setSaturation(Math.max(0.0F, beforeSaturation));
		MARK_STOCK_FOOD_SNAPSHOTS.put(player.getUUID(), getFoodDataSnapshot(player));
	}

	public static boolean shouldBlockMilkStockPositiveEffect(LivingEntity entity, MobEffectInstance effect) {
		if (!(entity instanceof ServerPlayer player) || effect == null || getMilkStockAbility(player) == null) {
			return false;
		}
		UUID allowedPlayerId = MILK_STOCK_ENCHANTED_GOLDEN_APPLE_USER.get();
		if (player.getUUID().equals(allowedPlayerId)) {
			return false;
		}
		return isMilkStockPositiveEffect(effect.getEffect());
	}

	public static void beginMilkStockEnchantedGoldenAppleEffects(ServerPlayer player, ItemStack stack) {
		MILK_STOCK_ENCHANTED_GOLDEN_APPLE_USER.remove();
		if (player == null || stack == null || !stack.is(Items.ENCHANTED_GOLDEN_APPLE) || getMilkStockAbility(player) == null) {
			return;
		}
		MILK_STOCK_ENCHANTED_GOLDEN_APPLE_USER.set(player.getUUID());
	}

	public static void endMilkStockEnchantedGoldenAppleEffects(ServerPlayer player) {
		UUID allowedPlayerId = MILK_STOCK_ENCHANTED_GOLDEN_APPLE_USER.get();
		if (allowedPlayerId != null && (player == null || player.getUUID().equals(allowedPlayerId))) {
			MILK_STOCK_ENCHANTED_GOLDEN_APPLE_USER.remove();
		}
	}

	private static boolean isMilkStockPositiveEffect(Holder<MobEffect> effectType) {
		if (effectType == null) {
			return false;
		}
		return effectType.value().isBeneficial()
				|| effectType.equals(MobEffects.REGENERATION)
				|| effectType.equals(MobEffects.INSTANT_HEALTH)
				|| effectType.equals(MobEffects.ABSORPTION)
				|| effectType.equals(MobEffects.SATURATION)
				|| effectType.equals(MobEffects.HEALTH_BOOST);
	}

	public static boolean shouldSuppressMilkStockMobDetection(Mob mob, LivingEntity target) {
		if (!(target instanceof ServerPlayer player) || mob == null || getMilkStockAbility(player) == null) {
			return false;
		}
		return isMilkStockAffectedMob(mob) && !isMilkStockRetaliating(mob, player);
	}

	public static void handleMilkStockCombatDamage(ServerLevel level, LivingEntity victim, DamageSource damageSource, float damage, boolean applied) {
		if (!applied || level == null || victim == null || damageSource == null || damage <= 0.0F) {
			return;
		}
		LivingEntity attacker = resolveDamageAttacker(damageSource);
		if (!(attacker instanceof ServerPlayer player)
				|| player == victim
				|| getMilkStockAbility(player) == null) {
			return;
		}

		boolean markedAny = false;
		for (Mob mob : getMilkStockRetaliationGroup(victim)) {
			markMilkStockRetaliating(mob, player);
			markedAny = true;
		}
		if (!markedAny && victim instanceof Mob mob && isMilkStockAffectedMob(mob)) {
			markMilkStockRetaliating(mob, player);
		}
	}

	private static void markMilkStockRetaliating(Mob mob, ServerPlayer player) {
		if (mob == null || player == null || !mob.isAlive()) {
			return;
		}
		MILK_STOCK_RETALIATING_MOBS.put(mob.getUUID(), player.getUUID());
		mob.setLastHurtByMob(player);
		mob.setTarget(player);
		if (mob instanceof NeutralMob neutral && neutral.canAttack(player)) {
			neutral.setLastHurtByMob(player);
			neutral.setTarget(player);
			neutral.setPersistentAngerTarget(EntityReference.<LivingEntity>of(player));
			neutral.startPersistentAngerTimer();
		}
		if (mob instanceof Warden warden) {
			warden.increaseAngerAt(player, 150, false);
			warden.setAttackTarget(player);
		}
	}

	public static boolean shouldSuppressLittleDictatorMobDetection(Mob mob, LivingEntity target) {
		if (!(target instanceof ServerPlayer player) || mob == null || getLittleDictatorStockAbility(player) == null) {
			return false;
		}
		if (isLittleDictatorNeutralMob(mob)) {
			return true;
		}
		return isLittleDictatorHostileMob(mob) && !isLittleDictatorRetaliating(mob, player);
	}

	public static void handleLittleDictatorCombatDamage(ServerLevel level, LivingEntity victim, DamageSource damageSource, float damage, boolean applied) {
		if (!applied || level == null || victim == null || damageSource == null || damage <= 0.0F) {
			return;
		}
		LivingEntity attacker = resolveDamageAttacker(damageSource);
		if (!(attacker instanceof ServerPlayer player)
				|| player == victim
				|| getLittleDictatorStockAbility(player) == null) {
			return;
		}

		boolean handledAny = false;
		for (Mob mob : getMilkStockRetaliationGroup(victim)) {
			if (isLittleDictatorHostileMob(mob)) {
				markLittleDictatorRetaliating(mob, player);
				handledAny = true;
			} else if (isLittleDictatorNeutralMob(mob)) {
				markLittleDictatorNeutralFlee(level, mob, player);
				handledAny = true;
			}
		}
		if (!handledAny && victim instanceof Mob mob) {
			if (isLittleDictatorHostileMob(mob)) {
				markLittleDictatorRetaliating(mob, player);
			} else if (isLittleDictatorNeutralMob(mob)) {
				markLittleDictatorNeutralFlee(level, mob, player);
			}
		}
	}

	private static void tickLittleDictatorStock(MinecraftServer server) {
		if (server == null) {
			return;
		}
		cleanupLittleDictatorRetaliation(server);
		cleanupLittleDictatorNeutralFlee(server);

		List<ServerPlayer> dictatorPlayers = new ArrayList<>();
		for (ServerPlayer player : server.getPlayerList().getPlayers()) {
			if (player.isAlive() && !player.isSpectator() && getLittleDictatorStockAbility(player) != null) {
				dictatorPlayers.add(player);
			}
		}
		if (dictatorPlayers.isEmpty()) {
			return;
		}

		for (ServerPlayer player : dictatorPlayers) {
			ServerLevel level = player.level() instanceof ServerLevel serverLevel ? serverLevel : null;
			if (level == null) {
				continue;
			}
			AABB area = player.getBoundingBox().inflate(LITTLE_DICTATOR_MOB_SCAN_RADIUS_BLOCKS);
			Set<UUID> processed = new HashSet<>();
			for (Mob mob : level.getEntitiesOfClass(Mob.class, area, mob -> mob != null && mob.isAlive())) {
				if (!processed.add(mob.getUUID())) {
					continue;
				}
				if (isLittleDictatorNeutralMob(mob)) {
					clearLittleDictatorMobAggression(mob, player);
					if (shouldLittleDictatorNeutralFlee(level, mob, player)) {
						moveMilkStockMobAway(level, mob, getMilkStockMovementBody(mob), player, 6.0D, LITTLE_DICTATOR_NEUTRAL_FLEE_SPEED, false);
					}
					continue;
				}
				if (isLittleDictatorHostileMob(mob) && !isLittleDictatorRetaliating(mob, player)) {
					clearLittleDictatorMobAggression(mob, player);
				}
			}
		}
	}

	private static void cleanupLittleDictatorRetaliation(MinecraftServer server) {
		if (server == null || LITTLE_DICTATOR_RETALIATING_MOBS.isEmpty()) {
			return;
		}
		Iterator<Map.Entry<UUID, UUID>> iterator = LITTLE_DICTATOR_RETALIATING_MOBS.entrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, UUID> entry = iterator.next();
			Entity entity = findEntity(server, entry.getKey());
			ServerPlayer player = entry.getValue() == null ? null : server.getPlayerList().getPlayer(entry.getValue());
			if (!(entity instanceof Mob mob)
					|| player == null
					|| !mob.isAlive()
					|| !player.isAlive()
					|| player.isSpectator()
					|| player.level() != mob.level()
					|| getLittleDictatorStockAbility(player) == null
					|| !isLittleDictatorHostileMob(mob)) {
				iterator.remove();
				continue;
			}
			if (mob.getTarget() != player && mob.getLastHurtByMob() != player) {
				iterator.remove();
			}
		}
	}

	private static void cleanupLittleDictatorNeutralFlee(MinecraftServer server) {
		if (server == null || LITTLE_DICTATOR_NEUTRAL_FLEE_UNTIL.isEmpty()) {
			return;
		}
		long nowTick = server.overworld().getGameTime();
		Iterator<Map.Entry<UUID, Long>> iterator = LITTLE_DICTATOR_NEUTRAL_FLEE_UNTIL.entrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, Long> entry = iterator.next();
			Entity entity = findEntity(server, entry.getKey());
			if (!(entity instanceof Mob mob) || !mob.isAlive() || !isLittleDictatorNeutralMob(mob) || nowTick >= entry.getValue()) {
				iterator.remove();
			}
		}
	}

	private static void markLittleDictatorRetaliating(Mob mob, ServerPlayer player) {
		if (mob == null || player == null || !mob.isAlive()) {
			return;
		}
		LITTLE_DICTATOR_RETALIATING_MOBS.put(mob.getUUID(), player.getUUID());
		mob.setLastHurtByMob(player);
		mob.setTarget(player);
		if (mob instanceof NeutralMob neutral && neutral.canAttack(player)) {
			neutral.setLastHurtByMob(player);
			neutral.setTarget(player);
			neutral.setPersistentAngerTarget(EntityReference.<LivingEntity>of(player));
			neutral.startPersistentAngerTimer();
		}
		if (mob instanceof Warden warden) {
			warden.increaseAngerAt(player, 150, false);
			warden.setAttackTarget(player);
		}
	}

	private static void markLittleDictatorNeutralFlee(ServerLevel level, Mob mob, ServerPlayer player) {
		if (level == null || mob == null || player == null || !mob.isAlive()) {
			return;
		}
		clearLittleDictatorMobAggression(mob, player);
		LITTLE_DICTATOR_NEUTRAL_FLEE_UNTIL.put(mob.getUUID(), level.getGameTime() + LITTLE_DICTATOR_NEUTRAL_FLEE_TICKS);
		moveMilkStockMobAway(level, mob, getMilkStockMovementBody(mob), player, 6.0D, LITTLE_DICTATOR_NEUTRAL_FLEE_SPEED, false);
	}

	private static void clearLittleDictatorMobAggression(Mob mob, ServerPlayer player) {
		clearMilkStockMobAggression(mob, player);
		if (mob != null) {
			mob.setLastHurtByMob(null);
		}
	}

	private static boolean shouldLittleDictatorNeutralFlee(ServerLevel level, Mob mob, ServerPlayer player) {
		if (level == null || mob == null || player == null) {
			return false;
		}
		Long until = LITTLE_DICTATOR_NEUTRAL_FLEE_UNTIL.get(mob.getUUID());
		return until != null && until > level.getGameTime();
	}

	private static boolean isLittleDictatorNeutralMob(Mob mob) {
		return mob != null && mob.isAlive() && mob instanceof NeutralMob;
	}

	private static boolean isLittleDictatorHostileMob(Mob mob) {
		return mob != null
				&& mob.isAlive()
				&& !isMilkMouseSilverfish(mob)
				&& !(mob instanceof NeutralMob)
				&& (mob instanceof Enemy || mob.getType().getCategory() == MobCategory.MONSTER);
	}

	private static boolean isLittleDictatorRetaliating(Mob mob, ServerPlayer player) {
		return mob != null && player != null && player.getUUID().equals(LITTLE_DICTATOR_RETALIATING_MOBS.get(mob.getUUID()));
	}

	private static boolean canLittleDictatorAttackRedirectMob(Mob mob, LivingEntity target) {
		if (mob == null || target == null || !mob.isAlive() || mob == target) {
			return false;
		}
		if (!isLittleDictatorNeutralMob(mob) && !isLittleDictatorHostileMob(mob)) {
			return false;
		}
		if (mob.isPassengerOfSameVehicle(target) || target.isPassengerOfSameVehicle(mob)) {
			return false;
		}
		return mob.canAttack(target) || mob instanceof NeutralMob || mob instanceof Enemy || mob.getType().getCategory() == MobCategory.MONSTER;
	}

	private static void applyLittleDictatorAttackTarget(Mob mob, LivingEntity target) {
		if (mob == null || target == null || !mob.isAlive()) {
			return;
		}
		mob.setLastHurtByMob(target);
		mob.setTarget(target);
		if (mob instanceof NeutralMob neutral && target instanceof ServerPlayer targetPlayer && neutral.canAttack(targetPlayer)) {
			neutral.setPersistentAngerTarget(EntityReference.<LivingEntity>of(targetPlayer));
			neutral.startPersistentAngerTimer();
		}
		if (mob instanceof Warden warden) {
			warden.increaseAngerAt(target, 150, false);
			warden.setAttackTarget(target);
		}
	}

